window.__D("text/torat-shmuel/c032",{"p":[[2000460202,"<h3>[ששים המה מלכות] אך הנה כו' זית רענן יפה כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ צו שבת הגדול, ט\"ל).</b>\nדור הפלגה כו' טנת\"א כו' בכי' דלע\"ל\nצו\n<b>אך</b> הנה כדי שיוכלו לקבל התורה הי' צ\"ל תחלה גלות מצרים דוקא, וזהו כמשארז\"ל במד\"ר ר\"פ תצוה הה\"ד זית רענן<sup data-n=\"462\">1</sup> יפה פרי תואר קרא ה' שמך כו' מה הזית הזה עד שהוא באילנו מגרגרין אותו כו' וחובטן כו' וטוחנן כו' ואח\"כ נותנין שמנן, כך ישראל כו' חובטין<sup data-n=\"463\">2</sup> וחובשין וכופתין כו' ואח\"כ עושי' תשובה והקב\"ה עונה להם, מנין שנא' ויאנחו בנ\"י מן העבודה ויזעקו, וכן בצר לך ומצאוך, כי אל רחום ה' אלקיך, הוי זית רענן כו'.\n<b>ובזה</b> יובן ג\"כ מהו התירוץ וארא כו', על טענת משה למה הרעות כו', דהנה איתא בפע\"ח בשער חג המצות שישראל שהיו במצרים היו גלגול דור הפלגה<sup data-n=\"464\">3</sup>, ולכן מפני שחטאו בחומר ובלבני' כמ\"ש ותהי להם הלבינה לאבן, התיקון שלהם הי' וימררו את חייהם ע\"י עבודה בחומר ובלבנים, (וזהו שאמר להם פרעה ותוכן לבנים תתנו, שכמה לבנים שעשו בבנין העיר והמגדל דדור הפלגה יעשו ג\"כ במצרים לא תגרעו כו'). והנה לכאורה יש להקשות על הפרע\"ח",[["462","1","<b>אך הנה. . זית רענן</b>: מאמר זה הוא המשך להמאמר שלפנ\"ז ד\"ה ששים המה מלכות. וראה בהנסמן שם לכללות המאמר.\nעניני המאמר נמצאים בהמשך זאת חנוכת המזבח תר\"מ פרקים יד-כב. (סה\"מ תר\"ם ח\"א, הוצאת תשס\"ד, ע' נט ואילך). וראה גם [נוסף להנסמן לעיל ברד\"ה ששים המה] <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560403\" data-slug=\"or-hatorah-hb\" data-id=\"8316560403\">אוה\"ת נח (כרך ג) תרנד, א</a> ואילך. תרסח, א-ב. סה\"מ תר\"ל ע' ד ואילך. תרמ\"ג ע' ג ואילך. תרפ\"ו ע' פז ואילך. סה\"מ קונטרסים ח\"א קלט, ב ואילך.\nוראה לקמן בהנחת השומעים ממאמר זה, שבעת אמירת המאמר התחיל כ\"ק אדמו\"ר מהר\"ש מאמר זה עה\"פ ”ששים המה מלכות\". [וראה לקמן בסיום המאמר פיסקא: ”ובזה יובן מ\"ש אחת היא יונתי\" שהוא סיום הכתוב ”ששים המה מלכות\"]."],["463","2","<b>כך ישראל כו' חובטין</b>: בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש (בכת\"י מס' 1063) נכתב תחילה: כך ישראל באים אומות העולם כו' חובטין. ואח\"כ העביר הקולמוס על התיבות ”באים אומות העולם\" [וניכר שהוא שינוי מחמת הצענזור]."],["464","3","<b>איתא בפע\"ח בשער חגהמ\"צ שישראל שהיו במצרים היו גלגול דור הפלגה</b>: הובא ונת' באוה\"ת וארא שם ע' ב'תקנב."]]],[2000460203,"ממשארז\"ל בסנהדרין<sup data-n=\"465\">4</sup> דור הפלגה אין להם חלק לעוה\"ב ואין עומדין בדין<sup data-n=\"466\">5</sup>, וא\"כ איך היו ישראל שבמצרים גלגול דור הפלגה. אך הענין הוא דהנה עיקר עוה\"ב הוא תחה\"מ שיהי' נשמות בגופי' דוקא<sup data-n=\"467\">6</sup>, וע\"ז אמרו דור הפלגה אין להם חלק לעוה\"ב שלא יקומו בתחה\"מ אבל נשמתן נתקן<sup data-n=\"468\">7</sup> במצרים ע\"י השעבוד בחומר ובלבנים.\n<b>ולהבין</b> כ\"ז צ\"ל שרש ענין חטא דור הפלגה, הנה כתי' וירד ה' לראות את העיר ואת המגדל אשר בנו בני האדם וארז\"ל במד\"ר פל\"ח א\"ר ברכי' וכי בני חמרי' או גמלי' הם אלא בנוי דאדם קדמאה<sup data-n=\"469\">8</sup>, והיינו שבשרשן היו נשמות גבוהות רק שנפלו בשבירה והתחילו לבנות העיר והמגדל. וזהו ע\"ד ארי' מפני שבשרשו הוא גבוה לכן כשנפל למטה הוא חי' טמאה<sup data-n=\"470\">9</sup>. וענין העיר והמגדל הנה כתי' ותהי להם הלבינה לאבן, פי' אבן הוא בחי' אותיות וכמ\"ש בס\"י שתי אבנים בונות שתי בתים כו' ובהקבץ הרבה אבני' נעשה עיר, שהוא בחי' עיר אלקינו<sup data-n=\"471\">10</sup> כללות עולם הדבור שמחי' ומהוה כל הנבראי'. והנה כתי' כי מציון תצא תורה ודבר הוי' מירושלי'<sup data-n=\"472\">11</sup>, דבר",[["465","4","<b>יש להקשות על הפרע\"ח ממשארז\"ל בסנהדרין</b>: ראה עד\"ז בסה\"מ תרנ\"ה ס\"ע קג. וראה בהנסמן עוד לקמן."],["466","5","<b>ממשארז\"ל בסנהדרין דור הפלגה אין להם חלק לעוה\"ב ואין עומדין בדין</b>: כ\"ה גם בהמשך זאת חנוכת המזבח תר\"מ שם פי\"ד ופי\"ז. וראה בסה\"מ תרנ\"ה שם (ועד\"ז בד\"ה דרש כו' ויראו את אלקי ישראל בס' תרל\"א) בשם רש\"י ותויו\"ט בסנהדרין ק\"ז ע\"ב שדור הפלגה עומדין בדין אבל אין להם חלק לעוה\"ב. וכן לקמן בהנחות של המאמר כאן נזכר רק ”אין להם חלק לעוה\"ב\". וראה הל' ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670582\" data-slug=\"torat-chaim\" data-id=\"2300670582\">תו\"ח נח עה, ד</a>: ועכ\"ז דור הפלגה אין להם חלק לעוה\"ב שלא יהיו בחי' שפה ברורה כו' רק יקומו בדין להיות לחרפות ולדראון עולם וכן דור המבול כמ\"ש בזהר. ע\"כ. וראה בתשובות וביאורים הנסמן לקמן."],["467","6","<b>עיקר עוה\"ב הוא תחה\"מ שיהי' נשמות בגופי' דוקא</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380138\" data-slug=\"likkutei-torah\" data-id=\"4001380138\">לקו\"ת צו טו, ג</a>: העוה\"ב כו' לפ\"ד הרמב\"ם קאי על עולם הנשמות והרמב\"ן ז\"ל השיג עליו כו' ומסיק שקאי על זמן תחה\"מ. וראה סה\"מ תרל\"ג ח\"ב ע' תצ. וש\"נ."],["468","7","<b>וע\"ז אמרו. . אין להם חלק לעוה\"ב שלא יקומו בתחה\"מ אבל נשמתן נתקן</b>: בהמשך זאת חנוכת תר\"מ שם מוסיף: שפי' שגופן לא יתוקן לעולם. ועד\"ז בד\"ה עיר קטנה בסה\"מ תרנ\"ב שם: שהגופים לא יתתקנו, אבל הנשמה לבד בלא הגוף יש לה תיקון. וראה עד\"ז בתשובות וביאורים בקובץ ליובאוויטש ע' 35."],["469","8","<b>במד\"ר פל\"ח. . אלא בנוי דאדם קדמאה</b>: בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש (בכת\"י 1063 שם) נוסף כאן הגה\"ה: (פי' באותן ק\"ל שנים שפירש אדם היו הנקבות מתחממות מאדם כמ\"ש במד\"ר פ\"כ יעו\"ש). עכ\"ל. ואח\"כ העביר ע\"ז הקולמוס ורשם ע\"ז בגוכתי\"ק בצידי הגליון: אינו כן שהרי הרוחות שנולדו היו רוחות ולא נשמות בגופים כמו שהיו בדור הפלגה, ולכן נמחק. עכ\"ל. ובד\"ה עיר קטנה בסה\"מ תרנ\"ב שם: בנוי דאדם קדמאה היינו הנשמות שהוליד בק\"ל שנה שפירש מאשתו שהם נשמות גבוהות, וע\"י חטא דור הפלגה נפלו למטה והי' מהם יניקת החיצונים מפני התלבשות הנשמות בלבושים רעים, והוצרכו להתתקן ע\"י שעבוד מצרים."],["470","9","<b>ארי' מפני שבשרשו הוא גבוה. . למטה הוא חי' טמאה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370119\" data-slug=\"torah-or\" data-id=\"3901370119\">תו\"א וישלח כה, ג</a>. מאמרי אדה\"ז תקס\"ה ח\"א ע' סא ואילך. ביאוה\"ז לאדהאמ\"צ נ, ד. ובארוכה אוה\"ת וארא ע' קסד. ועוד."],["471","10","<b>אבן הוא בחי' אותיות. . שתי אבנים בונות שתי בתים. . עיר אלקינו</b>: ראה בכ\"ז בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370252\" data-slug=\"torah-or\" data-id=\"3901370252\">תו\"א וארא נו, ב</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370103\" data-slug=\"torah-or\" data-id=\"3901370103\">תו\"א ויצא כא, א</a>. כב, א. סה\"מ תרכ\"ז ע' שסה. ובכ\"מ."],["472","11","<b>והנה כתי' כי מציון תצא תורה ודבר הוי' מירושלים</b>: בהבא לקמן — ראה בארוכה סה\"מ תרכ\"ז ע' תיד. וס\"ע תטו ואילך. וש\"נ. וראה ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600099\" data-slug=\"or-hatorah-hb\" data-id=\"8316600099\">אוה\"ת נ\"ך (כרך א) ע' צט</a>."]]],[2000460204,"הוי' הוא בחי' עיר אלקינו עולם הדבור הוא מבחי' ירושלי', ומציון שהיא פנימיות ירושלים תצא תורה הוא בחי' אותיות התורה, שהתורה היא תורת הוי' שזהו ענין המגדל שהוא בחי' מגדל עוז שם הוי'. וזהו מ\"ש גדול הוי' ומהולל מאד בעיר אלקינו, שבחי' הוי' ואלקי' הוא ענין עיר ומגדל בקדושה. וזה\"ע חתן וכלה, כלה הוא בחי' העלאה מלמטלמ\"ע, וחתן הוא בחי' המשכה מלמעלמ\"ט, שהם אותיות התורה ואותיות התפלה אתוון נוקבין ואתוון דוכרין.\n<b>אך</b> הנה כדי שנוכל לקבל מבחי' זו צ\"ל בבחי' יראה וביטול דוקא כמ\"ש את האלקי' ירא, שכדי לקבל מבחי' הוי' ואלקי' עיר ומגדל דקדושה צ\"ל בבחי' יראה וביטול דוקא. אמנם הנה דור הפלגה ידעו היטב שההשפעה צ\"ל מבחי' עיר ומגדל דקדושה, ושצ\"ל בבחי' ביטול דוקא, והם לא רצו בהביטול, לזה עשו העיר והמגדל בלעו\"ז. וזהו שלום יהי' לי כי בשרירות לבי אלך, פי' הגם כי בשרירות לבי אלך אעפ\"כ שלום יהי' לי, והיינו שרצו להמשיך להם השפעת גשמי' ע\"י בחי' עיר ומגדל דלעו\"ז. וזהו ותהי להם הלבנה לאבן, אבן הוא בחי' אותיות א' ב\"ן<sup data-n=\"473\">12</sup>, פי' שאל\"ף הוא מבחי' ש' מ\"ה שהוא במלוי אלפי\"ן שמברר ב\"ן, שזהו בקדושה, והם עשו תמורת אבן זה בחי' לבינה<sup data-n=\"474\">13</sup> שהוא מל' דנוגה, שהוא ג\"כ בחי' אותיות המחיי' בבחי' מקיף כמו שמצינו בחי' השבעת השמות וקבלה מעשיות<sup data-n=\"475\">14</sup> שמשביע בשם פלוני שיהי' הדבר כן כו', ורצו להוסיף חיות בקליפות ולהרוס בנין הקדושה, וזהו ושפחה כי תירש גבירתה. ויש בבחי' אותיות אלו ג\"כ העלאה והמשכה, שזהו משארז\"ל הרהורי עבירה כו', אדם מטמא עצמו מעט מלמטה מטמאין אותו הרבה מלמעלה. ולזה גדלה חטאתם עד מאד, ויפץ ה' אותם, ומשם הפיצם לעוה\"ב שלא יקומו בתחה\"מ. ועד\"ז הוא ענין עיר הנדחת שאין להם חלק לעוה\"ב, ויש בזה ב' דעות בגמ' סנהדרין דע\"א, הא' שעיר הנדחת לא היתה ולא עתידה להיות, וא' אמר אני ישבתי על תילה, הגם שנא' כי לא ידח ממנו נדח, אבל עיר הנדחת שעשו כל אנשי העיר הסכם כו'<sup data-n=\"476\">15</sup> ה\"ז כמו ענין חטא דור הפלגה.\n<b>והנה</b> תיקון נשמתם של דור הפלגה<sup data-n=\"477\">16</sup> הי' במצרים ע\"י עבודתם בחומר ובלבנים, ובזה נסתלק טענת משה העם הזה מה חטאו, שהם היו גלגול דור הפלגה,",[["473","12","<b>אבן הוא בחי' אותיות א' ב\"ן</b>: ראה שעהיוה\"א פ\"ז (פד, ב). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370347\" data-slug=\"torah-or\" data-id=\"3901370347\">תו\"א משפטים שם עח, סע\"ב</a>-ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380826\" data-slug=\"likkutei-torah\" data-id=\"4001380826\">לקו\"ת ראה כז, ג</a>. ועוד."],["474","13","<b>וזהו ותהי להם הלבנה לאבן. . עשו תמורת אבן. . לבנה</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370344\" data-slug=\"torah-or\" data-id=\"3901370344\">תו\"א משפטים עז, ג</a>-<a class=\"ft-cite\" href=\"#/read/torah-or/3901370347\" data-slug=\"torah-or\" data-id=\"3901370347\">ד. עח, ב</a>-ג. ובדרושים שנסמנו לעיל בתחילת המאמר. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061015\" data-slug=\"likkutei-sichot\" data-id=\"1300061015\">לקו\"ש ח\"ו ע' 15</a> ואילך."],["475","14","<b>כמו שמצינו בחי' השבעת השמות וקבלה מעשיות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370042\" data-slug=\"torah-or\" data-id=\"3901370042\">תו\"א נח י, ב</a>. אוה\"ת מטות ע' א'רפט. סה\"מ תרל\"ב ח\"ב ע' תקצו. [ובדרושים שנסמנו לעיל בתחילת המאמר]. וראה בהמובא ע\"ז באוה\"ת וארא שם ע' ב'תקסח. ובהמשך זאת חנוכת המזבח תר\"מ פי\"ז (סה\"מ תר\"ם ח\"א ע' ע ואילך)."],["476","15","<b>הסכם כו'</b>: בד\"ה עיר קטנה בסה\"מ תרכ\"ו נדפס: הסכם לעבוד כו'."],["477","16","<b>והנה תיקון נשמתם של דור הפלגה</b>: בהמשך זאת חנוכת המזבח תר\"מ (שם ע' עג) מתחיל כאן פרק יח."]]],[2000460205,"וע\"י השעבוד זכו למ\"ת, כי היו בחי' אבן בוחן<sup data-n=\"478\">17</sup> וכמ\"ש בזהר פ' שלח דקס\"ח ע\"א במאמר רב מתיבתא, אעא דלא שלטא בה נורא<sup data-n=\"479\">18</sup> מבטשין לי' ואנהר, גופא דלא שלטא בי' נהורא דנשמתא מבטשין בי' ויסלק בי' נהורא כו', סט\"א בעי למעבד הכי ובטש בחייביא, וכל מה דבטש כדין נר רשעים ידעך מחרף ומגדף לכל סטרין ולא יכיל לאנהרא כלל כו', ועל דא ה' צדיק יבחן ובטש בי' וכדין נהיר ואתקיף בנהירא, יבחן כד\"א אבן בוחן. והיינו לפי ששרש הגוף הוא מבחי' התהו שנפל בשבירה וע\"י הבירור בבחי' ביטול היש עי\"ז נמשך בחי' אורות דתהו, סט\"א בעי למעבד הכי ולא יכלית, כי בקדושה דוקא הוא בחי' שמאלו תחת לראשי שע\"י בחי' שמאל דוחה מגעת לבחי' ראשי כו', אבל בסט\"א לא כן הוא כו'. ועיקר המכוון מהשעבוד הי' להיות בחי' וגם אני שמעתי את נאקת בנ\"י שהוא מ\"ש ותעל שועתם אל האלקי' מן העבודה ויזעקו, כי בצר לך ומצאוך ושבת כו', מן המצר קראתי י\"ה, כי הנה מים תחתוני' בוכים אנן בעינן למהוי קדם מלכא, והיינו שהבכי' הוא ע\"י הרקיע המבדיל בין מים למים, וכמו\"כ ע\"י בכיית נש\"י מן העבודה עי\"ז הי' במ\"ת גילוי בחי' ש' הוי' דלעילא ולא הי' בחי' פסיק טעמא, כי ע\"י הבכי' מתעורר רחמים רבים, כי יש ב' בחי' רחמים, הא' בחי' רחמים שבסדר השתלשלות שיש מדת הדין כנגדה, וזהו ה' רחום וחנון, אבל יש בחי' רחמים רבים שלמעלה מבחי' השתלשלו' וזהו חנון ורחום ה'<sup data-n=\"480\">19</sup> בחי' ברחמיך הרבים לא עשיתם כלה, וע\"י הבכי' מתעורר רחמים רבים להיות גילוי ש' הוי' דלעילא במ\"ת. וזהו מי בכים ר\"ת ברוך כבוד הוי' ממקומו<sup data-n=\"481\">20</sup>, פי' שע\"י הבכי' ממשיכים ש' הוי' ממקומו דוקא. וזהו מ\"ש לכן אמור לבנ\"י אני הוי', שבמ\"ת הי' גילוי ש' הוי' דלעילא ע\"י השעבוד שלהם.\n<b>והנה</b> לע\"ל נאמר ג\"כ בבכי יבאו<sup data-n=\"482\">21</sup> ובתחנוני' אובילם, וצ\"ל ענין הבכי' דלעתיד. הנה כתי' כימי צאתך מאמ\"צ אראנו נפלאות, כי הנה כתי' ובלילה שירה עמי<sup data-n=\"483\">22</sup>, פי' שירה, כי דוד שאמר זמירות היו לי חוקיך א\"ל דוד זמירות קרית להו<sup data-n=\"484\">23</sup>, והיינו כי יש בחי' בתורה שלמעלה מבחי' זמירות שהוא בחי' טעמי תורה, כי באותיות יש ד' בחי'",[["478","17","<b>בחי' אבן בוחן</b>: ראה אוה\"ת וארא שם ס\"ע ב'תקסז. בהמשך זאת חנוכת תר\"מ שם מפרש (פי' אבן בוחן): והיינו שע\"י אבן זה נבחנו ישראל."],["479","18","<b>וכמ\"ש בזהר פ' שלח. . אעא דלא שלטא בה נורא</b>: הובא ונת' ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310034\" data-slug=\"tanya\" data-id=\"3401310034\">תניא פכ\"ט (לה, סע\"ב</a>) בשינויים. וראה גם לעיל ד\"ה זאת חוקת."],["480","19","<b>ה' רחום וחנון. . אבל יש בחי' רחמים רבים. . וזהו חנון ורחום ה'</b>: ראה בארוכה לקו\"ת ואתחנן ג, א. מאמרי אדה\"ז תקס\"ד ע' רכ. מאמרי אדהאמ\"צ נ\"ך ע' תקפא ואילך. יהל אור לתהלים ע' תרעז. אוה\"ת תשא ע' ב'מו. ואתחנן ע' נד. וע' ס. סה\"מ תרל\"ג ח\"ב ע' תכו."],["481","20","<b>מים תחתונים בוכים. . בכים ר\"ת ברוך כבוד הוי' ממקומו</b>: ראה בכ\"ז סה\"מ תרכ\"ו ס\"ע יט ואילך. ע' לג ואילך. וע' נח-ט. ועוד."],["482","21","<b>והנה לע\"ל נאמר ג\"כ בבכי יבואו</b>: בהבא לקמן ראה המשך זאת חנוכת תר\"מ שם פ\"כ ורפכ\"א."],["483","22","<b>כי הנה כתי' ובלילה שירה עמי</b>: בהבא לקמן — ראה [נוסף להנסמן לעיל בתחילת המאמר] <a class=\"ft-cite\" href=\"#/read/torah-or/3901370147\" data-slug=\"torah-or\" data-id=\"3901370147\">תו\"א מקץ לא, סע\"ג</a> ואילך. תו\"ח מקץ עח, ד ואילך."],["484","23","<b>דוד שאמר זמירות. . זמירות קרית להו</b>: ראה בארוכה קו\"א לתניא ד\"ה דוד זמירות קס, א ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380380\" data-slug=\"likkutei-torah\" data-id=\"4001380380\">לקו\"ת במדבר יח, א</a> ואילך. דרמ\"צ מא, א ואילך. סה\"מ תרכ\"ז ע' רצד. וש\"נ."]]],[2000460206,"טנת\"א שהם כנגד דצח\"מ<sup data-n=\"485\">24</sup>, אותיות הם דוממין, ותגין הוא בחי' צומח, נקודות הוא בחי' חי, וטעמים הוא בחי' מדבר.\n<b>והנה</b> בתורה הנגלית<sup data-n=\"486\">25</sup> אינו נמשך הגילוי כ\"א מבחי' נת\"א<sup data-n=\"487\">26</sup>, שזהו מ\"ש ששים המה מלכות כו' הוא בחי' תושבע\"פ אינה כ\"א מבחי' אותיות התורה כמשארז\"ל מ\"ט אמר קרא, וגם מבחי' תגין יש ג\"כ בתושבע\"פ כמשארז\"ל ר\"ע הי' דורש על כל קוץ וקוץ תלי תלים של הלכות, וגם מבחי' נקודות כמשארז\"ל יש אם למקרא יש אם למסורת. אבל מבחי' טעמים לא נתגלה בתושבע\"פ<sup data-n=\"488\">27</sup>, והיינו לפי ששרש אותיות התורה הוא מבחי' מדות עליונו' בחי' חג\"ת, דהנה אותיות הם בחי' כלים שע\"י נמשך השכל לידי גילוי לזולתו, שא\"א להשיג השכל בלתי אותיות, ולכך אנו רואים שאף מי שהוא בר שכל גדול אם אין לו אותיות אינו יכול להמשיך השכל לזולתו, לפי שגילוי השכל הוא דוקא ע\"י אותיות שהם בחי' כלים. אך הנה כדי שיומשך השכל באותיות זהו ע\"י צמצום, שתחלה נתצמצם השכל, לפי שעצמיות השכל כמו שהוא אינו יכול להיות נמשך באותיות, וכמו למשל יין שהוא בחבית גדולה א\"א לשתות ממנו כ\"א ע\"י שממשיכי' בכלים קטנים שנתצמצם ההשפעה כו', וכך כדי שיומשך השכל באותיות זהו ע\"י צמצום, ואח\"כ התפשטות והמשכה. וזהו ענין שהאותיות הם במדות חג\"ת לפי שע\"י ג' מדות חג\"ת שהוא בחי' צמצום והתפשטות והמשכה עי\"ז נמשך השכל באותיות כו' (וע' מענין ג' בחי' חג\"ת שהם בחי' ג' ידות שהם צמצום והתפשטות והמשכה בלק\"ת בביאור ע\"פ נשא את ראש<sup data-n=\"489\">28</sup> פ\"א ופ\"ב). אך הנה תגין הם למעלה מאותיות, כי תגין הם בבחי' כתרי אותיות, וכמשארז\"ל ודאשתמש בתגא<sup data-n=\"490\">29</sup> חלף, כל המשתמש בכתרה של תורה, וכן ארז\"ל שמצאו משה להקב\"ה שקושר כתרים לאותיות, והיינו לפי שתגין שרשן מבחי' בינה, ות\"ת דאימא נעשה כתר לז\"א. ונקודות הם בחכ', כי יו\"ד שהוא בחי' חכ' הוא בחי' נקודה, ולזה התיבה נשתנה לפי הנקודה, כמו למשל אותיות אב, אם הוא בנקודת פתח אז הוא פי' אב, ואם הוא בנקודה אחרת אז הוא פי' אחר ממש, והיינו לפי שנקודות הם בחכ'. והנה השכל הוא מנהיג את המדות, ולכך הנקודות הם מוליכים ומנהיגים להאותיות שהם בבחי' מדות, וזהו ענין נקודה בהיכלא שהעיקר הוא בחי' הנקודה שההיכל מתנהג עפ\"י הנקודה.",[["485","24","<b>טנת\"א שהם כנגד דצח\"מ</b>: ראה גם לקו\"ת חוקת נז, ד."],["486","25","<b>והנה בתורה הנגלית</b>: בהבא לקמן בפיסקא זו ראה המשך זאת חנוכת המזבח תר\"מ שם פכ\"א."],["487","26","<b>באותיות יש ד' בחי' טנת\"א </b>[טעמים נקודות תגין אותיות]<b>. . נת\"א </b>[נקודות תגין אותיות]: ראה בכ\"ז בארוכה באוה\"ת וארא שם ע' ב'תקנח ואילך. ב'תקעב ואילך. המשך זאת חנוכת המזבח תר\"מ שם פכ\"א. תו\"א ותו\"ח מקץ שם."],["488","27","<b>מבחי' טעמים לא נתגלה בתושבע\"פ</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380235\" data-slug=\"likkutei-torah\" data-id=\"4001380235\">לקו\"ת אמור לז, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381103\" data-slug=\"likkutei-torah\" data-id=\"4001381103\">ברכה צד, סע\"א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381107\" data-slug=\"likkutei-torah\" data-id=\"4001381107\">צה, א</a>."],["489","28","<b>בלק\"ת בביאור ע\"פ נשא את ראש</b>: כא, ג-ד. וראה גם סה\"מ תרל\"ג ח\"ב ע' שסה ואילך."],["490","29","<b>תגין. . בבחי' כתרי אותיות וכמשארז\"ל ודאשתמש בתגא</b>: ראה גם אגה\"ק סכ\"ט (קמח, ב. קנא, א)."]]],[2000460207,"<b>אך</b> הנה טעמים הם למעלה מבחי' חכ', כי שרש הטעמים הם בכתר<sup data-n=\"491\">30</sup> שהוא בחי' תענוג כו', שהתענוג הוא למעלה מבחי' חכ', וכמ\"ש אז תתענג על הוי' שהוא למעלה מבחי' שם הוי'<sup data-n=\"492\">31</sup> שהוא בחכ' וכמ\"ש הוי' בחכ' כו'. וזהו שאנו רואים למשל באדם שכשנופל לו שכל חדש אז הוא מתמלא תענוג, ואח\"כ כשנתיישן השכל נפסק התענוג, והיינו לפי שבעת שנפל לו השכל אז הוא נמשך מבחי' משכיל שהוא מקור השכל ששם השראת התענוג, ולכך בעת נפילת השכל אז נמשך לו התענוג לפי שאז הוא קרוב להתענוג, אבל אח\"כ כשנתיישן השכל אז הוא נתרחק ממקורו ולכך נפסק התענוג. וכמו למשל מים חיים שאינם נק' מים חיים כ\"א במעיין שמשם הוא נובע, משא\"כ אלו המים כשנמשכי' בנהר שאז מתרחקי' ממקורם אינם נקראי' מים חיים, נמצא שטעמים הם בכתר. והגם שמבואר במ\"א שטעמים הם בחכ'<sup data-n=\"493\">32</sup>, אך הנה שניהם אמת, והיינו כשאומרים שהאותיות הם במל' אז הטעמי' הם בחכ', אבל כשאומרים שהאותיו' הם במדות שהוא בחי' אותיות התו' שהם למעלה מבחי' אותיות שהם מקור לעולמות בחי' בדבר הוי' שמים נעשו, אז הטעמים הם בכתר. והיינו שיש שני בחי' טעם, כי יש טעם הגלוי שבחי' טעם זה הוא בחכ', ויש בחי' טעם הכמוס<sup data-n=\"494\">33</sup> שהוא ע\"ד שארז\"ל שתוק כך עלה במח', שבחי' טעם זה הוא בכתר.\n<b>והנה</b> לע\"ל יהי' התגלות בחי' טעמי תורה, שעתה לא נתגלו, ולע\"ל יהיו נמשכים בבחי' גילוי, וכדי שיומשכו בבחי' גילוי זהו ע\"י בכי' דוקא שהוא בחי' התעוררות רחמים רבים, וכמ\"ש בחנה ותתפלל חנה על הוי' למעלה מבחי' שם הוי'<sup data-n=\"495\">34</sup>, והיינו לפי שחנה התפללה על הבנים, והנה בני חיי ומזוני לאו בזכותא תלי' אלא במזלא תליא<sup data-n=\"496\">35</sup> שהוא למעלה מבחי' שם הוי' שהוא בחי' חכ', וכמ\"ש בזהר אבא יונק ממזלא, וכדי שיומשך מלמעלה מבחי' שם הוי' זהו ע\"י בכי' וכמ\"ש שם ותתפלל חנה כו' ובכה תבכה, שע\"י בכי' עי\"ז נמשך מלמעלה מבחי' שם הוי'. וזהו מ\"ש ג\"כ בבכי יבאו שע\"י בכי' דוקא יהי' בחי' התגלות טעמי תורה שהוא בחי' תענוג הפשוט ואהי' אצלו שעשועי' יום יום שהוא בחי' שעשועי' העצמי'. וזהו ובלילה שירה עמי דהיינו שע\"י הלילה דוקא בחי' בכה תבכה בלילה עי\"ז נמשך בחי' שירה עמי בחי' טעמי תורה כו'. וזהו כימי צאתך מאמ\"צ אראנו נפלאות שהוא בחי' טעמי תורה כו', שיצ\"מ הי' דוקא ע\"י חומר ולבנים שהוא בחי' בכי' התעוררות רחמים רבים, כך לע\"ל ע\"י",[["491","30","<b>ונקודות הם בחכ'. . שרש הטעמים הם בכתר</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380238\" data-slug=\"likkutei-torah\" data-id=\"4001380238\">לקו\"ת אמור לח, א</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370092\" data-slug=\"torah-or\" data-id=\"3901370092\">תו\"א תולדות יט, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370121\" data-slug=\"torah-or\" data-id=\"3901370121\">וישלח כו, א</a>."],["492","31","<b>וכמ\"ש אז תתענג על הוי'. . למעלה מבחי' שם הוי'</b>: ראה בארוכה סידור עם דא\"ח קעג, ב ואילך. וראה גם לקו\"ת דרושים לשמע\"צ פה, א. ועוד."],["493","32","<b>והגם שמבואר במ\"א שטעמים הם בחכ'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370218\" data-slug=\"torah-or\" data-id=\"3901370218\">תו\"א ויחי מח, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370237\" data-slug=\"torah-or\" data-id=\"3901370237\">שמות נג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380090\" data-slug=\"likkutei-torah\" data-id=\"4001380090\">לקו\"ת ויקרא ד, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380354\" data-slug=\"likkutei-torah\" data-id=\"4001380354\">במדבר יא, רע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380547\" data-slug=\"likkutei-torah\" data-id=\"4001380547\">חוקת נז, ד</a>. ובכ\"מ. וראה אוה\"ת וארא שם ע' ב'תקעה."],["494","33","<b>שיש שני בחי' טעם. . טעם הגלוי. . טעם הכמוס</b>: ראה בארוכה ביאוה\"ז לאדהאמ\"צ פח, ב. ולהצ\"צ ח\"ב ע' תתקעא. וש\"נ. סה\"מ תרל\"ב ח\"ב ע' שצד. ובכ\"מ."],["495","34","<b>ותתפלל חנה על הוי' למעלה מבחי' שם הוי'</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370350\" data-slug=\"torah-or\" data-id=\"3901370350\">תו\"א משפטים עט, סע\"א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380912\" data-slug=\"likkutei-torah\" data-id=\"4001380912\">לקו\"ת נצבים מח, ב</a>. ועוד."],["496","35","<b>בני חיי ומזוני. . במזלא תליא</b>: ראה בכ\"ז בארוכה מאמרי אדה\"ז תקס\"ג ח\"א ע' כה ואילך. מארז\"ל ע' קצח. וע' רג. ביאוה\"ז לאדהאמ\"צ יא, ב ואילך. ולהצ\"צ ח\"א ע' מד ואילך. ח\"ב ע' תרלז-ח. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490172\" data-slug=\"or-hatorah-hb\" data-id=\"8316490172\">אוה\"ת וירא (כרך ד) תשנה, ב</a> ואילך. ד\"ה וה' פקד בסה\"מ תרל\"א. וש\"נ. סה\"מ תרל\"ג ח\"א ע' רלח-ט."]]],[2000460208,"הבכי' אראנו נפלאות שהוא בחי' טעמי תורה הוא ג\"כ ע\"י בכי' דוקא ובלילה שירה עמי כנ\"ל.\n<b>ובזה</b> יובן מ\"ש אחת היא יונתי<sup data-n=\"497\">36</sup>, שכנס\"י נק' בחי' אחת שלמעלה מבחי' תורה שהם ששים מלכות, ובמ\"א מבואר שהתורה היא למעלה מישראל<sup data-n=\"498\">37</sup>, והיינו לפי שאחת היא בחי' כלי לאחד, והיינו ע\"י שארז\"ל למסור נפשו באחד, והנה מס\"נ היא למעלה מן הטו\"ד שהוא למעלה מבחי' חכ' כי ע\"פ טו\"ד נא' לאהבה את הוי' אלקיך כו' כי הוא חייך<sup data-n=\"499\">38</sup>, אך מס\"נ הוא למעלה מבחי' חכ', ועי\"ז מגיע למעלה ג\"כ למעלה מבחי' חכ', שהוא מגיע למעלה בבחי' תענוג הפשוט שהוא בחי' טעמי תורה בחי' שירה כו' שהוא למעלה מבחי' תורה כו', כי שרש התו' היא מבחי' חכ' כי אורייתא מח\"ע נפקת, אבל ע\"י מס\"נ מגיע למעלה מבחי' חכ', וע\"י מס\"נ נמשך המשכה בבחי' חכ' מלמעלה מן החכ' שהוא בחי' כתר. ולזה כשכנס\"י הם בבחי' זו הם למעלה מבחי' התורה, כי הם משפיעים וממשיכי' בבחי' תורה. ומ\"ש ישראל מתקשראן באוריי', זהו נש\"י כשהם למטה במדרגה שאינם בבחי' אחת שאין להם בחי' מס\"נ, אז הם מקבלים מבחי' תורה שהתו' היא למעלה מהם, כי שרש נש\"י הם מושרשים בז\"א משא\"כ התו' היא בחכ' כו', אך כשהם בבחי' אחת שעבודתם בבחי' מס\"נ אז הם למעלה מהתו'. וזהו ע\"ד משארז\"ל מט\"ט קושר כתרים לקונו מתפלותיהן של ישראל, והיינו כי תפלה הוא בקשת יהי רצון שיומשך בחי' רצון חדש<sup data-n=\"500\">39</sup> שלמעלה מן החכ', שאף שחייבה חכמתו יסורי' ודינין וכמשארז\"ל אין יסורים בלא עון, אעפ\"כ אנו מבקשי' יהי רצון שיכבשו רחמיך את כעסך מעלינו, והיינו לפי שהתפלה מגיע למעלה בבחי' כתר שהוא בחי' רעוא דכל רעוין ויכול להיות נמשך משם המשכת רצון חדש כו'. אך כ\"ז הוא כשהתפלה היא בבחי' אחת היא יונתי שהוא בחי' מס\"נ, עי\"ז התפלה מגיע בבחי' כתר ולזה אף שעפ\"י התורה צריך להיות בחי' יסורין ודינין, אבל ע\"י המשכת בחי' כתר, עי\"ז נמתקו הדינין כו'. והנה הגם שמבואר למעלה שמ\"ת הי' ג\"כ בחי' המשכת ש' הוי' דלעילא, אבל עכ\"ז הי' הגילוי רק מבחי' יו\"ד של ש' הוי' שהוא בחי' חכ', אבל טעמי תורה לא נתגלו, משא\"כ לע\"ל יהי' הגילוי בחי' טעמי תורה מבחי' שם הוי' דלעילא כו'.",[["497","36","<b>ובזה יובן מ\"ש אחת היא יונתי</b>: המשך הכתוב ”ששים המה מלכות\" (שה\"ש ו, ט) דלעיל בתחילת המאמר שלפנ\"ז. בהבא לקמן עד סוף המאמר ראה ד\"ה ששים המה מלכות ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381281\" data-slug=\"likkutei-torah\" data-id=\"4001381281\">לקו\"ת שה\"ש לח, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381283\" data-slug=\"likkutei-torah\" data-id=\"4001381283\">לח, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381286\" data-slug=\"likkutei-torah\" data-id=\"4001381286\">לט, סע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381295\" data-slug=\"likkutei-torah\" data-id=\"4001381295\">וראה גם שם מא, ד</a> ואילך. אוה\"ת שה\"ש (כרך ג) ע' תתקמג. תתקמו. תתקנח-ט. וראה גם אוה\"ת וארא שם ע' ב'תקעג."],["498","37","<b>ובמ\"א מבואר שהתורה היא למעלה מישראל</b>: בכ\"ז ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381196\" data-slug=\"likkutei-torah\" data-id=\"4001381196\">לקו\"ת שה\"ש טז, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381200\" data-slug=\"likkutei-torah\" data-id=\"4001381200\">שם יז, ד</a> ואילך. סה\"מ תרכ\"ט ע' קמה ואילך. [ובהנסמן שם בתחילת המאמר]."],["499","38","<b>מס\"נ הוא למעלה מן הטו\"ד. . כי ע\"פ טו\"ד נא' לאהבה. . כי הוא חייך</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370443\" data-slug=\"torah-or\" data-id=\"3901370443\">תו\"א מג\"א צט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380092\" data-slug=\"likkutei-torah\" data-id=\"4001380092\">לקו\"ת ויקרא ד, ג</a>. ובכ\"מ."],["500","39","<b>מט\"מ קושר כתרים. . תפלה הוא בקשת יהי רצון שיומשך בחי' רצון חדש</b>: ראה בכ\"ז סה\"מ תרכ\"ז ע' רצד. שצא. וע' תסו. וש\"נ. תרכ\"ט ע' ג. וש\"נ. תרל\"ג ח\"א ע' ב. וש\"נ."]]],[2000460209,"<h3>וככה תאכלו כו'</h3>\n<b></b><b>בס\"ד. פ' בא י\"ב. י\"א.</b>\n<b></b>יצי\"מ וגאולה דלע\"ל ד' הפרשים כו'\n<b>מתניכם חגורים - י\"ד [י\"א] פרקים ז' קיצורים</b>\nוככה<sup data-n=\"e15\">*</sup> תאכלו אותו<sup data-n=\"501\">1</sup> מתניכם חגורים, מד\"ר קל\"ו ג'<sup data-n=\"502\">2</sup> ס\"פ בא ס\"פ י\"ט כשאכלו ישראל את הפסח במצרים אכלו אותו בחפזון שנא' וככה תאכלו אותו על שם כי בחפזון יצאת מאמ\"צ, אבל לע\"ל כי לא בחפזון תצאו ובמנוסה לא תלכון ישעי' סי' נ\"ב. וע' מזה ג\"כ בילקוט פ' בא רמז קצ\"א למה הדבר דומה לסוחר שנכנס לשרות בפונדק עמד שם כל היום, בלילה עמד ונטל כל אשר לו ויצא לדרכו, עמדה הפונדקית בבקר והתחילה צווחת ראו הפרגמטוטוס עמד בלילה ונטל כל אשר לי ויצא לו, שמע הפרגמטוטוס ואמר מי גרם לי לשמוע כך אלא מפני שיצאתי בלילה לפיכך נשבע אני שלא אצא בלילה עוד, כך התקינו ישראל עצמן בלילה לצאת<sup data-n=\"e16\">*</sup>",[["501","1","<b>וככה תאכלו אותו</b>: ראה מאמר זה בשינויים קלים באוה\"ת בא ע' רחצ ואילך.\nבהערת כ\"ק אדמו\"ר זי\"ע (נדפס לעיל ע' 7) מציין על מאמר זה ”אולי הוא — ע\"פ הסגנון — דרוש מהצ\"צ. הפרקים ח'-יו\"ד לא מצאתי. כן לא ראיתי קצורים אלא לז' פרקים הראשונים\". אולם לאח\"ז הגיעו כמה כת\"י של מאמרי הצ\"צ, שם נמצא מאמר זה בשינויים קלים, ונדפס באוה\"ת בא כנ\"ל. בכת\"י הנ\"ל באו קיצורים רק לז' פרקים הראשונים. בכמה כת\"י לאחרי סוף פרק ז' באים הפרקים יא-יד, והפרקים ח-יו\"ד חסרים, וכנראה רצה כ\"ק אדמו\"ר הצ\"צ להוסיף עוד ג' פרקים באמצע המאמר, אך לא נרשמו בפועל, ולכן תוקנו אח\"כ בכמה כת\"י סימני הפרקים יא-יד והוחלפו לפרקים ח-יא, וכן נדפס באוה\"ת בא שם וכן נדפס כאן.\nעניני המאמר נמצאים עם שינויים והוספות לקמן בד\"ה וככה תאכלו (השני) ובמאמרים שלאחריו. (ד\"ה והנה יצ\"מ כו' אור לארבעה עשר, וד\"ה והנה בילקוט כו' כי בחפזון). וראה בהנסמן שם בתחילת המאמר."],["502","2","<b>מד\"ר קל\"ו ג'</b>: דפוס אמשטרדם ת\"א."],["e15","*","<b>וככה תאכלו</b>: על הגליון נרשם בכת\"י:\nוככה תאכלו אותו מתניכם חגורים: זח\"ב תרומה קע\"ה ע\"א. פ' פנחס דרנ\"א ע\"ב. פסחים [פ]\"ט צ\"ו א'. פרק ע\"פ ק\"ך ב. זבחים [פ]\"ה נ\"ו ב'. ברכות [פ]\"א ט' א'. (יר\"ק) כשפים א', קליפות ז'. מד\"ר קל\"ו ג'. ילקוט ח\"א נ\"ח ד', נ\"ט ד', ס' ב', ס\"ד ד'. ח\"ב נ\"ג ג'. של\"ה קס\"ו ב'. (יר\"ג) י\"ט ג', מ\"ו א'. (ע\"מ) ס\"ב. (י\"ח) משה ע\"ו. בחיי כ\"ד ד'."],["e16","*","<b>בשולי הגליון נרשם בכת\"י [והוא רשימת דרושים שאפשר לקשר ולסדר ממאמר זה]</b>:\nדרוש אין עומדין להתפלל כו' היו שוהים, בבוך תרי\"ז חצי בוגין דע\"ט א' ע\"פ אשה כי תזריע וילדה זכר וש\"נ. דרוש ע\"פ זאת החי' משל לרופא שנכנס לשני חולים בבוך תרט\"ז דרל\"א. דרוש מושיב יחידים ביתה לעיל בבוך זה."]]],[2000460210,"בהשכמה, עמדו המצריים אחר שהלכו להם ואמרו נרדוף אחריהם מפני שנטלו כל אשר לנו שנא' וירדפו מצרים אחריהם בפ' בשלח י\"ד, אמר להם הקב\"ה מי גרם לכם כל אלה חפזון שיצאתם בו, מכאן ואילך כי לא בחפזון תצאו, לשעבר אני ובית דיני הייתי מהלך לפניהם שנא' וה' הולך לפניהם יומם בפ' בשלח, אבל לע\"ל אני לבדי שנא' כי הולך לפניכם ה' ומאספכם אלקי ישראל בישעי' שם. והנראה דהא בהא תלי' אשר מה שלע\"ל לא ילכו בחפזון זהו מפני כי הוא ית' לבדו ילך לפניהם ע\"כ לא יצטרכו לחפזון ומנוסה, משא\"כ ביצ\"מ לפי שהוא וב\"ד מהלכים לפניהם נצרכו לחפזון ומנוסה (וע' מזה בלק\"ת פ' אמור בד\"ה וספרתם<sup data-n=\"503\">3</sup> לכם פ\"א בין שני חצאי עיגולים). וזהו ע\"ד מש\"ש במד\"ר ס\"פ י\"ח בעוה\"ז עשה להם נס בלילה שהוא נס עובר, אבל לע\"ל הלילה הזה נעשה יום שנא' והי' אור הלבנה כאור החמה.\n<b></b>קיצור. כי בחפזון יצאת, כמשל הסוחר שיצא מהפונדק בלילה ועי\"ז טענה הפונדקי' עליו, כך עי\"ז וירדפו מצרים אחריהם, נשבע הסוחר שלא יצא עוד בלילה כך מכאן ואילך כי לא בחפזון תצאו (הג\"ה ועמ\"ש ע\"פ וכי ימכור איש את בתו לאמה לא תצא כצאת העבדי' דפי' בזהר ר\"פ משפטים דצ\"ד ע\"ב שעז\"נ כי לא בחפזון תצאו ובמנוסה לא תלכון ע\"ש במק\"מ, וכתבתי מזה במ\"א ע\"פ וכי ימכור<sup data-n=\"504\">4</sup> איש כו' עכ\"ה). וזהו כעין מ\"ש במד\"ר בעוה\"ז עשה להם נס בלילה שהוא נס עובר אבל לע\"ל הלילה נעשה יום שנא' והי' אור הלבנה כאור החמה. וג\"כ ההפרש בין לשעבר אני וב\"ד היו מהלכים לפניכם אבל לע\"ל אני לבדי, ולכן כי לא בחפזון תצאו. נמצא מדת לילה וחפזון ובחי' וב\"ד הכל ענינם א', ומדת יום ובחי' לא בחפזון זהו נמשך מבחי' אני לבדי, ובפרדס ערך בית דין פי' כי ב\"ד הוא מל'.\nב) <b>עמ\"ש</b> ע\"פ וככה תאכלו אותו<sup data-n=\"505\">5</sup> בבוך שמות ד\"נ ע\"ב ע\"ש באריכות, ובזח\"ב תרומה<sup data-n=\"506\">6</sup> קע\"ה א' ע\"פ אשריך ארץ שמלכך בן חורין ושריך בעת יאכלו, ר' יוסי מוקי להאי קרא במשה בשעתא דאפיק להו לישראל ממצרים ועבד להון בני חורין ושריך בעת יאכלו דכתי' ואכלתם אותו בחפזון פסח הוא לה' (ע' כתובות ס\"ב ב' בני דעת קונך יש בך). והנה בקהלת סי' יו\"ד י\"ז בפסוק אשריך ארץ איתא בת\"י ושריך בעת יאכלו בארבעה שעות דהיינו אחר הקרבת תמיד של שחר, וא\"כ י\"ל דעכשיו תפלה במקום קרבנות זהו ע\"ד ועבדתם את ה' אלקיכם זו ק\"ש ותפלה, ואח\"כ וברך את לחמך ואת מימך. ואפ\"ל כי עת נק' המל' כמ\"ש בזח\"א פ' וירא דקי\"ו ע\"ב ע\"פ עת לעשות לה', אבל עת דא כנס\"י כד\"א ואל יבא בכל עת אל הקדש כו', כד\"א לשמרך מאשה זרה כו', מ\"ט עת בגין דאית לה עת וזמן לכולא לקרבא לאתנהרא כדקא יאות כד\"א ואני תפלתי לך ה' עת רצון עת לעשות לה' כמ\"ש ויעש",[["503","3","<b>בלק\"ת פ' אמור בד\"ה וספרתם</b>: דף לב, ב."],["504","4","<b>ועמ\"ש ע\"פ וכי ימכור איש את בתו. . וכתבתי מזה במ\"א ע\"פ וכי ימכור</b>: נדפס בתו\"ח שמות (כת\"י הר\"ש סופר) עא, ב ואילך. ובתוס' הגהות באוה\"ת משפטים ע' א'קכז ואילך. וביאור ע\"ז שם ע' א'קלט ואילך."],["505","5","<b>ומ\"ש ע\"פ וככה תאכלו אותו</b>: אוה\"ת בא ע' רצא ואילך."],["506","6","<b>זח\"ב תרומה. . פסחים. . זבחים</b>: רשימה זו כוללת ציונים ומ\"מ (מס' בית אהרן) למקומות בהם הובא הפסוק ”וככה תאכלו\". וכולל ציונים על: זהר, ש\"ס, יר\"ק [ ילקוט ראובני קטן], מדרש רבה, ילקוט שמעוני, של\"ה, יר\"ג [ ילקוט ראובני גדול], ע\"מ [ ס' עשרה מאמרות], י\"ח [ ס' ילקוט חדש]. רבינו בחיי עה\"ת. — חלק מציונים אלו הובאו ונתבארו לקמן בהמאמר."]]],[2000460211,"דוד שם, ועי' בלק\"ת פ' מטות בד\"ה עיני כל<sup data-n=\"507\">7</sup> אליך ישברו בענין ואתה נותן להם את אכלם בעתו, וזהו ושריך בעת יאכלו דהיינו אחר בחי' עת לעשות לה' אז יאכלו ג\"כ, דהיינו אחר שנעשו בני חורין שזהו ע\"י יחוד העליון שנק' עת רצון, כי בלילה דפסח נפתח בחי' טל ואזי ואכלתם אותו כו' שיהנו מיחוד העליון וכמ\"ש אכלתי יערי עם דבשי ועי\"ז אכלו ריעים הם מלאכים ונשמות דבי\"ע כמ\"ש בזהר ר\"פ ויקרא, וע' מענין עת בלק\"ת בד\"ה ואתחנן אל הוי'<sup data-n=\"508\">8</sup> בעת ההיא.\n<b></b>קיצור. ושריך בעת יאכלו, ואכלתם אותו בחפזון, עת לעשות לה' לחבר בחי' מל' הנק' עת אל הקדש, עת רצון, וזהו החפזון דשכינה לצאת מעת אחרא שעלי' נא' ואל יבא בכל עת.\nויש להעיר לענין עת מלשון ועונתה לא יגרע ע\"ד שארז\"ל פ' אע\"פ דס\"ב ב' בענין עונה של ת\"ח שעז\"נ אשר פריו יתן בעתו, הרי עת ועונה ענין א'. וזהו ענין בעתה אחישנה, ועמ\"ש ע\"פ והי' אמונת עתך<sup data-n=\"509\">9</sup>. וע' בשרשי' ערך עון וערך עונה ובערך עת, והנה בערך עון יש ל' מעון שהוא ל' דירה ולשון עונתה ופי' הש\"י<sup data-n=\"510\">10</sup> כי העונה והחיבור איש ואשתו נק' בית ודירה כמו מושיב יחידים ביתה, ובשרש עונה נז' ל' ענייה יעננו ביום קראנו. וע' בעה\"ק חלק התכלית פס\"ט בענין כל הקורא ק\"ש בעונתה, ואפשר להעיר מענין מצה הנק' לחם עוני שהוא הגורם להמשיך העונה, וזהו שעונין עליו דברים הרבה. ועמ\"ש בבוך שמות פ' בא בענין מארז\"ל כל האוכל מצה בע\"פ<sup data-n=\"511\">11</sup> כאלו בועל ארוסתו בבית חמיו הרי המצה שייך להיחוד, ולכן ושריך בעת הנ\"ל יאכלו ע\"ד באתי לגני אחותי כלה אכלתי יערי כו' ואזי אכלו ריעים כו'.\nג) <b>והנה</b> מ\"ש לעיל סעי' א' בעוה\"ז עשה להם נס בלילה כו' זהו הענין המבואר ג\"כ במדרש תלים סי' ל\"ו ע\"פ כי עמך מקו\"ח<sup data-n=\"512\">12</sup> באורך נראה אור א\"ר יוחנן עובדא הוה בחד בר נש הי' מדליק את הנר בלילה והי' כבה ומדליקו כבה ומדליקו, אמר עד מתי אהי' מתייגע והולך, ממתין אני עד שתזרח השמש ואני הולך לאור החמה, כך ישראל נשתעבדו במצרים עמדו משה ואהרן וגאלום, חזרו ונשתעבדו בבבל, וחוזרי' ונגאלים ע\"י חנני' מישאל ועזרי', חזרו ונשתעבדו למוקדון, ונגאלי' ע\"י מתתי' חשמונאי ובניו, חזרו ונשתעבדו באדום, אמרו ישראל הרי נתייגענו נגאלין ומשתעבדין אין אנו מבקשי' שיאיר לנו בשר ודם למטה אלא הקב\"ה שנא' אל הוי' ויאר לנו. הרי גאולת מצרים נמשל ג\"כ לנר והנר מדליקין בלילה, וזה\"ע עשה להם",[["507","7","<b>בלק\"ת פ' מטות בד\"ה עיני כל</b>: דף פה, ג-ד."],["508","8","<b>בלק\"ת בד\"ה ואתחנן אל הוי'</b>: פ' ואתחנן ג, א."],["509","9","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600123\" data-slug=\"or-hatorah-hb\" data-id=\"8316600123\">ועמ\"ש</a> ע\"פ והי' אמונת עתך</b>: אוה\"ת נ\"ך (כרך א) ע' קכג ואילך. אוה\"ת דרושים לחה\"ש ע' סו ואילך. וע' צ."],["510","10","<b>ופי' הש\"י</b>: — השרש ישע. [בד\"ה זה באוה\"ת בא שם נדפס: ופי' רש\"י]."],["511","11","<b>ועמ\"ש בבוך שמות. . בענין מארז\"ל כל האוכל מצה בע\"פ</b>: אוה\"ת בא שם ע' רצז."],["512","12","<b>במדרש תלים סי' ל\"ו ע\"פ כי עמך מקו\"ח</b>: בהבא לקמן — ראה סה\"מ תרכ\"ט ע' קלד ואילך. תרל\"ב ח\"א ע' כ. וע' כז-ח."]]],[2000460212,"נס בלילה, וכ\"ש גאולת בבל ומוקדון, וי\"ל לכן בחנוכה תקנו להדליק נר חנוכה, וגאולה דלע\"ל נמשל לאור השמש, וכמ\"ש ג\"כ במד\"ר פ' משפטים פל\"א ע\"פ עד בא השמש עד שיבא משיח שנא' וזרחה לכם יראי שמי שמש צדקה ומרפא. וזהו הפרש אחד בין נר לשמש, הב' בין ע\"י בשר ודם ובין ע\"י קוב\"ה, הג' בין לילה ליום, הד' בין שירות דעוה\"ז שנאמרו בל' נקבה שאע\"פ שיולדת חוזרת ומתעברת, כך אחר הגאולה הנמשל ללידה יש אח\"כ גלות הנק' עיבור, בכל פרשת העיבור יהיו צרכיהם לפניך, אבל לע\"ל גאולה שאין אחרי' גלות ח\"ו ונק' תשועת עולמים נאמר השיר בל' זכר כו'.\n<b>ואפ\"ל</b> שכל אלו הד' פירושי'<sup data-n=\"513\">13</sup> תלוים בדבר א', והוא כי מה שנעשה ע\"י הקב\"ה לבדו שלא ע\"י אמצעית בשר ודם הוא קיים לעולם ואין בו שינוי, והיינו משום שנא' אני הוי' לא שניתי, וכמשנ\"ת ענין זה בלק\"ת בהביאור ע\"פ אלה מסעי<sup data-n=\"514\">14</sup> דרוש השלישי ושם פ\"ד שזה\"ע אמת הפך נהרות המכזבין כ\"א כמו מוצא מים אשר לא יכזבו מימיו ואין בו הפסק, וכענין יחוד או\"א ונק' ונהר יוצא מעדן תרין ריעין דלא מתפרשין, משא\"כ יחוד זו\"נ שנפסק לפעמים ונק' נהר כבר שהי' בו מים מכבר אבל עכשיו ונהר יחרב ויבש. ועמ\"ש בענין מ\"ש במד\"ר פ' ויצא פ\"ע ע\"פ ושם ה' גדולה לאה גדולה במתנותי'<sup data-n=\"515\">15</sup> כהונה לעולם כו' ושם ה' קטנה רחל קטנה במתנותיה שאול לשעה כו', וזהו ההפרש בין חיי עולם ובין חיי שעה<sup data-n=\"516\">16</sup> בבוך תרי\"ט א' די\"ג השייך לד\"ה בכ\"ה בכסליו<sup data-n=\"517\">17</sup>. וע' בזהר ויחי דרכ\"א ע\"ב דעץ החיים שהוא ת\"ת נק' אתר דלא אשתני שנמשך מבחי' אני הוי' לא שניתי, ועה\"ד שהוא מל' נק' אתר דאשתני שמשתנה מגוון לגוון ממדה\"ר למדה\"ד כו', ועיקר שרש זה צ\"ל משום דבעץ החיים נא' ועל יובל ישלח שרשיו בינה שבה מאיר ע\"ק דלית שמאלא בהאי ע\"ק כו', שלכן ארז\"ל ספ\"ג דפסחי' ע\"פ ביום ההוא יהי' הוי' אחד שכולו הטוב והמטיב, כיון שאין שם מדה\"ד כלל, וצ\"ל בת\"ת מאיר בחי' זו, וזהו קוב\"ה מצלי יה\"ר מלפני שיכבשו רחמי, משא\"כ כשנמשך ע\"י בשר ודם שהוא מקבל מאתר דמשתני, ובשר ודם הוא מת ואף מרבע\"ה לא נמלט מזה ושרשו מחטא עה\"ד אתר דמשתני לכן גם הנס שנמשך ע\"י הוא נס עובר ואין לו קיום לעולם, רק כשנמשך מבחי' אני הוי' לא שניתי לבד. וזה\"ע המבואר במד\"ר פ' שמות פ\"ג אשר משה לא רצה לילך בשליחות<sup data-n=\"518\">18</sup> מה\"ט ורצה שיגאלם הקב\"ה בעצמו שלא ע\"י, וז\"ל המד\"ר שם",[["513","13","<b>הד' פירושי'</b>: ראה לקמן בהמשך וככה הב' שם מביא ה' חילוקים בין יצי\"מ לגאולה העתידה. עיי\"ש."],["514","14","<b>בלק\"ת בהביאור ע\"פ אלה מסעי</b>: פ' מסעי דף צג, ב."],["515","15","<b>במד\"ר פ' ויצא פ\"ע ע\"פ ושם ה' גדולה לאה גדולה במתנותי'</b>: ראה בכ\"ז סה\"מ תרכ\"ז ע' רצב-ג. וע' שצ. תרל\"ב ח\"א ע' קסח."],["516","16","<b>ההפרש בין חיי עולם ובין חיי שעה</b>: ראה בארוכה במקומות שנסמנו בהערה שלפנ\"ז. וראה גם סה\"מ תרכ\"ז ע' שלג. שלט. תרכ\"ט ע' רמד. ועוד."],["517","17","<b>בבוך תרי\"ט. . השייך לד\"ה בכ\"ה בכסלו</b>: אוה\"ת חנוכה רחצ, ב ואילך."],["518","18","<b>וזה\"ע. . אשר משה לא רצה לילך בשליחות</b>: ראה (באו\"א) <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111008\" data-slug=\"likkutei-sichot\" data-id=\"1300111008\">לקו\"ש חי\"א ע' 8</a>. ס' השיחות תשנ\"ב ח\"א ע' 98."]]],[2000460213,"ע\"פ ויאמר משה מי אנכי כך אמר משה לפני הקב\"ה רבון העולמים כשירד יעקב למצרים לא כך אמרת לו אנכי ארד עמך מצרימה ואנכי אעלך גם עלה ועכשיו אתה אומר לי לכה ואשלחך אל פרעה לא אנכי הוא שאמרת לו ואנכי אעלך גם עלה עכ\"ל, והמכוון הי' שמשה רצה שיצ\"מ יהי' ע\"ד שיהי' לע\"ל אל הוי' ויאר לנו שלא ע\"י בשר ודם ואזי לא יהיו חוזרים ומשתעבדי'. וזהו ג\"כ ההפרש בין נר לשמש, שהנר הוא מה שאדם מדליקו, משא\"כ השמש הוא פעול מאני הוי' לא שניתי, וגם כי השמש אין בו שינוים.\n<b>ויש</b> להעיר ג\"כ מפסוק כי נר מצוה ותורה אור שנמשל המצוה לנר והתורה לאור כי נר הוא מל' המאיר בבי\"ע, והיינו שענין הנר הוא דבר שאין לו אור מצד עצמו רק שהאדם מדליק אותה בשמן ואור ופתילה והיינו שהאדם ממשיך האור במל' שהמל' נק' סיהרא דלית לה מגרמה כלום רק שממשיכי' יחוד שמשא וסיהרא, וע' בת\"א פ' מקץ ע\"פ כי אתה נרי<sup data-n=\"519\">19</sup> היינו המשכת האור במל' ע\"ד יחיד חי העולמי' מלך והיינו ע\"י ארוממך אלקי המלך כו' ע\"ש, והנר אין לו קיום לעולם כי הרי זו\"נ נק' דודים דתאיבין דא לדא ולא משתכחין תדיר בזח\"ג פ' ויקרא ד\"ד סע\"א, וע' פרד\"ס ערך נר. אבל אור הוא ת\"ת שבו האור תמיד ואינו נצרך לאתעדל\"ת שידליקו, ואור הוי' הוא אור ע\"ק המאיר בז\"א, וע' בפרד\"ס ערך אור, וע' בלק\"ת בד\"ה ואתחנן אל הוי'<sup data-n=\"520\">20</sup> ההפרש בין מצוה ובין תורה, שהמצוה הוא המשכת אתעדל\"ע הנמשך ע\"י אתעדל\"ת דוקא, אבל התורה היא אתעדל\"ע שלמעלה מאתעדל\"ת. ומזה מובן מה שהמצוה נק' נר והתורה אור. וזהו שארז\"ל במס' סוטה פ\"ג דכ\"א א' את זו דרש ר' מנחם בר' יוסי כי נר מצוה ותורה אור תלה הכתוב את המצוה בנר ואת התורה באור, את המצוה בנר לומר לך מה נר אינה מגינה אלא לפי שעה כך מצוה אינה מגינה אלא לפי שעה, ואת התורה באור לומר לך מה אור מגין לעולם אף תורה מגינה לעולם כו', ד\"א עבירה מכבה מצוה ואין עבירה מכבה תורה, היינו מצוה יחוד ו\"ה והוא לשעה כי לפעמים מתפרשין דא מן דא כנ\"ל, וזהו עבירה מכבה מצוה כי ע\"י עבירה גורם דת\"ת אסתלק מהמל' ובפשעכם שולחה אמכם, אבל תורה מחו\"ב נפקת שהם תרדל\"מ כי שם מאיר ע\"ק אני הוי' לא שניתי כו', לכן אין עבירה מכבה תורה כי אין מגיע כלל הפגם שם. וע' בבה\"ז פ' תצוה בד\"ה גבי איהי קיימא",[["519","19","<b>בת\"א פ' מקץ ע\"פ כי אתה נרי</b>: דף מ, ג-ד."],["520","20","<b>בלק\"ת בד\"ה ואתחנן אל הוי'</b>: פ' ואתחנן ב, סע\"ג-ד."]]],[2000460214,"בשיעורא דטי\"ת נקודין גבי בהקדים הקדמה אחת דאו\"א נק' תרדל\"מ כו' עד ועז\"נ חנם חנם בלא מצות<sup data-n=\"521\">21</sup> כו' ע\"ש. וביאור ענין נר י\"ל שז\"ע המבואר בלק\"ת בשה\"ש בד\"ה קול דודי<sup data-n=\"522\">22</sup> הנה זה בא בפי' עד שנגלה עליהם ממה\"מ הקב\"ה כו', שמ\"מ בחי' זו נק' נר, השמן הוא חכ', והאור הארת הכתר נמשך ונאחז בפתילה יסוד, ומאיר במל' הנק' נר, ועי\"ז מאיר החשך דבי\"ע ועמ\"ש מזה לקמן סעי' יו\"ד באריכות.\n<b></b>קיצור. במד\"ת המשיל גאולת מצרים לאור הנר וגאולה דלעתיד לאור השמש, שהנר יוכל לכבות משא\"כ אור השמש, והיינו לפי שיצ\"מ הי' באמצעות בו\"ד אף שהיו משה ואהרן, והיינו כי אני הוי' לא שניתי, כ\"מ שנא' לי אינו זז לעולם, שם ה' גדולה אין הפסק במתנותי', משא\"כ כשנמשך מבחי' ה' קטנה זהו רק לשעה ויש הפסק כי יחוד זו\"נ נק' דודי' שהוא לפרקי' וכנ\"ל אות הקדום בענין עת ועונה, לכן לע\"ל שנא' וארשתיך לי הוא לעולם, וא\"כ היחוד שבבחי' נר שזהו ע\"י שבו\"ד מדליק הנר יוכל להיות כבה, כמו שבו\"ד עצמו יש לו הפסק שנמשך מאתר דמשתני, משא\"כ אור השמש א\"א לכבותו, לכן לע\"ל שיהי' הנס ע\"י והי' אור הלבנה כאור החמה ולא ע\"י נר יהי' תשועת עולמים. ועד\"ז יובן ג\"כ מעלת התורה כי עבירה מכבה מצוה ואין עבירה מכבה תורה, והיינו לפי כי נר מצוה והנר יוכל להיות כבה, והתורה אור והאור אין לו כיבוי, אך פי' אין עבירה מכבה תורה ע' בלק\"ת פ' ראה בד\"ה אחרי ה' אלקיכם<sup data-n=\"523\">23</sup> תלכו. והנה הנר מאיר בלילה משא\"כ ביום שרגא בטיהרא מאי אהני, ולפי שיצ\"מ הי' ע\"י נר לכן אור לי\"ד בודקין את החמץ לאור הנר<sup data-n=\"524\">24</sup>, ועמ\"ש בבוך ירמי' ע\"פ עוד תעבורנה הצאן<sup data-n=\"525\">25</sup> ע\"י מונה ירמי' ל\"ג י\"ג ושם סעי' ב'.\nד) <b>בבוך</b> שמות פ' בא ד\"נ ע\"ב נת' מענין כי בחפזון<sup data-n=\"526\">26</sup> יצאת לפי שהי' נס בלילה והלילה נק' ליל שמורים שבחי' מל' שהיא מדת לילה (ע' בת\"א פ' מקץ ד\"ה רני ושמחי דרוש השני) צריכה שמירה שלא יהי' יניקת החיצוני', וכמ\"ש בפרד\"ס ערך שמירה, אחת שהיא צריכה שמירה שסביבה היא הקליפה כענין סביב רשעים יתהלכון ולכן צריך שלא לחללה בחילול שבת עכ\"ל. (ועמ\"ש מזה בזח\"א ד\"ו ע\"א גבי תשמרו מאן מחלליה ובמק\"מ והרמ\"ז שם, וע' בלק\"ת פ' ראה בד\"ה ביאור הדברים בענין א\"ת בניך אלא בוניך ושם פ\"א, ומה שהעירותי שם<sup data-n=\"527\">27</sup> ממ\"ש בת\"א פ' בראשית בד\"ה להבין ענין הברכות<sup data-n=\"528\">28</sup> בענין שברכה אחרונה שכנגד חוה צ\"ל בה חותם",[["521","21","<b>בבה\"ז פ' תצוה בד\"ה גבי איהי קיימא. . עד ועז\"נ חנם חנם בלא מצות</b>: ז\"ל הביאוה\"ז שם דף נב, ב: יובן בהקדים הקדמה אחת דאו\"א נק' תרין רעין דלא מתפרשין וזווגייהו תדיר משא\"כ זו\"נ אין היחוד בהם אלא לפרקים כו' וכמ\"ש בע\"ח דעיקר העבודה לעשות יחודי' בהעלאת מ\"ן א\"צ רק בשביל יחוד דזו\"נ לפי שאינם ביחוד תדירי רק לפרקים ותלוי במעשה התחתונים וז\"ש ועבדתם את ה\"א וכן לאהבה את ה\"א ולעבדו כו' וידוע ענין עבודה זאת הוא לעשות יחודים בזו\"נ שנק' הוי' אלקיך והיינו ע\"י המצות וזהו תחת אשר לא עבדת את ה' אלקיך בשמח' כו'. אבל באו\"א א\"צ לעבוד' זו לגרום בהם בחי' היחוד אחר שיחוד שלהם תדירי ונק' תרדל\"מ כו' וע\"ז נאמ' חנם חנם בלא מצו' שא\"צ ליחודים ממעשה המצות כו'."],["522","22","<b>בלק\"ת בשה\"ש בד\"ה קול דודי</b>: דף יד, ד."],["523","23","<b>בלק\"ת פ' ראה בד\"ה אחרי ה' אלקיכם</b>: דף כ, א. ובהביאור ע\"ז שם כב, א."],["524","24","<b>ולפי שיצ\"מ הי' ע\"י נר לכן אור לי\"ד בודקין את החמץ לאור הנר</b>: ראה לקמן ד\"ה והנה יצ\"מ כו' אור לארבעה עשר."],["525","25","<b>בבוך ירמי' ע\"פ עוד תעבורנה הצאן</b>: <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600382\" data-slug=\"or-hatorah-hb\" data-id=\"8316600382\">אוה\"ת נ\"ך (כרך א) ע' שפב</a>."],["526","26","<b>בבוך שמות. . מענין כי בחפזון</b>: אוה\"ת בא שם ע' רצא."],["527","27","<b>בלק\"ת פ' ראה בד\"ה ביאור. . א\"ת בניך. . ומה שהעירותי שם</b>: דף לא, א."],["528","28","<b>בת\"א פ' בראשית בד\"ה להבין ענין הברכות</b>: דף ו, ג ואילך."]]],[2000460215,"בברוך כדי שלא יינקו החיצוני' כיון ומשם יפרד כו', ועמ\"ש בלק\"ת בשה\"ש בד\"ה קול דודי<sup data-n=\"529\">29</sup> ושם פ\"ב מענין ושמרתם את המצות). ויש עוד פי' ליל שמורים ע\"ד מארז\"ל פ' הבא על יבמתו שמשתמרת לביאה, וכמ\"ש בזח\"ב פ' בא דל\"ח ע\"ב שמורים דכר הוה זמין לאתחברא עמה, והוא כעין הנז' בת\"א פ' יתרו סד\"ה זכור ושמור<sup data-n=\"530\">30</sup> בדבור א' נאמרו בפי' שמור מל' ואביו שמר את הדבר, מ\"מ אדרבה מה\"ט צריכה שמירה מהחיצוני' כמ\"ש בזהר תרומה דקל\"ד ע\"א גבי ועד ובגין דלא תשלוט עין הרע אנן מחלפין אתוון כו' ע\"ש. וכן פי' בזהר שם דקל\"א ע\"א בענין שומר מה מליל ליל אצטריך לאנטורא כו', וכיון שכן לכן היציאה מהחשך להדבק בעולם העליון הנק' עלמא דדכורא הוא בחפזון שצריך לברוח מחשש יניקת החיצוני' שלא יתאחזו בה ויעכבו חיבור זה, ומעין ענין הנז' בזח\"א פ' נח דס\"ד א' שלא יקרב הנחש לגבי חוה יעו\"ש. ודוגמת בחי' זו באדם מבואר בסש\"ב פל\"א בפי' כי ברח העם, ובריחה זו היא למחדומ\"ע לבושי הנפש דקדושה, ע' סש\"ב פ\"ד ופי\"ב בענין והבינוני. ובזה מתורץ קושי' השל\"ה במס' פסחים שלו דרוש ג' מהו החשיבות כי בחפזון יצאת, כי זהו חשיבות ע\"ד יראת חטא שמתיירא מהחטא ולכן בורח ממנו ע\"ד ואל תאמין בעצמך, וזהו כמ\"ש במד\"ר פ' דברים ע\"פ פנו לכם צפונה ברחו לתורה כו', וכמארז\"ל פ\"ה דסוכה דנ\"ב אם רעב שונאך זה היצה\"ר האכילהו לחם מלחמה של תורה כו', ועי\"ז וה' ישלימנו לך יעו\"ש.\n<b></b>קיצור אות ד', ענין כי בחפזון יצאת בחפזון דשכינה, ליל שמורים יש בו ב' פי' ושניהם א', הא' דענין דכר הוה זמין לאתחברא בהדה וכענין זכור ושמור ואביו שמר את הדבר, וזהו לחם עוני כמו העני שמצפה להשפעת העשיר וכך סיהרא הנק' עני מצפה כו', וזהו ליל שמורים מצה שמורה שמשתמרת להיות צדיק אוכל, ע\"ד קראן לו ויאכל לחם. הב' שצריכה שימור מן החיצוני' שלא יחמיצוה ח\"ו ע\"י חומץ ומעול בחי' בא נחש כו', והיינו ע\"י שהשאור יחמיץ ח\"ו את בנ\"י וממילא יגרום כו', זהו הי' החפזון דשכינה מכף מעול וחומץ ולהדבק בקוב\"ה, ולכן זהו מעלה ע\"ד יראת חטא.\nה) <b>ועכ\"ז</b> אף שמוכרח למהר ולהיות חפזון, עכ\"ז כשהוא בענין שאין צריך כלל לחפזון הוא מעלה יתירה, כי החפזון קרוב לענין נחלה מבוהלת, ע' מד\"ר ויצא ר\"פ ע\"ב וס\"פ מטות בענין נחלת בני גד ובני ראובן<sup data-n=\"531\">31</sup>, הרי אם היו ממתינים היו יורשים בא\"י שמשובחת יותר מעבר הירדן. וכן באדם מעלת חסידי' הראשונים שהיו שוהים בתפלתן, שעי\"ז האהוי\"ר הן בני קיימא לא כן כשנחפז להתפעל ואינו שוהה בההתבוננו'. ולע\"ל שלא יצטרך לברוח מן הרע כי אז יגיעו לבחי' צדיק שלמעלה מבינוני בסש\"ב פרק יו\"ד, כ\"א ההילוך ע\"ד לצאת מחיצוני'",[["529","29","<b>בלק\"ת בשה\"ש בד\"ה קול דודי</b>: דף טו, א."],["530","30","<b>בת\"א פ' יתרו בד\"ה זכור ושמור</b>: דף עא, רע\"ד."],["531","31","<b>נחלה מבוהלת ע' מד\"ר. . בענין נחלת בני גד ובני ראובן</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380291\" data-slug=\"likkutei-torah\" data-id=\"4001380291\">לקו\"ת בחקותי נ, ב</a>. סה\"מ תרל\"ג ח\"א ע' לז ואילך."]]],[2000460216,"הלב לפנימי' הלב ומאהבה כמים הפנים לפנים לבחי' ובכל מאדך לא יצטרך לחפזון ומנוסה. וכן למעלה עילוי השכינה לא יצטרך לחפזון, וכענין יוה\"כ שאין שליטה לסט\"א אומרים בשכמל\"ו בקול רם. והנה עיקר חטא עה\"ד זהו שאדה\"ר הי' נחפז בזווגו עם חוה בערב שבת ולא המתין עד ליל שבת<sup data-n=\"532\">32</sup>, מיהו לא דמי ששם לא הי' בעת הנצרך כי אשר פריו יתן בעתו זהו בלילי שבת, וכאן הי' בעתו מ\"מ בחפזון.\n<b></b>קיצור סעי' ה', ועכ\"ז אף שלפי העת הי' צ\"ל חפזון ולא סגי בלא\"ה, עכ\"ז אין זה שלימות, דהרקנטי כ' דהחפזון דומה קצת להלעיטני כו'. ודוגמא מ\"ש רש\"י ע\"פ בן נעות המרדות בש\"א סי' ך' פסוק ל' כשחטפו בני בנימין מבנות של שילה כו' עד שבאת היא בעצמה כו'. והוא ההפרש בין בינוני לצדיק, חסידי' הראשוני' היו שוהים בתפלתם, משא\"כ בבינוני צ\"ל לפעמים חפזון מחשש מח\"ז והרהורים כו'. \nו) <b>ובמכילתא</b> מביא ראי' שהחפזון הי' חפזון דשכינה כנ\"ל אות ד' מפסוק קול דודי הנה זה בא מדלג, משמע שגם מעלמא דדכורא הי' ג\"כ כעין חפזון, והיינו משום מ\"ש בזהר ויקרא ד\"ד ע\"א בפי' דודים דתאיבין דא לדא, והדילוג הי' ג\"כ מטעם חשש יניקת החיצוני' שימנעו גילוי סוכ\"ע בממכ\"ע, וזהו ופסח ה' על הפתח, פתחי לי אחותי. וכ\"ז החפזון שייך בבחי' דודי' ששם יש מקום ליניקת החיצוני', משא\"כ בבחי' ריעים ונהר יוצא כו' שם א\"צ לחפזון ומנוסה כי אין שם מקום לחשש יניקת החיצוני'. ודוגמא זו בעבודה בצדיק גמור שכבר נהפך הרע, והעילוי רק שיאיר בו בחי' מזלי' ועי\"ז תורתו אומנתו, וע\"ד בחד קטירא אתקטרנא בי' בקוב\"ה.\n<b></b>קיצור סעי' וא\"ו, חפזון דשכינה קול דודי כו' מדלג, דודי' דתאיבין דא לדא, ופסח הוי' על הפתח, פתחי לי, משא\"כ בבחי' ריעים אין שייך יניקת החיצוני'.\nז) <b>והנה</b> לע\"ל כתי' ביום ההוא יהי' שבחי' ו\"ה יהיו תרין ריעין כמו י\"ה והיינו ע\"י ואת רוח הטומאה אעביר והיחוד יהי' לקבל פנימי' התורה שממו\"ס המאיר ע\"י יסוד אבא, והיינו ע\"י הרצוא לא בשביל ליפרד מהרע שזה אינו שייך וא\"צ אחר שיעביר רוח הטומאה, אלא ע\"ד ועמך לא חפצתי בד\"ה כי תצא דרוש השני<sup data-n=\"533\">33</sup>, וא\"כ א\"צ חפזון ומנוסה, והמעלה שההעלאה יהי' ע\"ד שוהים בתפלתם ואשה מזרעת תחלה ואח\"כ בא האתעדל\"ע וזהו השיהוי, ואז וילדה זכר, והיינו שעי\"ז יומשך הטפה מפנימיות אבא שבו מאיר פנימי' עת\"י, משא\"כ עכשיו נמשך רק מחיצוני' אבא נובלות חכ' שלמעלה תורה כו'.",[["532","32","<b>עיקר חטא עה\"ד זהו שאדה\"ר הי' נחפז. . ולא המתין עד ליל שבת</b>: ראה בארוכה ביאוה\"ז להצ\"צ ח\"א ע' טז ואילך. ח\"ב ע' תרכח ואילך. וראה גם אוה\"ת בראשית מו, א. מח, ב. מט, א. ועוד."],["533","33","<b>בד\"ה כי תצא דרוש השני</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380862\" data-slug=\"likkutei-torah\" data-id=\"4001380862\">לקו\"ת תצא לו, ב</a>."]]],[2000460217,"<b></b>קיצור סעי' ז', ולע\"ל ביום ההוא יהי' ע\"י ואת רוח הטומאה אעביר ואז יומשך גילוי פנימי' התורה ממו\"ס סבא דעתוהי סתים, ולא יהי' השפעת הדעת ע\"ד חפזון כ\"א בשובה ונחת, וע\"ד ההפרש בין הלומד מן הזקנים שדומה לאוכל ענבים בשולות ושותה יין ישן משא\"כ בלומד מן הקטנים כו', ובאמת במ\"ת נדמה להם כזקן, אך עכ\"ז יש סבא ויש סבא דסבין וזהו הגילוי דלע\"ל, ולכן מזה יומשך שיהי' כל עם ה' נביאים, וכן מלמטלמ\"ע הרצוא ע\"ד ועמך לא חפצתי ולא ליפרד מהרע לבד, וענין יין ישן זהו ע\"ד חסידי' הראשונים היו שוהים בתפלתן כי אין שום חשש חימוץ, וזהו לא תצא כצאת העבדים שיציאתן לברוח מן הרע וזה צ\"ל בחיפזון, אבל היציאה דלע\"ל ע\"ד עילוי אחר עילוי וכמו עולת שבת בשבתו שלמעלה מעולת התמיד, ועמ\"ש ע\"פ בן פורת יוסף<sup data-n=\"534\">34</sup> בפי' עלי עין למעלה מהעלאת מ\"ן דבחי' שמע שם ע' כו'.\nח) <b>ילקוט</b> פ' בא ד\"ס ע\"ב רמז קצ\"ט וככה תאכלו אותו כיוצאי דרכי' (יש להעיר מענין מה ראו על ככה ומענין ככה יעשה לאיש אשר המלך חפץ ביקרו יען שכדי שיומשך לבוש מל' אשר לבש בו ממה\"מ הקב\"ה וסוס ש' ס\"ג יומשך זה לצדיקים א\"א כ\"א ע\"י בחי' ככה כו', עיין בפי' ככה בת\"א ד\"ה לבסומי בפוריא דרוש השני<sup data-n=\"535\">35</sup>), ר' יוסי הגלילי אומר בא הכתוב ללמדך ד\"א מן התורה על יוצאי דרכי' שיהיו מזורזין. למדנו מזה שענין החפזון הוא הזריזות, ואפ\"ל הזריזות קאי על ענין מתניכם חגורים כו'. עוד שם בילקוט בחפזון כו' זה חפזון שכינה כו', זכר לדבר קול דודי הנה זה בא מדלג כו', יכול לע\"ל יהי' חפזון ת\"ל כי לא בחפזון תצאו כו'. עוד בילקוט שם דס\"ד ע\"א סוף רמז ר\"כ רבי אומר בזריזות יצאו ישראל ממצרים שנא' כי בחוזק יד הוציא ה', ד\"א בזריזות עצמן יצאו ישראל ממצרים שנא' וככה תאכלו אותו מתניכם חגורים. ויש להעיר ממ\"ש בגמ' שבת פרק אר\"ע דפ\"ט סע\"א עמא פזיזא דקדמיתו פומייכו לאודנייכו ופרש\"י פזיזא נמהר, והיינו ענין חפזון כו'.\n<b>וע'</b> מענין זהירות וזריזות בשל\"ה שער האותיות אות ז' דס\"ה סע\"ב שהזריזות הפך העצלות ע\"ד ותקם בעוד לילה כו' ולחם עצלות לא תאכל, והעיר מהמשנה יהודא בן תימא אומר רץ כצבי וגבור כארי, ובדף ס\"ט ע\"ב אות מ\"ם מתון, מתון מתון ארבע מאות זוז שויה כו'<sup data-n=\"536\">36</sup> שאל יבהל בשום מעשה כו', כי כל העושה בחפזון על הרוב מקלקל והסימן מן אמרתי בחפזי כל האדם כוזב כו', בשובה ונחת תושעון כו', והא דאמרינן זריזין מקדימי' למצות וצריך לעשותה בזריזות זה\"ע מצוה שכבר מפורסמת ומושכלת אצלו כו' עכ\"ל ויעו\"ש. וא\"כ א\"ש מעלת כי בחפזון יצאת כו' כי",[["534","34","<b>ועמ\"ש ע\"פ בן פורת יוסף</b>: הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370466\" data-slug=\"torah-or\" data-id=\"3901370466\">תו\"א ויחי קה, ד</a> ואילך. אוה\"ת ויחי (כרך ו) תתשמז, א."],["535","35","<b>בת\"א ד\"ה לבסומי בפוריא דרוש השני</b>: דף צט, סע\"ב-ג."],["536","36","<b>מתון מתון ארבע מאות זוז שויה כו'</b>: ע\"פ גמ' ברכות כ, א: דר\"א בר אהבה חזייה לההיא כותית דהות לבישא כרבלתא בשוקא סבר דבת ישראל היא קם קרעה מינה אטאי מילתא דכותית היא שיימוה בארבע מאה זוזי א\"ל מה שמך אמרה לי' מתון אמר לה מתון מתון ארבע מאה זוזי שויא."]]],[2000460218,"זהו מצוה מפורסמת ומושכלת, וע\"כ צ\"ל זריזין מקדימין. אך הקושיא א\"כ אמאי לע\"ל כי לא בחפזון תצאו כו', ע\"כ צ\"ל נהי דזריזין מקדימין למצות מ\"מ מעשה המצוה עצמה צ\"ל בשובה ונחת הפך החפזון כענין דברי חכמים בנחת נשמעים, והפסוק הוא בישעי' סי' למ\"ד ט\"ו כי כה אמר ה' קדוש ישראל בשובה ונחת תושעון בהשקט ובבטח, ושובה ונחת הוא ענין השקט ומנוחה.\n<b>וא\"כ</b> זהו מעין ההפרש שנת' במ\"א ע'פ הזהר פ' ויצא דקמ\"ח ע\"א ההפרש בין קומה ה' ויפוצו<sup data-n=\"537\">37</sup> אויביך שזהו ע\"ד הוי' איש מלחמה, ובין קומה ה' למנוחתיך שהמנוחה הוא ענין היפך המלחמה, וכמו בימי שלמה שהי' איש מנוחה לפי שמרוב הגילוי שהי' בבהמ\"ק היו כל האומות בטלים וכפופים כו' וא\"צ למלחמה. ועד\"ז ההפרש בין יצ\"מ שנא' וחמושים עלו בנ\"י מאמ\"צ ופרש\"י אין חמושים אלא מזויינים, ובירושלמי פ' במה אשה על המשנה לא יצא האיש בסייף כו' וחמושים עלו בנ\"י בחמשה כלי זיין<sup data-n=\"538\">38</sup>, אבל לע\"ל נא' וכתתו חרבותם לאתים ולא ישאו גוי אל גוי חרב כו', א\"כ הגאולה לא יהי' ע\"ד מלחמה כמו ביצ\"מ שנא' הוי' איש מלחמה כי ה' נלחם להם במצרים, אלא ע\"ד בשובה ונחת תושעון, וזה נמשך ע\"י כי הולך לפניהם ה' אני בעצמי שלמעלה מבחי' אני וב\"ד כו', לכן א\"צ למלחמה כלל כי הרים כדונג נמסו מלפני ה'. וע' בעה\"ק חלק העבודה ר\"פ ל\"ו מענין בשובה ונחת תושעון. וע' מפסוק זה<sup data-n=\"539\">39</sup> בישעי' סי' למ\"ד ט\"ו, בסנהדרין פרק חלק דצ\"ז ע\"ב, ירושלמי תענית פ\"א, מד\"ר פ' בא ט\"ו קל\"ג ג' קלד\"א קסח\"א, פ' ויקרא רכ\"ד ד', פ' נשא ספ\"ז, בקהלת צד\"ד, ילקוט ח\"ב סח\"א, של\"ה סט\"ב רלג\"א שנ\"ב ב'. והנה ההפרש בעבודה בין מלחמה ובין מנוחה זהו עצמו ההפרש בין בינוני ובין צדיק גמור, וע' באגה\"ק סי' י\"ב בד\"ה והי' מעשה הצדקה שלום.\nט) <b>בסנהדרין</b> פ' חלק דצ\"ז סע\"ב כתנאי ר' אליעזר אומר אם עושין תשובה נגאלין, אמר לו ר' יהושע והלא נא' חנם נמכרתם ולא בכסף תגאלו לא בתשובה ומע\"ט כו' א\"ל ר\"א והלא כבר נא' בשובה ונחת תושעון. מוכח דפי' בשובה ונחת היינו תשובה ומע\"ט, וכן פי' בהדיא במד\"ר פ' בא פט\"ז משכו וקחו לכם צאן הה\"ד בשובה ונחת תושעון, היינו משכו ידיהם מע\"ז זהו בשובה שישובו לה' ית', וקחו לכם צאן לקרבן פסח זהו ונחת ע\"ד ריח ניחוח, ופרש\"י נח\"ר לפני שאמרתי ונעשה רצוני. ובמד\"ר פ' ויקרא פ\"ג דקס\"ח ע\"פ טוב מלא כף נחת ממלא חפנים עמל, טוב מלא כף נחת זה יום השבת, ממלא חפנים עמל אלו ששת ימי",[["537","37","<b>שנת' במ\"א ע\"פ הזהר. . ההפרש בין קומה ה' ויפוצו</b>: הוספות לביאוה\"ז לאדהאמ\"צ קלב, ב ואילך. ולהצ\"צ ח\"א ע' קא ואילך. ח\"ב ע' תרפז ואילך. וע' תרצא ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158670035\" data-slug=\"or-hatorah-hb\" data-id=\"8158670035\">אוה\"ת ויצא קעז, א</a> ואילך. קפו, א ואילך."],["538","38","<b>וחמושים עלו בנ\"י. . לא יצא האיש בסייף. . בחמשה כלי זיין</b>: ראה בכ\"ז בארוכה סה\"מ תרל\"ב ח\"א ע' נב ואילך. וע' רכד ואילך. [ובהנסמן שם]. וראה גם אוה\"ת בשלח ע' שעד ואילך."],["539","39","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600214\" data-slug=\"or-hatorah-hb\" data-id=\"8316600214\">ע\"ד</a> בשובה ונחת תושעון. . וע' מפסוק זה</b>: ראה אוה\"ת נ\"ך (כרך א) ע' ריד-טו."]]],[2000460219,"המעשה (ועמ\"ש בלק\"ת פ' בלק בד\"ה לא הביט און ביעקב<sup data-n=\"540\">40</sup> ולא ראה עמל בישראל יעו\"ש) תדע לך שכן שאין ישראל נגאלין אלא בזכות שבת שנא' בשובה ונחת תושעון. במד\"ר פ' נשא ספ\"ז דרכד\"ד ע\"פ כן עשו בנ\"י, שעתידי' ישראל שיעשון תשובה והן נגאלין שנא' בשובה ונחת תושעון. במד\"ר בקהלת צ\"ד ד' ע\"פ טוב מלא כף נחת כמ\"ש במד\"ר פ' ויקרא פ\"ג כנ\"ל, אלא דשם מפרש יותר דפי' נחת ל' נייח דהיינו שבת שהוא יום מנוחה כו'.\n<b>והנה</b> בלק\"ת פ' בלק בד\"ה לא הביט און ביעקב ולא ראה עמל בישראל נת' שבחי' יעקב נק' עבדי, וזהו העבודה בחול ששת ימים תעבוד, ולעבדו בכל לבבכם זו תפלה, ועם היות כי לא הביט און ביעקב, מ\"מ עמל יש בו, מאחר שזהו בחי' עבודה, אכן ישראל נק' בן, בני בכורי ישראל שלמעלה ממדרגת עבד, וזהו בחי' שבת ואז לא ראה עמל ג\"כ בישראל כי הוא בחי' נייחא דאתהפכא חשוכא לנהורא יעו\"ש בהביאור<sup data-n=\"541\">41</sup>. והנה בשבת יש נשמה יתירה הנק' נשמת כל חי דפרחא מחי העולמים, ועמ\"ש מזה לעיל די\"ח ע\"ב בהגהות לד\"ה ויקהל משה<sup data-n=\"542\">42</sup>, ועיין בסנהדרין דצ\"ט ע\"ב ע\"פ כי אדם לעמל יולד באיוב סי' ה' לעמל תורה, אפ\"ל ג\"כ עפמ\"ש שבמזמור לתודה שאומרים בחול נא' הריעו לה' כל הארץ ר\"ת הלכה, ובשבת אומרים השתחוו לה' בהדרת קדש ר\"ת קבלה<sup data-n=\"543\">43</sup> היינו פנימי' התורה, ומצד הנגלות שבתורה שייך עמל, אבל פנימי' התורה היא דוגמת מן שאין בו פסולת כמ\"ש בת\"א פ' בשלח בד\"ה אכלוהו היום<sup data-n=\"544\">44</sup> לכן זהו למעלה גם מעמל תורה. והנה לע\"ל דוקא יתגלה פנימי' התורה כמ\"ש בסידור בהביאור ע\"פ כי על כל כבוד חופה<sup data-n=\"545\">45</sup> לכן זהו בשובה ונחת ע\"ד טוב מלא כף נחת ממלא חפנים עמל.\n<b>והנה</b> לפרש בענין תשובה שובה ונחת, י\"ל שובה זהו תשובה בינה מלמטלמ\"ע, ואח\"כ ונחת זהו עסק התורה שארז\"ל דברי חכמים בנחת נשמעים, ועמ\"ש במ\"א שלכן שערי דרישא רכיכין<sup data-n=\"546\">46</sup> יותר הרבה משערות דדיקנא דאינון קשישין כו' אשר שערי דרישא מורי' על המשכת החכ' ממו\"ס כו', וע' מענין דברי חכמים בנחת נשמעים בבה\"ז פ' וירא ע\"פ המאמר אחותי בת אבי<sup data-n=\"547\">47</sup> היא. והנה בחי' זו נק'",[["540","40","<b>ועמ\"ש בלק\"ת פ' בלק בד\"ה לא הביט און ביעקב</b>: דף עב, א."],["541","41","<b>והנה בלק\"ת פ' בלק בד\"ה לא הביט. . יעו\"ש בהביאור</b>: שם דף עב, ג ואילך."],["542","42","<b>ועמ\"ש. . בהגהות לד\"ה ויקהל משה</b>: ראה אוה\"ת ויקהל ס\"ע ב'קל. כרך ז' ס\"ע ב'תשצט."],["543","43","<b>עפ\"מ שבמזמור לתודה. . ר\"ת הלכה ובשבת. . ר\"ת קבלה</b>: ראה מאמרי אדה\"ז כתובים ח\"א ע' ו ואילך. מאמרי אדהאמ\"צ נ\"ך ע' קלט ואילך. סה\"מ תרכ\"ז ע' שט ואילך. וע' שיח ואילך. וש\"נ."],["544","44","<b>בת\"א פ' בשלח בד\"ה אכלוהו היום</b>: דף סה, ג-ד."],["545","45","<b>בסידור בהביאור ע\"פ כי על כל כבוד חופה</b>: סידור עם דא\"ח קלא, סע\"א ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381320\" data-slug=\"likkutei-torah\" data-id=\"4001381320\">לקו\"ת שה\"ש מח, א</a>-ב."],["546","46","<b>ועמ\"ש במ\"א דלכן שערי דרישא רכיכין</b>: סידור עם דא\"ח סד, סע\"א ואילך. מאמרי אדה\"ז תקס\"ז ע' קלה. וע' קמה."],["547","47","<b>בבה\"ז פ' וירא ע\"פ המאמר אחותי בת אבי</b>: ביאוה\"ז לאדהאמ\"צ יא, א."]]],[2000460220,"בעל תשובה ר\"ל שהוא בעל ומשפיע לבחי' תשובה עילאה<sup data-n=\"548\">48</sup> שהיא ה' של שם, כי תשובה תשוב ה', וע\"י עסק התורה שהיא מחכ' עילאה יו\"ד של שם נעשה בעל לבחי' תשובה כמ\"ש מזה בלק\"ת סד\"ה מה טובו<sup data-n=\"549\">49</sup> אוהליך יעקב ושם פ\"ו, וזה\"ע בשובה ונחת תושעון שהם בחי' י\"ה, ובהיות כן שיהי' בבחי' מנוחה היפך המלחמה א\"כ א\"צ כלל לחפזון ומנוסה כו'. של\"ה שנ\"ב סע\"ב, י\"ל שובה ונחת ע\"ד חיבור הרצוא דאש עם השוב דבחי' רוח עד יערה עלינו רוח ממרום שנת' בלק\"ת סד\"ה והי' מספר בנ\"י<sup data-n=\"550\">50</sup>, גם היפך מ\"ש לא ידון רוחי כ\"א ושפכתי רוחי, וזהו נחת ע\"ד נחת רוח.\nי) <b>והנה</b> בענין מתניכם חגורים כבר נת\"ל סעי' ח' דזהו ענין זריזות, וע' באגה\"ק סי' א' ע\"פ חגרה בעוז מתני' דפי' מתני' הוא בחי' אמונה, שהאמונה יסוד המעמיד השכל והאהוי\"ר כמו שהרגלים מעמידי' את הגוף, אך החגורה והחיזוק לבחי' מתנים זהו תשבע\"פ הנק' עוז, כי תושבע\"פ שרשה מרצה\"ע בחי' כתר, ונה\"י חדשים הנק' מתנים נמשכי' מהכתר. עוי\"ל שלהיות בחי' כי ברח העם לברוח מנו\"ן שע\"ט צ\"ל קל כצבי כמ\"ש ברח דודי ודמה לך לצבי, שהצבי קל ברגליו לברוח, ותשבע\"פ נק' ארץ הצבי<sup data-n=\"551\">51</sup> כמ\"ש בת\"א פ' וארא בד\"ה לכן אמור לבנ\"י<sup data-n=\"552\">52</sup>, לכן בה ועל ידה בורח מנש\"ט ומגיע לנש\"ב דקדושה ולרצה\"ע, כמו ברח לך דודי על הרי בשמים ג\"כ ע\"י בחי' ודמה לך לצבי. וזהו שיהיו מתניכם חגורים ע\"ד חגרה בעוז בתשבע\"פ מתני' שעי\"ז תוכלו לילך בזריזות מהרי בתר להרי בשמים<sup data-n=\"553\">53</sup>.\n<b>וזהו</b> ענין אוזר ישראל בגבורה, והנה במ\"ח מס' חצות פ\"ג פי' אוזר ישראל שהוא ז\"א, בגבורה שהיא נוק' הנבנית מהגבורות ויוצאות כנגד מקום אזור שבו. ועד\"ז פי' במאו\"א אות ח' סעי' וא\"ו בענין חגורה, אך לפמש\"ל דחגרה בעוז זהו תשבע\"פ שמאיר בה רצה\"ע, א\"כ י\"ל בגבורה היינו בינה כמ\"ש בזהר ויחי דר\"ז ב' בפי' ואם בגבורות שמונים שנה, והוא ג\"כ תושבע\"פ כי ע\"י גבורה זו נמשך להיות איזהו גבור הכובש את יצרו, וע\"ז מביא פסוק טוב ארך אפים מגבור<sup data-n=\"554\">54</sup> כו' וא\"א מאיר בבינה וכמ\"ש אני בינה לי גבורה, לכן ענין יצ\"מ שזהו ענין איזהו גבור הכובש את יצרו צ\"ל מתניכם חגורים בבחי' עוז שהוא ענין אוזר ישראל בגבורה. ועמ\"ש ע\"פ",[["548","48","<b>בעל תשובה. . בעל ומשפיע לבחי' תשובה עילאה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380618\" data-slug=\"likkutei-torah\" data-id=\"4001380618\">לקו\"ת בלק עה, א</a>-ב. סה\"מ תרכ\"ו ס\"ע רנ. תרל\"ח ע' שכו. וע' תקז."],["549","49","<b>בלק\"ת סד\"ה מה טובו</b>: לקו\"ת בלק שם."],["550","50","<b>בלק\"ת סד\"ה והי' מספר בנ\"י</b>: פ' במדבר ו, רע\"א."],["551","51","<b>קל כצבי. . ותשבע\"פ נק' ארץ הצבי</b>: ראה בכ\"ז לעיל ד\"ה החודש הזה לכם. וש\"נ."],["552","52","<b>בת\"א פ' וארא בד\"ה לכן אמור לבנ\"י</b>: דף נז, ד ואילך."],["553","53","<b>ברח לך דודי. . מהרי בתר להרי בשמים</b>: ראה בכ\"ז בארוכה הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370522\" data-slug=\"torah-or\" data-id=\"3901370522\">תו\"א מג\"א קטז, ד</a> ואילך. סה\"מ תרכ\"ז ע' רה ואילך. ובהנסמן בהמ\"מ שם בתחילת המאמר."],["554","54","<b>איזהו גבור הכובש את יצרו. . טוב ארך אפים מגבור</b>: בכ\"ז ראה לקמן ד\"ה ובראשי חדשיכם."]]],[2000460221,"חגור חרבך על ירך גבור תלים סי' מ\"ה ד' והוא בבוך תלים<sup data-n=\"555\">55</sup> דק\"כ ע\"ב ומ\"ש ע\"פ ויתפרו עלי תאנה<sup data-n=\"556\">56</sup> ויעשו להם חגורות. והנה חגור חרבך פרש\"י בשבת פ' במה אשה דס\"ג ע\"א דקאי על דברי תורה, שהתו' נק' וחרב פיפיות במד\"ר פ' בראשית ס\"פ כ\"א, וכיון שביצי\"מ נק' וחמושים עלו בני ישראל בבחי' חרב כו', וזהו מתניכם חגורים בחי' חגור חרבך על ירך גבור שהוא עסק התורה וזהו עיקר ענין אוזר ישראל בגבו' וכנ\"ל. וברקנטי פ' בא<sup data-n=\"557\">57</sup> כ' וז\"ל וככה תאכלו אותו, הפסוק הזה אומר לך דרשני אמר מתניכם רומז למ\"ש ויעשו להם חגורות ע' זהר בראשית דכ\"ח סע\"ב כי מלת חגורה רומז לזיין שנא' חגור חרבך, וחגור נתנה לכנעני הנא' על אשת חיל, והבן זה, וע\"כ מלת חגורים חסר יו\"ד, וזהו נעליכם ברגליכם כד\"א מה יפו פעמיך בנעלים, ומקלכם בידכם כד\"א כי במקלי עברתי את הירדן הזה עכ\"ל. ויש להעיר מענין ויקח לו יעקב מקל לבנה לח כו'. ועמ\"ש בבוך תרי\"ט ג' דף ל\"ו ע\"פ קח את המטה<sup data-n=\"558\">58</sup> כו' ודברתם אל הסלע. ובשל\"ה כי במקלי ר\"ת ברוך כבוד ה' ממקומו לישועתך קויתי ה', וי\"ל מקלי מטה וממשלה צדיק מושל ביראת אלקי', ועי\"ז עברתי את הירדן, ועמ\"ש ע\"פ כי במקלי בבוך בראשית<sup data-n=\"559\">59</sup> דשפ\"ו ע\"ב שאחר דף שצ\"ז ושם אח\"כ מענין ויקח לו יעקב מקל לבנה.\nיא) <b>וזהו</b> ענין מצה זו שאנו אוכלים<sup data-n=\"560\">60</sup> ע\"ש מה על שום שלא הספיק בצקת של אבותינו להחמיץ כו', וכ' הרד\"א<sup data-n=\"561\">61</sup> בפי' סדר ההגדה ד\"ע ע\"ג וז\"ל, יש לשאול כי ציווי אכילת מצות בסתם ולא אמר טעם לדבר (וע' מענין קושי' זו בלק\"ת ד\"ה ששת ימים תאכל<sup data-n=\"562\">62</sup> מצות דרוש הראשון, ובשה\"ש בד\"ה קול דודי<sup data-n=\"563\">63</sup> הנה זה בא, ושם תירץ שיש ב' בחי' מצה, ועדיין נשאר הקושי' שהרי אומר מצה זו שאנו אוכלים דהיינו מצה שקודם חצות הוא ע\"ש שלא הספיק להחמיץ, והתירוץ שם ע\"ז הוא דוחק ולפמש\"כ יתורץ כפשוטו), ותירץ ה\"ר יוסף קמחי<sup data-n=\"564\">64</sup> שמה שנצטוו על המצות קודם לכן הי' על שם העתיד שהשם יודע העתידות ידע שהי' להם לצאת ממצרים בחפזון ואפי' היו רוצים לא היו יכולים להחמיץ בצקם, צוה לאכול הפסח על מצות ומרורים ולאכול שבעת ימים מצה עכ\"ל. והיינו שיצ\"מ הי' צ\"ל בחפזון כנ\"ל סעי' ד', והוא ג\"כ ענין המשל הנז' בסעי' א' בלילה נטל כל אשר לו ויצא ומשל הנז' בסעי' ג' הי' מדליק את הנר בלילה כו' כ\"ז נק' חפזון.",[["555","55","<b>ועמ\"ש ע\"פ חגור חרבך. . בבוך תלים</b>: נדפס ביהל אור לתהלים ריש ע' קעד. וראה גם סה\"מ תרל\"ג ח\"ב ע' תד ואילך."],["556","56","<b>ומ\"ש ע\"פ ויתפרו עלי תאנה</b>: אוה\"ת בראשית (כרך ב) תלו, א ואילך. ס' החקירה להצ\"צ סו, א ואילך."],["557","57","<b>וברקנטי פ' בא</b>: הובא בהמשך וככה תרל\"ז פ\"ד (ע' ד)."],["558","58","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830143\" data-slug=\"or-hatorah-hb\" data-id=\"8158830143\">ועמ\"ש</a> בבוך תרי\"ט. . ע\"פ קח את המטה</b>: אוה\"ת חקת ע' תתכט ואילך."],["559","59","<b>ועמ\"ש ע\"פ כי במקלי בבוך בראשית</b>: אוה\"ת וישלח רלב, סע\"ב ואילך. וראה בכ\"ז סה\"מ תרל\"ג ח\"א ע' רלב ואילך. [ובהנסמן שם]."],["560","60","<b>וזהו ענין מצה זו שאנו אוכלים</b>: בהבא לקמן בפרק זה ראה בארוכה סה\"מ תרכ\"ט ע' קלב ואילך. וש\"נ."],["561","61","<b>וכ' הרד\"א</b>: הרב ר' דוד אבודרהם."],["562","62","<b>בלק\"ת ד\"ה ששת ימים תאכל</b>: פ' צו יג, ב. וראה גם שם יג, א."],["563","63","<b>ובשה\"ש בד\"ה קול דודי</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381188\" data-slug=\"likkutei-torah\" data-id=\"4001381188\">לקו\"ת שה\"ש יד, ד</a>."],["564","64","<b>והתירוץ שם ע\"ז הוא דוחק. . ותירץ ה\"ר יוסף קמחי</b>: ראה סה\"מ תרכ\"ט שם ס\"ע קלג-ד."]]],[2000460222,"<b>והענין</b> י\"ל עפמ\"ש בת\"י בש\"ב סי' כ\"ב כ\"ט ע\"פ כי אתה נרי הוי' והוי' יגיה חשכי, ארום את מארי נהורא דישראל הוי', והוי' יפקינני מחשוכא לנהורא ויחזינני בעלמא דעתיד למיתי לצדיקייא. אשר פשט דבריו דר\"ל כי אתה נרי היינו בעוה\"ז שהחשך בתקפו אלא שאתה מאיר לו כמו נר, אבל לע\"ל שנא' והי' אור הלבנה כאור החמה א\"כ יתבטל החשך, וזהו יפקינני מחשוכא לנהורא וזהו והוי' יגיה חשכי יגיה לשון כאור נוגה הולך ואור, וזהו עצמו ענין הנז' במדרש תלים סי' ל\"ו ע\"פ באורך נראה אור ההובא לעיל סעי' ג'. והנה מתחלה צריך להבין ענין שבעוה\"ז אע\"פ שיש חשך עכ\"ז כי אתה נרי הוי', ויתבאר זה ג\"כ ע\"ד שפי' רבינו ז\"ל בלק\"ת בשה\"ש בד\"ה קול דודי<sup data-n=\"565\">65</sup> הנה זה בא בפי' עד שנגלה עליהם ממה\"מ הקב\"ה וגאלם, ומתחלה ביאר לשון עד שלא נברא העולם דהל\"ל עד שלא בראת העולם, ומ\"מ כן לשון הכתוב כי הוא צוה ונבראו וגם כתי' בראשית ברא, והקדים ענין מלכותך מכ\"ע היינו מלכות כל עולמים זהו מל' דאצי' המחי' עולמות בי\"ע ולכבודי בראתיו יצרתיו אף עשיתיו, ובבחי' זו שייך ברא לפי שמבחי' זו נמשך כח הפועל בנפעל וע' בת\"א בד\"ה וקבל היהודים<sup data-n=\"566\">66</sup> ובלק\"ת בד\"ה שובה ישראל<sup data-n=\"567\">67</sup> עד דרוש השני פ\"א ופ\"ה. אך בחי' מלכותך הוא כמו שבחי' מל' כלול ובטל בעצמותו כזיו השמש כשהוא בתוך כדור השמש, ושם אין שייך לשון נברא. והנה מבחי' מל' כל עולמים נמשך שיהי' בבי\"ע בחי' העלם כמ\"ש בד\"ה תקעו בחדש שופר<sup data-n=\"568\">68</sup> דרוש הראשון ובד\"ה מי מנה עפר יעקב<sup data-n=\"569\">69</sup>, וע\"כ בחי' זו נק' מדת לילה כמ\"ש בת\"א פ' מקץ בד\"ה רני ושמחי<sup data-n=\"570\">70</sup> דרוש השני, וגם נת' במ\"א ע\"פ ויחלק עליהם לילה<sup data-n=\"571\">71</sup>. וע' עוד מזה בת\"א פ' בראשית בד\"ה ענין הברכות<sup data-n=\"572\">72</sup> ושם בענין ולילה ללילה יחוה דעת, ועוד בת\"א בדרוש פורים בד\"ה ותוסף אסתר<sup data-n=\"573\">73</sup>, וע' בלק\"ת פ' תבא בד\"ה תחת אשר לא עבדת<sup data-n=\"574\">74</sup> מענין בחי' לילה ובחי' יום בעבודת ה'. והנה ההמשכה מבחי' מלכותך בבחי' מל' כל עולמים להאיר מדת לילה זהו בחי' נר, דהיינו מ\"ש דהע\"ה שהוא בחי' מל' כי אתה נרי הוי', וע' מזה באריכות בת\"א פ' מקץ בד\"ה כי אתה נרי<sup data-n=\"575\">75</sup> הוי' בענין ד' בחי' שבנר, פתילה ושמן וב' גווני אור נהורא תיכלא ונהורא חיורא, שהם נגד ד' אותיות ש' הוי', ושם דהפתילה הוא ש' ב\"ן, ואיך כ\"ז הוא ענין ארוממך אלקי המלך, והיינו שההמשכה ממל' דא\"ס בבחי' מל' דאצי' נמשך ע\"י ד'",[["565","65","<b>שפי' רבינו ז\"ל בלק\"ת בשה\"ש בד\"ה קול דודי</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381187\" data-slug=\"likkutei-torah\" data-id=\"4001381187\">לקו\"ת שה\"ש שם יד, ג</a> ואילך."],["566","66","<b>בת\"א בד\"ה וקבל היהודים</b>: מג\"א דף צו, ג."],["567","67","<b>ובלק\"ת בד\"ה שובה ישראל</b>: דרושים לשבת שובה סו, א. סז, ג."],["568","68","<b>בד\"ה תקעו בחודש שופר</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380934\" data-slug=\"likkutei-torah\" data-id=\"4001380934\">לקו\"ת</a> דרושים לר\"ה נג, ד."],["569","69","<b>ובד\"ה מי מנה עפר יעקב</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380590\" data-slug=\"likkutei-torah\" data-id=\"4001380590\">לקו\"ת בלק סח, א</a>."],["570","70","<b>בת\"א פ' מקץ בד\"ה רני ושמחי</b>: דף לז, א-ב. לז, ד ואילך."],["571","71","<b>נת' במ\"א ע\"פ ויחלק עליהם לילה</b>: אוה\"ת בראשית עג, סע\"א ואילך. שם (כרך ב) תכג, א."],["572","72","<b>בת\"א פ' בראשית בד\"ה ענין הברכות</b>: דף ו, ד."],["573","73","<b>בת\"א בדרוש פורים בד\"ה ותוסף אסתר</b>: דף צד, ד."],["574","74","<b>בלק\"ת פ' תבא בד\"ה תחת אשר לא עבדת</b>: דף מב, סע\"ג."],["575","75","<b>בת\"א פ' מקץ בד\"ה כי אתה נרי</b>: דף מ, סע\"ב ואילך."]]],[2000460223,"אותיות ש' הוי' וזהו כי אתה נרי הוי'. וע' בהביאור ע\"פ המגביהי לשבת<sup data-n=\"576\">76</sup> פי' ענין הפתילה באופן אחר.\n<b>וכ\"ז</b> הוא רק בחי' נר, ר\"ל שמדת לילה בעצם לא נשתנה, כ\"א שנמשך בה בחי' נר שיהי' ע\"ד הלילה הזה. אכן בחי' והוי' יגיה חשכי היינו שיתהפך חשך הלילה לבחי' אור ממש דהיינו ענין והי' אור הלבנה כאור החמה, והיינו שבחי' בי\"ע שזהו מדת לילה יהי' כמו אצי' ממש שהוא בחי' יום, שגם בבי\"ע יאיר ע\"ד הגילוי שבאצי' ממש, וזהו הנמשך מבחי' והוי' ר\"ל הוי' דע\"ק שלמעלה מבחי' כי אתה נרי הוי' שהוא ש' הוי' שבאצי', שמבחי' שם הוי' דאצי' נמשך ע\"ד כי אתה נרי הוי', אבל מבחי' ש' הוי' דלעילא ע\"ק<sup data-n=\"577\">77</sup> יומשך שהחשך יהופך לאור, כמשנ\"ת מענין ב' שמות הוי' בלק\"ת פ' תצא בד\"ה ולא אבה<sup data-n=\"578\">78</sup> ה' אלקיך לשמוע אל בלעם, ושם נת' שמבחי' ש' הוי' דע\"ק נמשך להיות ויהפוך ה' אלקיך לך את הקללה לברכה וכ\"ש וק\"ו שיוכל להיות החשך נהפך לאור כו', ולכן אז כי בחפזון לא תצאו כו'. וזהו ג\"כ המשל מהסוחר שנשבע שלא יצא עוד מהפונדק בלילה כו', שלא יהי' עוד בחי' לילה כי בי\"ע יהי' כמו אצי'. והנה גם במדת לילה יש נר ויש אבוקה<sup data-n=\"579\">79</sup> כו'.\n<b>והנה</b> פי' כי נר מצוה ותורה אור, י\"ל אשר ע\"י המצוה ממשיכי' בחי' כי אתה נרי הוי', שנשאר מדת לילה רק שיהי' מאיר בה האור הנר, ע\"ד ההמשכה מבחי' מלכותך במל' דאצי' ע\"י ש' הוי' דאצי'. אבל ותורה אור ר\"ל ע\"י התורה ממשיך בחי' אור שלמעלה מבחי' נר שהוא שגם חשך הלילה יהי' אור, והיינו לפי שהתורה היא המשכת יחודא עילאה הגילוי איך כולא קמי' דוקא כלא חשיב וזהו עצמו מדת יום, משא\"כ המצות הם מצות המלך שהוא יחו\"ת כמשנ\"ת בלק\"ת פ' אחרי בד\"ה כי ביום הזה יכפר<sup data-n=\"580\">80</sup> דרוש השני ושם פ\"ב. ואפ\"ל שזהו פי' והיו הדברים האלה דקאי על תורה אשר אנכי מצוך היום, כלומר שעי\"ז תהיו בבחי' היום שהוא מדת יום שלמעלה ממדת לילה כו', וזהו ענין כימי השמים על הארץ.",[["576","76","<b>בהביאור ע\"פ המגביהי לשבת</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370178\" data-slug=\"torah-or\" data-id=\"3901370178\">תו\"א מקץ לט, ב</a>."],["577","77","<b>ש' הוי' שבאצי'. . ש' הוי' דלעילא ע\"ק</b>: ראה לעיל ד\"ה זאת חוקת וד\"ה ששים המה מלכות בענין ב' שמות הוי'. וש\"נ."],["578","78","<b>בלק\"ת פ' תצא בד\"ה ולא אבה</b>: דף לט, א. לט, סע\"ג ואילך."],["579","79","<b>גם במדת לילה יש נר ויש אבוקה</b>: בהמאמר כאן לא נת' ענין נר ואבוקה, וראה לקמן ד\"ה והנה בילקוט כו' כי בחפזון."],["580","80","<b>בלק\"ת פ' אחרי בד\"ה כי ביום הזה יכפר</b>: דף כז, א-ב."]]],[2000460224,"<h3>וככה תאכלו אותו (א)</h3>\n<b></b><b>בס\"ד. (ליל ב' דחג הפסח, ט\"ל).</b>\n<b></b>ה' הפרשים בין יצי\"מ ולע\"ל כו' נהר כבר כו' שאול ודוד כו' חפזון כו' גאולת חמו\"ע\nליל ב' דחה\"פ\n<b>וככה</b> תאכלו אותו<sup data-n=\"581\">1</sup> מתניכם חגורים כו' ואכלתם אותו בחפזון, ואיתא ברבות ע\"ז (בא פי\"ט) יצ\"מ הי' ע\"י חפזון<sup data-n=\"582\">2</sup>, אבל לע\"ל כתי' כי לא בחפזון תצאו ובמנוסה לא תלכון, למה הדבר דומה לסוחר שנכנס לשרות בפונדק עמד שם כל היום, בלילה נטל כל אשר לו ויצא לדרכו, עמדה הפונדקית בבקר והתחילה צווחת ראו הפרגמטוטוס עמד בלילה נטל כל אשר לי והלך לו, שמע אותו הפרגמטוטוס אמר מי גרם לי לשמוע כך אלא מפני שיצאתי בלילה לפיכך נשבע אני שלא אצא עוד בלילה, כך התקינו ישראל עצמם בלילה לצאת בהשכמה, עמדו המצריים כו' ואמרו נרדוף אחריהם מפני שנטלו כל אשר לנו שנא' וירדפו מצרים כו' (נטלו כל אשר להם, אך באמת הי' זה של ישראל כי שכר העבודה שלהם הי' שוה יותר (וכמשארז\"ל בסנהדרין צ\"א א'), א\"ל הקב\"ה מי גרם לכם כל אלה חפזון שיצאתם בו, מכאן ואילך כי לא בחפזון תצאו ובמנוסה לא תלכון. וזהו מ\"ש בזהר ע\"פ וכי ימכור איש את בתו לאמה לא תצא כצאת העבדי' זהו מ\"ש כי לא בחפזון תצאו כו'. עו\"ש במדרש לשעבר אני ובית דיני<sup data-n=\"583\">3</sup> היו מהלכים לפניהם שנא' וה' הולך לפניהם יומם, וה' הוא ובית דינו, אבל לע\"ל אני לבדי שנא' כי הולך לפניכם ה' (ישעי' נ\"ב). ובפ' י\"ח אמרו במדרש לשעבר הי' הנס בלילה ולכך הי' הנס עובר, אבל לע\"ל לא יהי' הנס בלילה כי לילה כיום יאיר וכתי' והי' אור הלבנה כאור החמה.",[["581","1","<b>וככה תאכלו אותו</b>: מאמר זה וב' המאמרים שלאחריו מיוסדים והגהות על ד\"ה זה להצ\"צ בכרך כת\"י 1063 רכג, א (כת\"י זה נק' בוך בראשית שמות ויקרא וכולל הנחות ממאמרי הצ\"צ). חלק מההגהות נרשמו בגוכי\"ק כ\"ק אדמו\"ר מהר\"ש בגליונות בפ\"ע ונרשם ע\"ז: לד\"ה וככה כו' ואכלתם אותו בחפזון שבס' בראשית שמות ויקרא. ולאח\"ז נעתק המאמר עם ההגהות ע\"י הר\"ש סופר, [בראש המאמר נרשם בגוכתי\"ק: לא הועתק, וכן נרשם על גליוני ההגהות, וכנראה הכוונה שמאמר זה לא ניתן להעתיק ולפרסם אותו בשעתו (ראה עד\"ז סה\"מ תרנ\"ד ע' וע' )].\nהנחה אחרת ממאמר הצ\"צ נד' באוה\"ת בא (כרך ח) ע' ב'תתקלד ואילך. מאמר זה כפי שנרשם ע\"י הצ\"צ נדפס באוה\"ת בא ע' רחצ ואילך. ולעיל ד\"ה וככה תאכלו הא' [כנסמן לקמן בפרטיות].\nלכללות עניני המאמר ראה: ד\"ה זה באוה\"ת בא ע' רצא ואילך. שם (כרך ז) ע' ב'תרכב. המשך וככה תרל\"ז פרקים א-ד. ופרק קכט ואילך. ד\"ה מצה זו בסה\"מ תרכ\"ט ע' קלד ואילך. ד\"ה כי עמך מקור חיים בסה\"מ תרל\"ב ח\"א ע' כ ואילך וע' כז ואילך. ד\"ה למען תזכור בסה\"מ תרס\"ג ח\"ב ע' קמט ואילך. ד\"ה וככה וד\"ה מצה זו תער\"ב (סה\"מ תער\"ב-ע\"ו ע' קנח ואילך. וע' קעב ואילך. ובסה\"מ ליקוט ח\"ב ע' קפט ואילך. וע' רי-יא). ד\"ה כי בחפזון וד\"ה כימי צאתך תרצ\"א תש\"ח בסה\"מ תש\"ח ע' 152 ואילך. ד\"ה וככה תאכלו וד\"ה כימי צאתך בסה\"מ תשל\"ז ע' 191 ואילך וע' 201 ואילך.\nראה לקמן בהנחות השומעים מהמאמר שבעת אמירת המאמר ע\"י כ\"ק אדמו\"ר מהר\"ש התחיל את המאמר עה\"פ: ”ואכלתם אותו בחפזון\"."],["582","2","<b>ואיתא ברבות. . יצ\"מ הי' ע\"י חפזון</b>: בהבא לקמן עד סוף הפיסקא ראה לעיל ד\"ה וככה תאכלו (הא') פרק א. וראה בכ\"ז סה\"מ תרכ\"ט שם ע' קלד."],["583","3","<b>במדרש לשעבר אני וב\"ד. . שנא' כי הולך לפניכם ה'</b>: הובא ונת' ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490171\" data-slug=\"or-hatorah-hb\" data-id=\"8316490171\">אוה\"ת וירא (כרך ד) תשנה, א</a>."]]],[2000460225,"<b>והנה</b> מ\"ש כאן שלשה הפרשים<sup data-n=\"584\">4</sup> בין יצ\"מ לגאולה העתידה חפזון, ולילה, ובין הוא ובית דינו ואני לבדי. והנה באמת כל ההפרשים תלוי' בהפרש א' שכשהגילוי הי' ע\"י הוא ובית דינו אזי צריך להיות חפזון דוקא, וגם מצד זה הי' הנס בלילה. אבל כשיהי' הגילוי ע\"י אני לבדי אז א\"צ לחפזון, וגם הלילה כיום יאיר כו'. ופי' בית דינו הוא בחי' ש' אלקי'<sup data-n=\"585\">5</sup>, וכמו שבית דין של מטה נק' ג\"כ אלקי' כמ\"ש עד האלקי' יבא דבר שניהם, אשר ירשיעון אלקי' שהכוונה הוא על בית דין.\n<b>עוד</b> במדרש תלים ע\"פ כי עמך מקור חיים<sup data-n=\"586\">6</sup> באורך נראה אור איתא שם עובדא הוה בחד בר נש שהי' מדליק את הנר בלילה והי' כבה ומדליקו, כבה ומדליקו, אמר עד מתי אהי' מתייגע והולך, ממתין אני עד שתזרח השמש ואני אלך לאור החמה, כך ישראל נשתעבדו במצרים עמדו משה ואהרן וגאלום, חזרו ונשתעבדו בבבל, ונגאלו ע\"י חנני' מישאל ועזרי'<sup data-n=\"587\">7</sup>, חזרו ונשתעבדו במוקדון, ונגאלו ע\"י מתתי' בן יוחנן כה\"ג חשמונאי ובניו, חזרו ונשתעבדו, אמרה כנס\"י לפני הקב\"ה עד מתי אנו מתייגעין נגאלין ומשתעבדין אין אנו רוצי' שיהי' גאולתינו ע\"י בשר ודם אלא כנ\"ל ממתינים אנו עד שיאיר לנו השמש היינו עד שיאיר לנו אור הוי' בעצמו וכמ\"ש אל הוי' ויאר לנו, וזהו באורך נראה אור. נמצא שיש עוד הפרש בין יצ\"מ ובין לעתיד, שגאולת מצרים נק' נר שהאדם מדליקו שהגאולה הי' ע\"י בשר ודם, והגם שהי' ע\"י משה ואהרן אעפ\"כ נק' נר, משא\"כ הגאולה דלעתיד הוא בחי' אור השמש שלמעלה מנר. וזהו מ\"ש עד בא השמש תשיבנו לו שקאי על משיח שביאת משיח נק' בשם אור השמש, כמ\"ש וזרחה לכם יראי שמי כמ\"ש במד\"ר במקומו פ' משפטי' פל\"א. עוד יש הפרש בין שירים דעתה לשירים דלע\"ל, כי שירים דעתה הוא ל' נקבה שנק' בשם שירה ל' נקבה, משא\"כ לע\"ל נא' שיר בל' דכר שנא' ביום ההוא יושר השיר הזה (ישעי' רסי' ך\"ו), והיינו כי פי' ל' נקבה היינו כמו שהנקבה יולדת וחוזרת ומתעברת, וכך גלות וגאולה נק' בשם עיבור ולידה<sup data-n=\"588\">8</sup>, כי הגאולה נק' לידה וכמ\"ש כי חלה גם ילדה ציון את בניה, והגלות נק' בשם עיבור וכמשארז\"ל בכל פרשת העיבור יהיו צרכיהם לפניך אפי' בשעה שאתה מתמלא עליהם עברה כאשה עוברה, ולכן השירים דעתה הוא ל' נקבה לפי שאף שהי' גאולה וכמ\"ש ויושע ה'",[["584","4","<b>והנה מ\"ש כאן שלשה הפרשים</b>: בהבא לקמן בפיסקא זו ראה לעיל ד\"ה וככה (הא') פרק ג פיסקא: ואפ\"ל."],["585","5","<b>ופי' בית דינו הוא בחי' שם אלקי'</b>: בד\"ה זה ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316300020\" data-slug=\"or-hatorah-hb\" data-id=\"8316300020\">אוה\"ת בא (כרך ח</a>) שם: בספר מנחם עזרי' פי' בשם ירושלמי דב\"ד הוא שם אלקים. ע\"כ. (והכוונה לס' עשרה מאמרות להרמ\"ע מפאנו מאמר אם כל חי ח\"א פ\"א בשם הירושלמי ריש סנהדרין). וראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490163\" data-slug=\"or-hatorah-hb\" data-id=\"8316490163\">אוה\"ת וירא (כרך ד) תשנא, א</a> ואילך. ד\"ה וה' פקד בסה\"מ תרל\"א. וש\"נ."],["586","6","<b>עוד במדרש תלים ע\"פ כי עמך מקור חיים</b>: בהבא לקמן — ראה לעיל ד\"ה וככה (הא') ריש פרק ג. וראה בכ\"ז יהל אור לתהלים ע' קלח. סה\"מ תרכ\"ט שם ע' קלה. תרל\"ב ח\"א שם ע' כ וע' כז."],["587","7","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460010\" data-slug=\"or-hatorah-hb\" data-id=\"8316460010\">ונגאלו ע\"י</a> חנני' מישאל ועזרי'</b>: בד\"ה זה באוה\"ת בא (כרך ח) שם נוסף כאן: הגם שהי' בנין הבית ע\"י עזרא, קורא זה כאן ע\"ש חנני' מישאל ועזרי'."],["588","8","<b>גלות וגאולה נק' בשם עיבור ולידה</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370247\" data-slug=\"torah-or\" data-id=\"3901370247\">תו\"א וארא נה, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370257\" data-slug=\"torah-or\" data-id=\"3901370257\">נז, ג</a>-ד. ועוד. וראה גם לעיל ד\"ה החודש הזה לכם."]]],[2000460226,"ביום ההוא, אעפ\"כ יש אחריה עיבור דהיינו עוד גלות, משא\"כ לע\"ל יהי' השיר בל' דכר לפי שלא יהי' אחריה עוד גלות ולא יהי' שם עצב ויגון וכמ\"ש ושמחת עולם על ראשם.\n<b>נמצא</b> שיש כאן ה' הפרשים בין גאולת מצרים לגאולה העתידה<sup data-n=\"589\">9</sup>, א' חפזון, ב' לילה, ג' בין הוא ובית דינו לבחי' אני, ד' נר ושמש, ה' בין שירים דעתה ללע\"ל, וכל ההפרשים תלויין בההפרש שבין וה' הוא ובית דינו לבחי' אני בעצמי.\n<b>והענין</b> דהנה כתי' אני הוי' לא שניתי לכן כשנמשך הנס מבחי' ש' הוי' לבדו אין בזה שינוי, וזהו ענין אמת<sup data-n=\"590\">10</sup> ששם הוי' נק' אמת וכמ\"ש ואמת הוי' לעולם, דהנה אמת הוא היפוך מבחי' כזב כי כזב הוא בחי' שיש לה הפסק, וכמשארז\"ל בענין נהרות המכזבין פעם אחת בשבוע פסולין<sup data-n=\"591\">11</sup> לקידוש מי חטאת, שאעפ\"י שאינם מכזבין אלא פעם אחת בשבוע אעפ\"כ נק' כזב לפי שיש הפסק לנביעתן, משא\"כ אמת הוא בחי' מבוע דלא פסיק לעלמין וכמ\"ש וכמוצא מים אשר לא יכזבו מימיו, וזהו ענין בחי' י\"ה בחי' יחוד חו\"ב שנק' תרין ריעין דלא מתפרשין לעלמין וכמ\"ש ונהר יוצא מעדן, יוצא תמיד בלי הפסק. ובזה יובן מה שפי' הר\"ש בפ\"ח דפרה משנה ט' על מי כוזבים אבל כשמכזבין פ\"א ביובל כשרים לקידוש מי חטאת, וכ\"פ הרע\"ו ב\"ט<sup data-n=\"592\">12</sup>, כי יובל הוא בחי' בינה שנהר דבינה יוצא תמיד מעדן, תרין ריעין דלא מתפרשין, ולכן גם עץ החיים הוא אתר דלא משתני כמשי\"ת, מפני שועל יובל ישלח שרשיו. וזהו שהתורה נק' חיי עולם שהוא בחי' נצחיות, משא\"כ התפלה נק' חיי שעה<sup data-n=\"593\">13</sup>, לפי שהתפלה היא במל' כמ\"ש ואני תפלה, ובבחי' ו\"ה שהוא בחי' יחוד זו\"נ שהוא בחי' יחוד דודים אין היחוד בתמידיות. וזהו מ\"ש ביחזקאל ואני הייתי בתוך הגולה על נהר כבר, דהיינו שמכבר היו בו מים, משא\"כ עתה<sup data-n=\"594\">14</sup> כתי' ונהר יחרב ויבש שאין היחוד עתה כמו שהי' בזמן שבהמ\"ק קיים, ולכך נק' נהר כבר שמכבר היו בו מים. וזהו מ\"ש ושם הגדולה לאה ואיתא ברבות במקומו ע\"ז דלכך נק' לאה גדולה",[["589","9","<b>ה' הפרשים בין גאולת מצרים לגאולה העתידה</b>: ראה לעיל בד\"ה וככה (הא') פרק ג שם מביא ד' חילוקים. עיי\"ש."],["590","10","<b>והענין דהנה כתיב אני הוי' לא שניתי. . וזהו ענין אמת</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380697\" data-slug=\"likkutei-torah\" data-id=\"4001380697\">לקו\"ת מסעי צג, ב</a>. — בהבא לקמן עד סוף הפיסקא ראה לעיל בד\"ה וככה (הא') פ\"ג פיסקא: ואפ\"ל."],["591","11","<b>כזב הוא בחי' שיש לה הפסק. . נהרות המכזבין פעם אחת בשבוע פסולין</b>: בכ\"ז ראה גם סה\"מ תרכ\"ט ע' קסב. תרל\"ב ח\"א ע' ערה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061103\" data-slug=\"likkutei-sichot\" data-id=\"1300061103\">לקו\"ש ח\"ו ע' 92</a>. וש\"נ."],["592","12","<b>וכ\"פ הרע\"ו ב\"ט</b>: וכן פירש הרב עובדי' ברטנורא."],["593","13","<b>שהתורה נק' חיי עולם. . התפלה נק' חיי שעה</b>: ראה בכ\"ז סידור עם דא\"ח עג, ג ואילך. שערי תשובה ח\"ב כו, א ואילך. סה\"מ תרכ\"ז ע' רצב ואילך. וש\"נ. שלג. שלט. שפט ואילך. תרכ\"ט ע' רמד. וש\"נ."],["594","14","<b>נהר כבר דהיינו שמכבר היו בו מים משא\"כ עתה</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600390\" data-slug=\"or-hatorah-hb\" data-id=\"8316600390\">אוה\"ת בלק ע' א'לד</a>. נ\"ך (כרך א) ע' שצ ואילך. סה\"מ תרס\"ה ע' קצב. וראה ס' השיחות תנש\"א ח\"א ע' 151."]]],[2000460227,"שגדולה במתנותי'<sup data-n=\"595\">15</sup> כהונה לעולם וכמ\"ש ברית כהונת עולם<sup data-n=\"596\">16</sup> ברית מלח עולם היא, ע' במד\"ר ר\"פ קדושים, כמו שמלח הוא דבר המעמיד ומקיים לעולם שאין המלח נפסד ומתקלקל, ואדרבה שהוא מקיים גם דבר אחר כו', וכך כהונה לעולם ולכך נק' ברית מלח, וכן מלוכה לעולם וכמ\"ש ודוד עבדי נשיא עליהם לעולם, משא\"כ רחל נק' קטנה שקטנה במתנותיה שאול לשעה, והיינו לפי שלאה הוא בחי' ה' גדולה שהוא בחי' בינה והתגלות עת\"י בבינה לכך הוא לעולם.\n<b>וזהו</b> משארז\"ל בפ\"ב דיומא שאול באחת ועלתה לו, דוד בשתים ולא עלתה לו, והיינו לפי שבדוד נא' רמה קרני<sup data-n=\"597\">17</sup> בה', ולא רמה פכי, שאול שנמשח בפך לא נמשכה מלכותו, דוד שנמשח בקרן נמשכה מלכותו (בפ\"ק דמגילה), והיינו לפי שמלוכה של שאול הי' ע\"פ חכ' שע\"פ חכ' נתחייב שיהי' הוא דוקא מלך ישראל, והיינו לפי שנא' בו משכמו ולמעלה גבוה מכל העם דהיינו שבחי' כתפין שלו שהוא בחי' מדותיו הי' למעלה מבחי' מוחין של כל ישראל, ולכך חייבה חכמתו ית' שיהי' הוא דוקא מלך ישראל, ולפי שמלוכה שלו הי' ע\"פ חכ' ולכך כשחטא ממילא חייבה חכמתו ית' להיפוך שיופסק מלכותו. וכמשארז\"ל (בילקוט תלים ע\"פ טוב וישר ה') שאלו לחכמה חוטא מה עונש והשיבה חטאי' תרדוף רעה, שאלו לנבואה<sup data-n=\"598\">18</sup> השיבה הנפש החוטאת היא תמות, והנה נודע כי נבואה היא בחי' נו\"ה, וא\"כ למה החמירה יותר מחכמה שהוא בחי' ח\"ת, הלא כל מה שגבוה יותר מקילים יותר שלכן התורה השיבה יביא אשם, והקב\"ה יעשה תשובה. וי\"ל שזהו ע\"ד חכם עדיף מנביא, ע' באגה\"ק סי' י\"ט ד\"ה עוטה אור כשלמה, והיינו שידיעת המציאות מבחי' היותר גבוה היינו מבחי' תעלומות חכמה שהחכם משיג, הוא גדול יותר בבחי' זו מהשגת המהות מבחי' ומדריגה שלמטה ממנה שמתגלה להנביא. גם י\"ל שזהו מפני דכתי' ה' בחכ' יסד ארץ שבחי' ארץ ח\"ת יסודה מבחי' ח\"ע, וכמ\"ש בזהר דאבא יסד ברתא, ולכן ח\"ת מקיל יותר לפי ששרשה מח\"ע כו'. וזהו שמצינו בשאול שלאחר שחטא התחיל רוח רעה לבעתו כמ\"ש בש\"א סי' ט\"ז, שכמו שגזרה חכמתו שיהי' מלך, כן כשחטא גזרה חכמתו ית' שיופסק מלכותו. משא\"כ דוד שנמשח בקרן רמה קרני, שהמלוכה שלו הי' למעלה מן החכ', דהיינו שהמלוכה שלו נמשך מבחי' כתר שהוא בחי' רם מרום, שמרום הוא בחי' כתר, וכמ\"ש בנוסח התפלה כי הוא לבדו מרום וקדוש פועל גבורות, שנחשב כאן עשר מדרגות כנגד ע\"ס וכי הוא לבדו קאי על עצמיות אוא\"ס,",[["595","15","<b>וזהו מ\"ש ושם הגדולה לאה. . שגדולה המתנותי'</b>: ראה גם סה\"מ תרכ\"ז שם ע' רצב-ג. ס\"ע שפט-צ."],["596","16","<b>כהונה לעולם וכמ\"ש ברית כהונת עולם</b>: בד\"ה זה ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460030\" data-slug=\"or-hatorah-hb\" data-id=\"8316460030\">אוה\"ת בא (כרך ח</a>) שם נוסף כאן הגה\"ה (כנראה מא' השומעים): והגם שיש כאן קושיא דא\"כ דהכהונה לעולם איך כתי' והכהנים הלוים ואי' בשם האריז\"ל שלע\"ל יהיו לוים כהנים, ואיך הוא, הלא במדרש אמרו כהונה לעולם. וצ\"ע."],["597","17","<b>וזהו משארז\"ל. . שאול באחת. . רמה קרני</b>: בהבא לקמן בפיסקא זו ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490190\" data-slug=\"or-hatorah-hb\" data-id=\"8316490190\">אוה\"ת וירא (כרך ד) תשסד, ב</a>. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370322\" data-slug=\"torah-or\" data-id=\"3901370322\">תו\"א יתרו עב, ג</a>: וזהו שאמרה חנה רמה קרני בה' שדוד שנמשח בקרן הוא בבחי' רמה כו'. שער האמונה לאדהאמ\"צ כח, א."],["598","18","<b>שאלו לחכמה. . שאלו לנבואה</b>: בהבא לקמן — ראה סה\"מ תרל\"ג ח\"ב ע' תקיח. וש\"נ. וראה בהערות שם ע\"ד הגירסאות במארז\"ל זה. וראה גם סה\"מ מלוקט ח\"ה ע' יז. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041357\" data-slug=\"likkutei-sichot\" data-id=\"1300041357\">לקו\"ש ח\"ד ע' 1358</a>."]]],[2000460228,"ומרום הוא בחי' כתר, וקדוש הוא בחי' חכ', פועל גבורות הוא בחי' בינה<sup data-n=\"599\">19</sup>. והנה לפי שהמלוכה שלו נמשכה מבחי' מרום רמה קרני לכך נמשכה מלכותו לעולם וכמ\"ש ואתה מרום לעולם ה' שבחי' מרום הוא לעולם, וזכה דוד לזה לפי שהי' בבחי' ביטול שהוא בחי' קרן (כי קרן הוא בחי' ביטול וכמ\"ש במ\"א, והיינו שהקרן פירושו גם קרן זוית<sup data-n=\"600\">20</sup>, שענין הקרן זוית אינו תופס שום מקום כלל, עד\"מ הקרן שמחבר דופן מזרח עם צפון עד\"מ, שכל מה שנמשך למזרח ה\"ז דופן מזרח, וכל מה שנמשך לצפון ה\"ה דופן צפון, ומהו הקרן הרי אינו שום תפיסות כלל כ\"א שהוא בחי' ביטול, וכן דוד הי' בבחי' ביטול שאמר ע\"ע כי עני ואביון אני, תולעת ולא איש, לפי שהי' בבחי' ביטול כו') לכך נמשכה מלכותו מבחי' רמה קרני.\n<b>והנה</b> בזהר נק' בחי' זו בשם עץ החיים שהוא בחי' אתר דלא אשתני וכמ\"ש פן ישלח ידו ולקח גם מעץ החיים ואכל וחי לעולם, הרי אף לאחר חטא עה\"ד אם הי' אוכל מעה\"ח הי' חי לעולם, רק שזה לא הי' מעלה לפי שכיון שאכל מעה\"ד ונמשך בחי' רע שנתערב טוב ברע<sup data-n=\"601\">21</sup> ממילא אם הי' חי לעולם הי' גם להרע קיום נצחי, לכן לא רצה הקב\"ה שיאכל אחר עה\"ד מעה\"ח לפי שעתה יוכל הרע להתברר, אבל אם הי' אוכל מעה\"ח לא היו יכולים לברר אותו כלל, ולכך ויגרשהו מג\"ע כדי שלא יאכל מעה\"ח, נמצא שעה\"ח הוא בחי' אתר דלא אשתני. והגם שעה\"ח הוא בחי' ת\"ת, אך הנה ידוע שת\"ת עולה עד הכתר שהוא בחי' מרום לעולם כו' לכך גם בחי' עה\"ח שהוא בחי' ת\"ת הוא אתר דלא אשתני, (הג\"ה. וע\"ד מ\"ש בילקוט כשרצה דוד לבנות בהמ\"ק, א\"ל הקב\"ה לא תבנה אתה את הבית הזה, לפי שאם תבנה אתה את הבהמ\"ק לא יחרב לעולם, א\"ל דוד א\"כ אדרבה אני אבנה אותו כדי שלא יחרב, א\"ל הקב\"ה גלוי וידוע לפני שעתידין ישראל לחטוא ומוטב שאכלה חמתי על עצים ואבנים ואל יכלה בהם כו'. והיינו לפי שדוד נמשך מבחי' מרום לעולם שהוא קיים לעד ולכך גם מעשה ידיו הי' להם קיום לעולם כו'). משא\"כ עה\"ד הוא בחי' אתר דאשתני (והנה עה\"ד הוא בחי' מל', ולכך נק' מל' בשם עה\"ד לפי שהיא מתלבשת בבחי' עה\"ד לברר אותו ולכך נק' המל' בשם עה\"ד ג\"כ). והנה נס שנמשך ע\"י בשר ודם שהוא מקבל מעה\"ד אתר דאשתני שאפי' משה רבינו לא נמלט מזה, לכך הוא נס עובר. ובזה יובן מה שסירב בשליחות המקום לפי [שרצה] שיהי' יצ\"מ ע\"י הקב\"ה ואז יהי' הנס קיים לעולם, ולא ע\"י בשר ודם שהוא נס עובר, וכמ\"ש במד\"ר שא' משה מי אנכי<sup data-n=\"602\">22</sup> היינו וכי",[["599","19","<b>כי הוא לבדו מרום וקדוש. . עשר מדרגות כנגד ע\"ס. . פועל גבורות. . בינה</b>: בד\"ה זה באוה\"ת בא (כרך ח) שם מביא זה בשם הפרדס, באוה\"ת שם ממשיך: עושה חדשות חסד, בעל מלחמות גבורה כו' עד אדון הנפלאות מל'."],["600","20","<b>קרן הוא בחי' ביטול וכמ\"ש במ\"א. . קרן זוית</b>: ראה בארוכה ביאוה\"ז לאדהאמ\"צ קמד, ב ואילך. ולהצ\"צ ח\"א ע' תסד ואילך. אוה\"ת נ\"ך ע' קלו ואילך. סה\"מ תרכ\"ז ע' קעו. תרכ\"ט ע' לח. רפט. תרל\"ב ח\"א ע' רסח. ח\"ב ע' תקנא. לקמן סד\"ה הללוי' הללו את ה' מן השמים."],["601","21","<b>פן ישלח ידו ולקח גם מעץ החיים. . שנתערב טוב ברע</b>: בהבא לקמן — ראה בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370020\" data-slug=\"torah-or\" data-id=\"3901370020\">תו\"א בראשית ה, ג</a> ואילך."],["602","22","<b>ובזה יובן מה שסירב בשליחות. . שא' משה מי אנכי</b>: ראה לעיל ד\"ה וככה (הא') פרק ג'. וש\"נ."]]],[2000460229,"בחי' אנכי אני שהבטחת לאביהם אנכי ארד עמך מצרימה ואנכי אעלך גם עלה, ועתה אתה אומר לכה ואשלחך אל פרעה וכי אנכי אני, והיינו לפי שרצה שיהי' הגאולה ע\"ד לע\"ל שיהי' ע\"י אני בעצמי שהוא בחי' אתר דלא אשתני, משא\"כ כשהגאולה ע\"י בשר ודם שהוא בחי' אתר דאשתני, ולכך נק' הגאולה בשם נר שהנר יכול להכבות.\n<b>והגם</b> שנא' וה' הוא ובית דינו שהי' בחי' הוא ג\"כ, שיצ\"מ הי' ע\"י ש' הוי' וכמ\"ש לכן אמור לבנ\"י אני הוי'<sup data-n=\"603\">23</sup> וידעתם כי אני הוי'. אך הענין הוא דכשנמשך שם הוי' ע\"י בית דינו שהוא בחי' ש' אלקי', אזי גובר מדריגת שם אלקי', הגם שנמשך ש' הוי' בגילוי בשם אלקי', ולא ע\"ד מ\"ש שמש ומגן הוי' אלקי' ששם אלקי' מסתיר על ש' הוי', משא\"כ יצ\"מ התגלות נסים ונפלאות הוא מבחי' גילוי ש' הוי', אך מ\"מ כיון שהגילוי הוא ע\"י ש' אלקי' שהוא בחי' שילוב הוי' בשם אד' מתגברים אותיות ש' אד' (וזהו שלא רצה משה בשליחות המלאך שאמר לו ה' הנה אנכי שולח מלאך לפניך, והשיב לו משה אם אין פניך הולכים<sup data-n=\"604\">24</sup> כו', ואף שהוא רק מלאך שהוא בחי' שליח ואינו יכול לעשות שום דבר, ואעפי\"כ לא רצה, לפי שכשנמשך ע\"י מלאך ההמשכה הוא באופן אחר) משא\"כ כשנמשך מבחי' ש' הוי' בעצמו. ואף שש' הוי' הוא בחי' ת\"ת, ויש כמה מדרגות בבחי' ש' הוי', שיש ש' הוי' בבחי' ממכ\"ע, ויש ש' הוי' בבחי' סוכ\"ע וכמ\"ש ויקרא הוי' הוי'<sup data-n=\"605\">25</sup>, מ\"מ הוא בחי' ש' הוי' שהוא בחי' אני בעצמי, שהכל הוא אחד, והיינו שההמשכה הוא ע\"י ש' הוי' לבד. וכמו שאמר יעקב והי' הוי' לי לאלקי', שבחי' ש' הוי' יהי' כאלקי'<sup data-n=\"606\">26</sup>, שלא יהי' נמשך ע\"י ש' אלקי' בחי' אתר דאשתני. אך באמת מבחי' ש' הוי' לבד א\"א לקבל, רק שהוא בחי' שילוב אד' בשם הוי' ששם הוי' גובר ולכך לא יהי' בבחי' שינוי כי אני הוי' לא שניתי. ועוי\"ל דמה שא\"א לקבל כ\"א ע\"י ש' אלקי', זהו מפני ששם אלקי' הוא חלוק מכל השמות שבו נא' אלקינו היינו אלקי' שלנו, כמ\"ש בלק\"ת פ' נצבים בסוף הביאור ע\"פ כי כארץ תוציא צמחה<sup data-n=\"607\">27</sup>, הנה כ\"ז הוא עכשיו, אבל לעתיד הנה ארז\"ל עתידי' צדיקים שיקראו על שמו של הקב\"ה ופי' רש\"י שיהי' שמם הוי'<sup data-n=\"608\">28</sup>, וצדיקים הם המקיימים תומ\"צ כמ\"ש ועמך כולם צדיקים, א\"כ יהי' באפשר לקבל מש' הוי' שלא יהי' נצרך הגבורות וצמצום דש' אלקי' מאחר שיקראו ש' הוי', לכן אז בחי' ש' הוי' עצמו כאלקי' דעכשיו יחשב כו'.",[["603","23","<b>שיצי\"מ הי' ע\"י ש' הוי' וכמ\"ש לכן אמור לבנ\"י אני הוי'</b>: ראה בכ\"ז בארוכה לעיל ד\"ה החודש הזה לכם וד\"ה ששים המה מלכות."],["604","24","<b>שלא רצה משה בשליחות המלאך. . אם אין פניך הולכים</b>: ראה בארוכה אוה\"ת תשא ע' ב'כו ואילך. סה\"מ תרע\"ח ס\"ע ריב ואילך. ובכ\"מ."],["605","25","<b>ויש כמה מדרגות בבחי' ש' הוי'. . וכמ\"ש ויקרא הוי' הוי'</b>: ראה לעיל ד\"ה ששים המה מלכות. וש\"נ."],["606","26","<b>שאמר יעקב והי' הוי' לי לאלקים. . הוי' יהי' כאלקי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370102\" data-slug=\"torah-or\" data-id=\"3901370102\">תו\"א ויצא כא, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370105\" data-slug=\"torah-or\" data-id=\"3901370105\">כב, ג</a>."],["607","27","<b>בלק\"ת פ' נצבים. . ע\"פ כי כארץ תוציא צמחה</b>: דף נג, סע\"ג. וראה גם אוה\"ת וארא ע' ריג. ועוד."],["608","28","<b>עתידי' צדיקי' שיקראו על שמו של הקב\"ה ופי' רש\"י שיהי' שמם הוי'</b>: ראה גם אוה\"ת בראשית (כרך ו) תתרנה, סע\"א ואילך. דברים ע' י. סה\"מ תרכ\"ט ע' קטו. וש\"נ. תרל\"ב ח\"ב ע' שצב. וש\"נ. תרל\"ח ע' כו. וש\"נ. לקמן ד\"ה ובראשי חדשיכם. וש\"נ."]]],[2000460230,"<h3>[אור לארבעה עשר]</h3>\n<b></b><b>בס\"ד. (שבת חוה\"מ פסח. ט\"ל).</b>\nוהנה יצי\"מ כו' אור לארבעה עשר (ב)\nשחוהמ\"פ\n<b>והנה</b> יצ\"מ לפי שנמשך ע\"י ש' אלקי' ולכך נמשך ע\"י בשר ודם ע\"י משה לכך נק' יצ\"מ בשם נר, כמו שנר הוא שאדם מדליקו ולכך הי' הנס עובר, וזהו שאמר אור לארבעה עשר<sup data-n=\"609\">1</sup> בודקין את החמץ לאור הנר.\n<b>אך</b> לפי\"ז יש להבין מ\"ש כי נר מצוה ותורה אור<sup data-n=\"610\">2</sup> שהמשיל את המצוה לנר, שהרי ידוע שתרי\"ג מצות דאורייתא וז' דרבנן הם תר\"ך עמודי אור, ולכך לע\"ל יהי' מעשה גדול<sup data-n=\"611\">3</sup>, וא\"כ למה נק' המצות בשם נר. אך הענין הוא דהנה איתא בגמ' סוטה את זו דרש ר' מנחם ב\"ר יוסי כי נר מצוה ותורה אור המשיל את המצוה לנר והתורה לאור, לומר לך מה נר אינה מגינה לעולם אלא לפי שעה, כך המצוה אינה מגינה אלא לפי שעה. והיינו כי שכר מצוה בהאי עלמא ליכא, רק פרטי מצות יש שאוכל פירותיהם בעוה\"ז, משא\"כ ות\"ת כנגד כולם שנמשך למטה ג\"כ בהאי עלמא, וזהו מה נר אינה מגינה אלא לפי שעה דהיינו שהגנה למטה אינה נמשך אלא לפי שעה, לפי ששכר מצוה בהאי עלמא ליכא, אבל שרש המצות הם באמת בחי' תר\"ך עמודי אור.\n<b>עו\"ש</b> ד\"א עבירה מכבה מצוה ואין עבירה מכבה תורה. ואין לומר שעבירה מכבה את המצוה עצמה<sup data-n=\"612\">4</sup> שהרי אינו מחשבי' מצוה כנגד עבירה, כי מי שיש בידו מחצה זכיות ומחצה עוונות הרי זה מנוחלי עוה\"ב, אלא שנפרעים ממנו על עוונותיו ואינו מאבד זכיותיו ח\"ו. אלא הענין הוא כך דהנה ע\"י כל מצוה נמשך הארה על הנפש בבחי' או\"מ שמקיפו שלא יהי' נפרד מאלקות, והיינו ע\"י קבלת עומ\"ש ועול מצות, וע\"י בחי' התעוררות רחמים שמעורר על נפשו, כאשר יתבונן איך שהמלך המרומם לבדו מאז פי'<sup data-n=\"613\">5</sup> שהוא ית' מרומם ונעלה מגדר עלמין מאז היינו כמו קודם שנבה\"ע, כי כלליות ההתהוות דבי\"ע הוא מהארה לבד שהוא מה שנק' מלך לבד",[["609","1","<b>והנה יצ\"מ. . אור לארבעה עשר</b>: מאמר זה המשך להמאמר שלפניו ד\"ה וככה תאכלו אותו (השני). וראה לקמן בחלק ההנחות שהתחלת המאמר בעת אמירתו הי' ”אור לארבעה עשר\".\nלכללות המאמר ראה בהנסמן לעיל בד\"ה וככה תאכלו (השני) שם בתחילתו."],["610","2","<b>אך לפי\"ז יש להבין מ\"ש כי נר מצוה ותורה אור</b>: בהבא לקמן (עד פיסקא: ועתה י\"ל מה שיצ\"מ) — ראה לעיל ד\"ה וככה (הא') פרק ג (ע' קכג)."],["611","3","<b>לע\"ל יהי' מעשה גדול</b>: ראה סה\"מ תרכ\"ט ע' כד. תרל\"ג ח\"ב ע' תפד. תרל\"ד ע' פט. לקמן ד\"ה ושננתם. סה\"מ מלוקט ח\"ד ע' קיא. [ובהנסמן שם בהערה 23]. וע' קיט."],["612","4","<b>עבירה מכבה מצוה. . ואין לומר שעבירה מכבה את המצוה עצמה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380796\" data-slug=\"likkutei-torah\" data-id=\"4001380796\">לקו\"ת ראה כ, א</a>: עבירה מכבה מצוה דהיינו שמכבה את הנר ונשקע אור האהבה אבל אינו מכבה גוף המצוה עצמה ח\"ו. ועד\"ז שם כב, א. וראה גם דרך חיים קי, ג: דאע\"פ שעבירה מכבה מצוה, הרי אינו מכבה לשרש אור אלקי שבמצוה זו שעשה בפו\"מ שהיא פנימיות רצונו למעלה. עיי\"ש. וראה גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450681\" data-slug=\"or-hatorah-hb\" data-id=\"8316450681\">אוה\"ת ראה ע' תרפא</a>. דרמ\"צ קפח, ב."],["613","5","<b>שהמלך המרומם לבדו מאז פי'</b>: בהבא לקמן בפיסקא זו — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380467\" data-slug=\"likkutei-torah\" data-id=\"4001380467\">לקו\"ת שלח לח, סע\"ד</a> ואילך. [והוא ע\"פ לשון הלקו\"ת שם בשינויים והוספות]. ובארוכה במאמרי אדהאמ\"צ במדבר ח\"ג ע' א'מג ואילך."]]],[2000460231,"כמ\"ש מלכותך מלכות כל עולמי', ואי לזאת אנו אומרים ברחמיך הרבים רחם עלינו אדון עוזינו פי' שהרחמנות גדולה מאד על האדם שהוא חלק הוי' שנתגשם ורחוק מאד מה' בתכלית, ואומרי' אדון עוזינו שהגם שאין אוא\"ס נתפס בבחי' פנימיות להיות תוכה רצוף אהבה, מ\"מ ה\"ה אדון עוזינו, פי' אדון זו קבלת מלכותו בחי' שום תשים עליך מלכותו ית' בבחי' מקיף, והיינו ע\"י שמקיים מצותיו ית' בדרך קבלת עול לקיים מצות המלך כו', ומבחי' מקיף זה נמשך ג' מקיפי' דצור מגן משגב<sup data-n=\"614\">6</sup> שאומרי' אח\"כ שהם ג' מקיפי' לבחי' מחדו\"מ, וג' בחי' נר\"נ להקיף ולהלביש את הנר\"נ<sup data-n=\"615\">7</sup> להתכלל באוא\"ס, ולהיות צרורה בצרור החיים את ה', ומקיפי' אלו נמשכי' ע\"י מעשה המצות<sup data-n=\"616\">8</sup> שהם ג\"כ בג' בחי' מחדו\"מ, שיש מצות שתלוי' במח' וכוונת הלב שאם כיון לבו יצא וא\"ל לא יצא, ויש שתלוי' בדבור, ורובם במעשה. וזהו דכתי' והלך לפניך צדקך וכבוד כו', פי' צדקך הוא כלליות המצות שנק' בשם צדקה כמ\"ש וצדקה תהי' לנו כו', ועי\"ז יאספך בחי' כבוד ה' הוא בחי' המקיף להגבי' את הנר\"נ ומחדו\"מ של האדם כי כל עלי' הוא ע\"י בחי' מקיף דוקא, והוא הלבוש של הנשמה בעוה\"ב, וע' בלק\"ת בד\"ה ועתה יגדל נא<sup data-n=\"617\">9</sup> סס\"י א'. וגם בעודנו חי בעוה\"ז פועל בחי' מקיף זה שיעשה עוד מצות וכמארז\"ל מצוה גוררת מצוה לפי שנמשך הארת או\"מ על הנפש. והנה הארה זו שנמשך ע\"י המצוה על הנפש, בחי' זו עבירה מכבה, ולכך נק' המצוה בשם נר. ועוי\"ל כמ\"ש בלק\"ת בד\"ה אחרי הוי'<sup data-n=\"618\">10</sup> פ\"ג שנר הוא בגימט' רמ\"ח פקודין ותרין דרועין, שע\"י המצוה נמשך בחי' אהוי\"ר, והנה בחי' אהוי\"ר שנמשך מהמצוה בחי' זו עבירה מכבה, אבל לא ח\"ו עצם המצוה עבירה מכבה.\n<b>והתורה</b> נמשל לאור שאין עבירה מכבה אותה כלל, אפי' בחי' שנמשך למטה על הנפש וכמ\"ש במד\"ר ע\"פ ואותי עזבו ואת תורתי לא שמרו (ירמי' ט\"ז י\"א) הלואי אותי עזבו ותורתי שמרו מתוך שתורתי שמרו המאור שבה מחזירם למוטב, נמצא שהתורה נק' מאור<sup data-n=\"619\">11</sup>, וגם יש בכח התורה להחזיר למוטב, שאדרבה שהתורה מתקן את הפגם של עבירה, והיינו לפי שהגם ששרש המצות הם בחי' תר\"ך עמודי אור שהם בחי' רצה\"ע, אעפי\"כ עיקר המצות הם בבחי' מל' שנקראי' מצות המלך והיינו שהם בבחי' ו\"ה שאין היחוד בתמידות רק לפרקי', והיינו לפי שיחוד ו\"ה תלוי בבחי' אתעדל\"ת דוקא, ולכך נק' נר כמו שנר האדם מדליקו, וכך למעלה נר הוא בחי' מל' דל\"ל מגרמה כלום והאדם מדליקה שממשיך בתוכה שמן ופתילה ואור ושמן, שמן הוא בחי' חכ', ואור הוא בחי' כתר, ופתילה הוא בחי' יסוד, והנר",[["614","6","<b>אדון עוזינו. . ומבחי' מקיף זה נמשך ג' מקיפי' דצור מגן משגב</b>: ראה [נוסף ל<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380265\" data-slug=\"likkutei-torah\" data-id=\"4001380265\">לקו\"ת</a> שלח שם] גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380913\" data-slug=\"likkutei-torah\" data-id=\"4001380913\">לקו\"ת בהר מד, ב</a>. נצבים מח, ג. וראה אוה\"ת סידור ע' קכב ואילך."],["615","7","<b>ולהלביש את הנר\"נ</b>: בגוכתי\"ק אדמו\"ר מהר\"ש נרשם בתחילה: ”הנפש\", ואח\"כ נרשם ממעל: ”הנר\"נ\"."],["616","8","<b>להיות צרורה בצרור החיים. . ומקיפי' אלו. . ע\"י מעשה המצות</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370175\" data-slug=\"torah-or\" data-id=\"3901370175\">תו\"א מקץ לח, ג</a>."],["617","9","<b>בלק\"ת בד\"ה ואתה יגדל נא</b>: לקו\"ת שלח שם."],["618","10","<b>בלק\"ת בד\"ה אחרי הוי'</b>: פ' ראה דף כ, א שם."],["619","11","<b>המאור שבה מחזירם למוטב. . שהתורה נק' מאור</b>: ראה בכ\"ז סה\"מ תרכ\"ט ע' רצ. ועוד."]]],[2000460232,"הוא בחי' מל', אבל התורה הוא בחי' יחוד י\"ה שהם בחי' ריעים, תרין ריעין דלא מתפרשין לעלמין, שאין היחוד תלוי באתעדל\"ת כלל רק שהוא בחי' אתדל\"ע שלמעלה מאתעדל\"ת, ולכך נק' התורה אור.\n<b>ועתה</b> י\"ל מה שיצ\"מ הי' בחפזון דוקא<sup data-n=\"620\">12</sup>, אך הענין הוא דהנה נס דיצ\"מ הי' בלילה וכמ\"ש ויהי בחצי הלילה וכנ\"ל, והנה בליל פסח כתי' ליל שמורים הוא, ופי' ליל שמורים היינו ב' בחי' שמירה, הפי' הא' היינו שבחי' מדת לילה שהוא בחי' מל' צריכה שימור, לפי שמל' נעשה מקור לעולמות בי\"ע ששם יש רע ג\"כ כו', לכך צריכה שימור שלא יהי' מבחי' זו יניקת החיצוני', שבחי' מדת יום שהוא בחי' אצי'<sup data-n=\"621\">13</sup> א\"צ שימור כלל לפי ששם כתי' לא יגורך רע. ואף שיש קליפה גם נגד עולם האצי' אעפ\"כ אפי' קליפה שכנגד אצי' המעמד שלה היא בבריאה<sup data-n=\"622\">14</sup>, לכן א\"צ שמירה, רק בחי' מדת לילה שהוא בחי' מל' צריכה שמירה. וזהו מ\"ש בזהר שיש י\"ג עלין דסחרין לשושנה, שושנה הוא בחי' מדת מל', וי\"ג עלין דסחרין לשושנה לשמור אותה מיניקת החיצוני', ויש ה' עלין תקיפין לאגנא עלה. וזהו משארז\"ל שלש משמורות הוי הלילה משמורה ראשונה חמור נוער, שני' כלבים צועקי' שהם בחי' קליפות<sup data-n=\"623\">15</sup>, ולכך הלילה צריך שמירה (ואפי' ליל שבת צריך שמירה ולכך אומרים מגן אבות כו'). וזהו ע\"ד ברכות נשואין שברכה ראשונה פותח בברוך ואינו חותם בברוך, וברכה שני' פותח בברוך וחותם בברוך, לפי ששני ברכות אלו הם כנגד אדם וחוה<sup data-n=\"624\">16</sup> שהוא בחי' מדת יום ומדת לילה (כמ\"ש יום ליום יביע אומר ולילה ללילה יחוה דעת), וגם שהוא כנגד תושב\"כ ותו' שבע\"פ שנק' ג\"כ מדת יום ומדת לילה וכמ\"ש בילקוט פ' כי תשא ע\"פ ויהי שם עם ה' ארבעים יום וארבעים לילה, מנין הי' יודע משה אימתי יום ואימתי לילה, שהרי כתי' ונהורא עמי' שרי', אלא כשהי' לומד מקרא הי' יודע שהוא יום, וכשהי' לומד משנה הי' יודע שהוא לילה<sup data-n=\"625\">17</sup>, נמצא שתושבע\"פ נק' מדת לילה. ולכך ברכה שני' פותח בברוך וחותם בברוך שצריך חתימה שלא יהי' יניקת החיצוני' מבחי' זו. וזהו משארז\"ל שמור זו משנה, שמשנה צריכה שימור שלא ילמוד לשם גסות ולהתייהר וכמ\"ש ושמתם סם תם זכה נעשה לו סם חיים לא זכה כו'. משא\"כ בתושב\"כ אינו שייך עדיין בחי' גסות. וזהו שנא' ליל שמורים שמדת לילה צריכה שימור.\n<b>ועוי\"ל</b> פי' שמורים הוא מל' ואביו שמר את הדבר שהוא בחי' המתנה, וכן בגמ' איתא המשתמרת לביאה, והיינו לפי שבליל פסח הי' נגלה בחי' מלך מלכי",[["620","12","<b>ועתה י\"ל מה שיצ\"מ הי' בחפזון דוקא</b>: בהבא לקמן (עד פיסקא: והנה אף שחפזון) — ראה לעיל ד\"ה וככה (הא') פרק ד (ע' קכח ואילך)."],["621","13","<b>מדת לילה. . מל'. . מדת יום. . אצי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370169\" data-slug=\"torah-or\" data-id=\"3901370169\">תו\"א מקץ לז, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370172\" data-slug=\"torah-or\" data-id=\"3901370172\">לז, ד</a> ואילך."],["622","14","<b>ואף שיש קליפה גם נגד עולם האצי'. . היא בבריאה</b>: ראה סה\"מ תרכ\"ט ע' קלט. וש\"נ."],["623","15","<b>שלש משמורות הוי הלילה. . שהם בחי' קליפות</b>: ראה גם סה\"מ תרכ\"ו ע' שכד. תרכ\"ט ע' קמב. תרל\"ב ח\"א ע' כד. וש\"נ. וע' לא."],["624","16","<b>ברכות נשואין. . פותח בברוך. . כנגד אדם וחוה</b>: ראה בכ\"ז בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370023\" data-slug=\"torah-or\" data-id=\"3901370023\">תו\"א בראשית ו, ב</a> ואילך. ובארוכה סה\"מ תרל\"ח ע' קפה ואילך."],["625","17","<b>וכמ\"ש בילקוט. . כשהי' לומד מקרא הי' יודע שהוא יום. . לילה</b>: ראה גם יהל אור להצ\"צ ס\"ע סב ואילך. סה\"מ תרל\"ב ח\"א ע' עדר."]]],[2000460233,"המלכים וכמשארז\"ל עד שנגלה עליהם ממה\"מ הקב\"ה, וזהו שנק' ליל שמורים שהלילה היתה משתמרת על בחי' יחוד זה שיהי' בחי' יחוד סוכ\"ע בממכ\"ע (שנק' בשם חתן וכלה) וכמ\"ש בזהר דכר הוה זמין לאחברא עמה. וזהו ג\"כ ענין זכור ושמור, זכור לדכורא<sup data-n=\"626\">18</sup> שמור לנוק', ולכך נק' שמור לפי שמשתמרת לדכורא. וזהו ג\"כ ענין מצה שמורה לפי שמצפה ומשתמרת על הגילוי שיומשך לה מלמעלה, וכן נק' לחם עוני היינו כמו שהעני מצפה וממתין על השפעת העשיר כמו\"כ המל' נק' לחם עוני שמצפה וממתין על היחוד בחי' צדיק אוכל לשובע נפשו ע\"ד קראן לו ויאכל לחם.\n<b>וזהו</b> שנא' ליל שמורים שסובל ב' הפירושי' של שימור. ובאמת ב' הפי' הם ענין א' ממש, והיינו לפי שמשמרת ומצפה על בחי' גילוי אור עליון, לכך מהאי טעמא צריכה שימור, לפי שאז מתקנאין הקליפות ויכול להיות אז יניקת החיצוני' וכמ\"ש בזהר ובגין דלא תשלוט בה עין הרע לכך מחלפי אתוון ועד בחילופי אתוון דאחד. ודוגמא לזה הוא מה שקא חשיב (במשנה אבות פ' ה') מעשרה נסים שנעשו לאבותינו בבהמ\"ק לא אירע קרי לכ\"ג ביוהכ\"פ, דלכאו' קשה ולמה יארע לו קרי שהרי מסתמא כה\"ג הי' גדול בישראל, וגם שהי' ביוה\"כ שכל ישראל הם בטהרה, וגם שהיו מזרזין אותו כל שבעת הימים. והתשובה לפי שהי' כה\"ג וביוהכ\"פ לכן מתקנאים בו הקליפות<sup data-n=\"627\">19</sup>, ולזה הי' קרוב מאד להיות הכהן בעל קרי. וכך עד\"ז לפי שהיא משתמרת ליחוד עליון המשכת סוכ\"ע לכן צריכה שמורים. וזהו שיצ\"מ הי' ע\"י חפזון כדי שלא יהי' יניקת החיצוני'.\n<b>ובנפש</b> ענין בחי' השמירה זהו מ\"ש כי ברח העם, שהקשה בתניא<sup data-n=\"628\">20</sup> למה היו צריכים לברוח שהרי אם היו רוצים הי' פרעה משלחם בע\"כ. ותי' לפי שהיו במצרים מושקעים במ\"ט שע\"ט, לפיכך היו צריכים לברוח מן הרע. ולהיכן צריך לברוח לתורה, וזהו מ\"ש דרך שלשת ימים נלך במדבר שהוא כנגד מחדו\"מ של תורה, וכמ\"ש במד\"ר פנו לכם צפונה הצפינו עצמיכם בתורה, ולכך הי' יצ\"מ בחפזון. ובזה יובן הקושי' שהקשה השל\"ה מהו המעלה של חפזון<sup data-n=\"629\">21</sup> שיצאו ממצרים בחפזון, והיינו לפי שהוא ע\"ד יראת חטא שירא מהחטא עצמו, וכך הי' חפזון שברחו מהרע כדי שלא יהי' ח\"ו יניקת החיצונים כו'.\n<b>והנה</b> אף שחפזון הוא מעלה<sup data-n=\"630\">22</sup>, מ\"מ כשלא יהי' צריך לחפזון אזי הוא יותר מעלה, לפי שחפזון הוא קרוב לנחלה מבוהלת הנאמר על נחלת בני גד ובני ראובן שמיהרו וחפזו וקיבלו נחלתן מעבר לירדן, שאם לא היו ממהרים היו מקבלים",[["626","18","<b><a class=\"ft-cite\" href=\"#/read/torah-or/3901370318\" data-slug=\"torah-or\" data-id=\"3901370318\">וזהו ג</a>\"כ ענין זכור ושמור זכור לדכורא</b>: ראה בכ\"ז תו\"א יתרו עא, סע\"ג-ד. סה\"מ תרכ\"ז ע' קל."],["627","19","<b>לפי שהי' כה\"ג וביוהכ\"פ לכן מתקנאים בו הקליפות</b>: ראה גם אוה\"ת מג\"א (הוצאת תש\"נ) ע' רסד."],["628","20","<b>כי ברח העם שהקשה ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא</b>: פרק לא (מ, ב</a>)."],["629","21","<b>הקושי' שהקשה השל\"ה מהו המעלה של חפזון</b>: ראה לעיל ד\"ה וככה (הא') פרק ח פיסקא: וע' מענין זהירות (ע' קלא ואילך)."],["630","22","<b>והנה אף שחפזון הוא מעלה</b>: בהבא לקמן עד סוף מאמר זה ראה לעיל ד\"ה וככה שם פרק ה (ע' קכט ואילך)."]]],[2000460234,"נחלתם בא\"י (שלגבי א\"י נק' מעבר לירדן ארץ טמאה<sup data-n=\"631\">23</sup> וכמ\"ש ביהושע ואם טמאה ארץ אחוזתכם), ולכך כשא\"צ לחפזון אז הוא יותר מעלה. וזהו שהי' חטא אדה\"ר שנחפז להזדווג קודם שבת, שאם הי' ממתין<sup data-n=\"632\">24</sup> עד שבת אז הי' כל פריו קדש כו'. ומ\"מ לא דמי לכאן, ששם לא הי' צריך לחפזון שהחפזון לא הי' בעתו משא\"כ כאן שהחפזון הי' בעת שהיו צריכים באותו שעה לחפזון. והיינו לפי שעתה צ\"ל חפזון לפי שעתה יש בחי' רע, ולכך צ\"ל חפזון כדי שלא יהי' יניקת החיצונים.\n<b>משא\"כ</b> לע\"ל כתי' כי לא בחפזון תצאו שלא יהי' צריך לחפזון, לפי שאז ואת רוה\"ט אעביר מן הארץ ולא יהי' בחי' רע כלל לכן א\"צ לחפזון, וכשהוא בלא חפזון אז יותר טוב. והגם שאמרו זריזין מקדימין למצות, אך מ\"מ המעשה של המצוה עצמה צ\"ל במתון<sup data-n=\"633\">25</sup> ולא בחפזון, לפי שכל דבר הנעשה ביישוב הדעת הוא נעשה בטוב יותר כו'. וע\"ד שארז\"ל חסידים הראשונים היו שוהין ט' שעות ביום, לפי שע\"י שהיו שוהין בתפלתן עי\"ז יש לאהוי\"ר שלהם יותר קיום, והיינו שזהו ההפרש בין צדיק לבינוני<sup data-n=\"634\">26</sup>, שבבינוני צ\"ל כי ברח העם שצריך לברוח מהרע כדי שלא יפול במחשבות זרות, משא\"כ צדיק שאין בו רע כלל אינו ירא מפני מח\"ז, ולכך היו שוהים בתפלתן שעי\"ז יש לאהוי\"ר יותר קיום. וכך לע\"ל לא יהי' צריך לחפזון לברוח מהרע, לפי שלא יהי' רע כלל, רק שהעלי' יהי'<sup data-n=\"635\">27</sup> לצאת מחיצוני' הלב לפנימי' הלב, או מאהבה כמים הפנים לפנים לבחי' אהבה בכל מאדך.\n<b>וזהו</b> שנא' לע\"ל ומל ה' אלקיך את לבבך, כי עתה נא' ומלתם את ערלת לבבכם<sup data-n=\"636\">28</sup> שנא' ערלת לבבכם, והיינו כי ערלת לבבכם הוא בחי' תאוות גשמי' שהוא בחי' רע, משא\"כ לע\"ל נא' ומל הוי' את לבבך שלא נא' ערלה לפי שלא יהי' בחי' רע כלל רק שיהי' העלי' מחיצוני' הלב לפנימי' הלב ולכך ומל הוי' את לבבך, שאין זה בכח האדם עצמו, ולכך לא יהי' בחי' חפזון.\n<b>",[["631","23","<b>שלגבי א\"י נק' מעבר לירדן ארץ טמאה</b>: ראה עוד אודות עבר הירדן בסה\"מ תרכ\"ט ע' רפב. וראה אודות הדיעות בזה ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021418\" data-slug=\"likkutei-sichot\" data-id=\"1300021418\">לקו\"ש ח\"ב ע' 695</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131124\" data-slug=\"likkutei-sichot\" data-id=\"1300131124\">חי\"ג ע' 124</a> <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300281054\" data-slug=\"likkutei-sichot\" data-id=\"1300281054\">[ובהע' 20</a> שם]. חכ\"ח 214 [ובהע' 54 שם. וש\"נ]. ס' השיחות תש\"נ ח\"ב ע' 546 [הע' 68, ובשוה\"ג שם]."],["632","24","<b>וזהו שהי' חטא אדה\"ר. . שאם הי' ממתין</b>: ראה לעיל ע' קל (שם) וש\"נ."],["633","25","<b>והגם שאמרו זריזין מקדימין. . המצוה עצמה צ\"ל במתון</b>: ראה לעיל ד\"ה וככה (הא') פרק ח (פיסקא: וע' מענין זריזות)."],["634","26","<b>שזהו ההפרש בין צדיק לבינוני</b>: ראה תניא פ\"י ופי\"ב."],["635","27","<b><a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300291356\" data-slug=\"likkutei-sichot\" data-id=\"1300291356\">לע\"ל</a> לא יהי' צריך לחפזון לברוח מהרע. . שהעלי' יהי'</b>: ראה גם לקו\"ש חכ\"ט ע' 341 ואילך."],["636","28","<b>ומל ה' אלקיך. . עתה נא' ומלתם את ערלת לבבכם</b>: ראה אגה\"ק ס\"ד (קה, ב ואילך). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380790\" data-slug=\"likkutei-torah\" data-id=\"4001380790\">לקו\"ת ראה יח, סע\"ג</a>-ד. סה\"מ תרל\"ג ח\"ב ע' שצט ואילך. וע' תמט ואילך. ובכ\"מ."]]],[2000460235,"<h3></b>[להבין מה שיצי\"מ נק' נר] והנה בילקוט כו' כי בחפזון (ג)</h3>\n<b>והנה</b> בילקוט פ' בא<sup data-n=\"637\">1</sup> בשם המכילתא איתא כי בחפזון<sup data-n=\"638\">2</sup> יצאת ממצרים, חפזון של מי, חפזון של שכינה, אע\"פ שאין ראי' לדבר זכר לדבר, קול דודי הנה זה בא מדלג כו'. והיינו שגם בבחי' דודי שהוא בחי' ז\"א הי' ג\"כ בחי' חפזון. והגם שמדת יום א\"צ שמירה, לפי ששם כתי' לא יגורך רע וא\"א להיות משם יניקת החיצונים וא\"כ א\"צ לחפזון. אך היינו כמ\"ש בזהר שבחי' דודים תאיבין דא לדא ולא משתכחין תדיר, ולכך הי' למעלה בבחי' ז\"א ג\"כ חפזון כדי שלא ימנעו היחוד עליון כו' לפי שתאיבין דא לדא. ומ\"מ החפזון דבחי' דודי זהו רק זכר לדבר, ועיקר החפזון הי' בבחי' שכינה, השוכן אתם, גלו למצרים שכינה עמהם כו'.\n<b>אך</b> לע\"ל נא' ביום ההוא יהי'<sup data-n=\"639\">3</sup>, ב' פעמים י\"ה, שיהי' בבחי' ו\"ה ג\"כ היחוד כמו בבחי' י\"ה, בחי' ריעין, תרין ריעין דלא מתפרשין, לכך לא יהי' צריך אז לחפזון. נמצא שמה שהי' צ\"ל בחפזון זהו לפי שהי' הנס בלילה. ולכך נק' הנס דיצ\"מ בשם נר לפי שהי' נס עובר.\n<b>וזהו</b> מ\"ש בתרגום יונתן ע\"פ כי אתה נרי<sup data-n=\"640\">4</sup> הוי' והוי' יגיה חשכי, ארי את הוא מארי נהורא דישראל ה', וה' יפקינני מחשוכא לנהורא ויחזינני בעלמא דעתיד למיתי לצדיקייא.\n<b>נמצא</b> שמפרש פי' כי אתה נרי הוי' בעוה\"ז, וה' יגיה חשכי על לע\"ל, והיינו לפי שעתה אפי' הנס דיצ\"מ הוא רק בחי' נר. דהנה על יצ\"מ נא' עד שנגלה עליהם מלך מלכי המלכים<sup data-n=\"641\">5</sup> הקב\"ה, והנה פי' מלך מלכי המלכים כו' הוא ענין מ\"ש מלכותך מלכות כל עולמים פי' מלכות כל עולמים קאי על מל' דאצי' שמחי' עולמות בי\"ע, ולכבודי בראתיו יצרתיו אף עשיתיו, והנה מבחי' זו נמשך בחי' עולמים שהוא בחי' העלם והסתר כו'. אך בחי' מלכותך הוא שכמו שבחי' מל' הוא בעצמותו, כמו עד\"מ זיו השמש הכלול בשמש<sup data-n=\"642\">6</sup> עצמו שאינו נראה שם כלל, רק הוא בטל בעצמותו ואין אורו וזיוו ניכר כלל רק על הארץ כו'. וזהו עד שלא נבה\"ע הי' הוא ושמו בלבד",[["637","1","<b>בילקוט פ' בא</b>: בהבא לקמן בפיסקא זו — ראה לעיל ד\"ה וככה (הא') פרק ו. סה\"מ תרכ\"ט ע' קלד. וש\"נ. שם ע' קמג."],["638","2","<b>והנה בילקוט. . כי בחפזון</b>: מאמר זה נאמר באחרון של פסח, והוא המשך למאמרים שלפניו (ד\"ה וככה תאכלו (הב') וד\"ה והנה יצ\"מ כו' אור לארבעה עשר). וראה לקמן בחלק ההנחות (מאחש\"פ) שהתחלת מאמר זה בעת אמירתו הי': להבין מה שיצ\"מ נק' בשם נר.\nלכללות המאמר ראה לעיל ד\"ה וככה תאכלו (הב') בתחילתו."],["639","3","<b>אך לע\"ל נא' ביום ההוא יהי'</b>: בהבא לקמן בפיסקא זו — ראה לעיל ד\"ה וככה (הא') ריש פרק ז."],["640","4","<b>וזהו מ\"ש בתרגום יונתן ע\"פ כי אתה נרי</b>: בהבא לקמן (עד פיסקא: ועוי\"ל שיש הפרש) — ראה לעיל ד\"ה וככה (הא') פרק יא פיסקא: והענין י\"ל עפמ\"ש."],["641","5","<b>דהנה על יצ\"מ נא' עד שנגלה עליהם ממה\"מ</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381187\" data-slug=\"likkutei-torah\" data-id=\"4001381187\">לקו\"ת שה\"ש יד, ג</a> ואילך. סה\"מ תרכ\"ט שם ע' קלה ואילך. תרל\"ב ח\"א ע' כ ואילך. וע' כח ואילך."],["642","6","<b>עד\"מ זיו השמש הכלול בשמש</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310038\" data-slug=\"tanya\" data-id=\"3401310038\">תניא פל\"ג (מב, א</a>). שעהיוה\"א פ\"ג (עח, א). ובכ\"מ."]]],[2000460236,"דהיינו שהי' שמו כלול בעצמותו. ופי' מלכותך מלכות כל עולמים היינו שנמשך מבחי' מלכותך (שהוא בחי' מל' דא\"ס)<sup data-n=\"643\">7</sup> בבחי' מל' כל עולמים. וזהו ג\"כ ענין שנגלה עליהם מלך מלכי המלכים הקב\"ה, כי מלכים הוא בחי' זו\"נ דאצי', ומלכי המלכים הוא בחי' חו\"ב, ומלך מלכי המלכים הוא בחי' כ\"ע<sup data-n=\"644\">8</sup> דאיהו כתר מל' (שהוא בחי' מל' דא\"ס).\n<b>והנה</b> בחי' זו נק' נר הוי', שצ\"ל נמשך ע\"י ד' אותיות דש' הוי', וזהו שנק' נר כמו שבנר יש ד' בחי', שמן ופתילה ואור<sup data-n=\"645\">9</sup>, והיינו שהשמן הוא בחי' חכ', ופתילה הוא בחי' יסוד, ואור הוא בחי' כתר בחי' מלך מלכי המלכים, וכל ההמשכות נמשכי' בנר שהוא בחי' מלכות כל עולמים, ולכך נק' נר. והנה לפי שנמשך בחי' מלך מלכי המלכים ע\"י השתלשלו' ולכך יכול להיות הנס עובר כמו שנר מאיר את החשך ודוחה אותו, אבל אעפ\"כ החשך הוא נשאר חשך, ולכך כשכלה הנר חוזר החשך, ולפי שגאולת מצרים הי' ע\"י בחי' מלך מלכי המלכים שנמשך בחי' מלך ע\"י השתלשלו' מלכי המלכים שהוא בחי' נר, לכך חזרו ונשתעבדו.\n<b>ולהבין</b> ההפרש שבין גאולת מצרים וגאולת חנני' מישאל ועזרי' וכן מתתי' כה\"ג שנק' ג\"כ בשם נר, י\"ל שההפרש הוא ע\"ד בין נר לאבוקה, וכך י\"ל שגאולת מצרים שהי' ע\"י משה ואהרן הוא בחי' אבוקה שמאיר למרחוק, ולכך נמשך הגאולה ט' מאות שנה, והיו הנסים של יצ\"מ נסים שלמעלה מן הטבע, משא\"כ שאר גאולות הם רק בחי' נר ולכך היו הנסים מלובשים בטבע כו'. אך כ\"ז הוא רק בחי' נר, שגם אבוקה דיצ\"מ בכלל נר וכמו שהמשילו בגמ' סוטה דך\"א ע\"א הנ\"ל ענין נזדמנה לו אבוקה של אור על בחי' נר מצוה לפי שאבוקה ג\"כ בכלל נר כו'.\n<b>אבל</b> לע\"ל כתי' והוי' יגיה חשכי שיפקינני מחשוכא לנהורא, שהחשך יתהפך לאור כו' ולילה כיום יאיר<sup data-n=\"e17\">*</sup>, והי' אור הלבנה כאור החמה, ונמצא שלא יהי' בחי' לילה במציאות כלל, ולכך לא יהי' עוד עיבור שהוא בחי' גלות כו', ולכן יהי' השיר לשון זכר שיר הזה כנ\"ל.",[["643","7","<b>מלכותך (שהוא בחי' מל' דא\"ס)</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370327\" data-slug=\"torah-or\" data-id=\"3901370327\">תו\"א יתרו עג, סע\"ד</a>. ועוד."],["644","8","<b>מלכים. . זו\"נ דאצי'. . ומלכי המלכים. . חו\"ב וממה\"מ. . כ\"ע</b>: ראה גם סה\"מ תרל\"ב ח\"א ע' רפז. ועוד."],["645","9","<b><a class=\"ft-cite\" href=\"#/read/torah-or/3901370154\" data-slug=\"torah-or\" data-id=\"3901370154\">שבנר יש ד</a>' בחי' שמן ופתילה ואור</b>: ראה לעיל ד\"ה וככה (הא') פי\"א שם: ד' בחי' שבנר פתילה ושמן וב' גווני אור נהורא תיכלא ונהורא חיוורא. וראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370182\" data-slug=\"torah-or\" data-id=\"3901370182\">תו\"א מקץ לג, ב</a>-ג. מ, ב. ובכ\"מ."],["e17","*","<b>אבל לע\"ל. . ולילה כיום יאיר</b>: בהגהות על המאמר נוסף כאן בגוכי\"ק [ואח\"כ נרשם ע\"ז: להעתיק בשיפולי העמוד בהיפוך]: יש להעיר לענין שלע\"ל הלילה כיום יאיר ממ\"ש כי אלף שנים בעיניך כיום אתמול שיומו של הקב\"ה הוא אלף שנה, וא\"כ שית אלפי שנה הם ששה ימים, ולע\"ל הוא יום השבת, ובשבת לא נא' ויהי ערב ויהי בקר, כי ל\"ו שעות שמשה אותה האורה כמ\"ש במד\"ר בראשית פי\"א, י\"ב של ערב שבת, וי\"ב של לילי שבת, וי\"ב של שבת, א\"כ גם הלילה כיום ממש יאיר."]]],[2000460237,"<b>והנה</b> בגמ' סוטה הנ\"ל המשילו מ\"ש ותורה אור לבחי' אור היום, שאמרו שם עלה עמוד השחר ניצול כו' שקאי על זכות התורה ע\"ש. לכן בזה י\"ל לפי שהתורה נק' אור שהוא אור היום, לכך כתי' בה והיו הדברים האלה אשר אנכי מצוך היום, מצוך הוא לשון התחברות, שהוא מחבר בחי' יום, שהוא ממשיך ומחבר בחי' יום שיהי' אור הלבנה כאור החמה. ולכך התורה היא למעלה מן הזמן שכל המצות הם בבחי' זמן<sup data-n=\"646\">10</sup> כמו למשל מצות סוכה הוא בזמן סוכות אז הוא מצוה, וכן מצות מצה בפסח דוקא הוא מצוה, משא\"כ בשאר ימות השנה אינו מצוה כלל, והוא מפני שהמצות הם בחי' מצות המלך, הגם כי בשרשם תרי\"ג מצות וז' דרבנן הם תר\"ך עמודי אור<sup data-n=\"647\">11</sup> בחי' כתר, עכ\"ז עיקרם במל'<sup data-n=\"648\">12</sup> שהוא שרש ומקור הזמן מלך מלך ימלוך. משא\"כ התורה היא למעלה מן הזמן שאם הוא עוסק אפי' בשאר ימות השנה בלימוד מצות סוכה הוא ג\"כ מצוה כמו בזמן סוכות, רק שדבר בעתו מה טוב, אבל לענין המצוה הוא שוה כלומד הלכות סוכה או הלכות פסח בשאר ימות השנה כמו בסוכות או בפסח כו', והיינו לפי שהתו' הוא בחי' יום שגם הלילה נעשה יום. ולכן הכל מודים שמ\"ת הי' בשבת, ובשבת לא נא' בתורה במע\"ב לילה, שרק עד יום הששי נא' ויהי ערב ויהי בקר יום הששי, וכמארז\"ל במד\"ר פ' בראשית פי\"א ל\"ו שעות שמשה אותה האורה, י\"ב של ערב שבת, וי\"ב של לילי שבת וי\"ב של שבת, א\"כ גם הלילה הי' יום ממש כו', ולכן מובן קצת שגם בתורה שלמטה שניתנה בשבת יש כח זה. והגם שבמצות כתי' ג\"כ והי' אם שמוע תשמעו אל מצותי כו' מצוה אתכם היום, עכ\"ז עיקרם במל' שהרי הם מלובשי' בזמן דוקא, וכמ\"ש בתשו' הרשב\"א שהם מלובשי' בזמן ומקום וכלים<sup data-n=\"649\">13</sup>, משא\"כ לימוד התורה הוא למעלה מן הזמן. וי\"ל שלכן למי שהוא פנוי מעסק צ\"ל הלימוד יומם ולילה כמ\"ש והגית בה יומם ולילה, א\"כ ה\"ז למעלה מן הזמן. וזהו מ\"ש כימי השמים על הארץ<sup data-n=\"650\">14</sup> כו', ולפי שלע\"ל הלילה יהי' יום לכך לא יהי' הנס עובר כו'.\n<b>ועוי\"ל</b> שיש הפרש בין יצ\"מ ללע\"ל<sup data-n=\"651\">15</sup>, זהו ע\"ד ההפרש בין קומה ה' למנוחתיך ובין קומה ה' ויפוצו אויביך<sup data-n=\"652\">16</sup>, שיצ\"מ הי' ע\"י מלחמה, וכמ\"ש וחמושים עלו בנ\"י",[["646","10","<b>התורה היא למעלה מן הזמן. . המצות. . בבחי' זמן</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380360\" data-slug=\"likkutei-torah\" data-id=\"4001380360\">לקו\"ת במדבר יג, א</a>. סה\"מ תרכ\"ז ע' שלו (בשוה\"ג). תרל\"ג ח\"ב ע' שעה. וראה גם הנסמן בהערה שלאח\"ז."],["647","11","<b>תרי\"ג מצות וז' דרבנן. . תר\"ך עמודי אור</b>: ראה אגה\"ק סכ\"ט (קמט, סע\"ב ואילך)."],["648","12","<b>שהמצות הם בחי' מצות המלך. . עיקרם במל'</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380193\" data-slug=\"likkutei-torah\" data-id=\"4001380193\">לקו\"ת אחרי כז, סע\"ב</a>."],["649","13","<b>וכמ\"ש בתשו' הרשב\"א שהם מלובשי' בזמן ומקום וכלים</b>: ראה סה\"מ תרל\"ג ח\"ב ע' שעה: וכמ\"ש בתשו' הרשב\"א באלף רנ\"ה סוף תשו' צ\"ד שהמצות הם בזמן ומקום וכלים."],["650","14","<b>וזהו מ\"ש כימי השמים על הארץ</b>: ראה בארוכה אוה\"ת משפטים ע' א'קכב. סה\"מ תרל\"ב ח\"א ע' רכד."],["651","15","<b>ועוי\"ל שיש הפרש בין יצ\"מ ללע\"ל</b>: בהבא לקמן בפיסקא זו — ראה לעיל ד\"ה וככה (הא') פרק ח פיסקא: וא\"כ זהו מעין."],["652","16","<b>ההפרש בין קומה ה' למנוחתיך ובין קומה ה' ויפוצו אויביך</b>: ראה בארוכה ביאוה\"ז לאדהאמ\"צ קלב, א ואילך. ובהנסמן לעיל ד\"ה וככה (הא') פ\"ח שם."]]],[2000460238,"שזהו ענין חמשה כלי זיין<sup data-n=\"653\">17</sup> סייף קשת תריס אלה ורמח, וזהו מ\"ש ה' איש מלחמה. משא\"כ לע\"ל יהי' בחי' מנוחה שלא יהי' צריך למלחמה, וע\"ד שכתוב בשלמה והוא יהי' איש מנוחה, שדוד הי' איש הדמים איש מלחמה, ולכך לא נבנה בהמ\"ק על ידו כי בבהמ\"ק הוא ע\"ד לע\"ל שיהי' אז בחי' מנוחה, לכך לא נבנה הבהמ\"ק ע\"י דוד שהוא איש מלחמה, רק ע\"י שלמה שהוא איש מנוחה. ועד\"ז י\"ל ההפרש ג\"כ בין יצ\"מ ללע\"ל שעתה נא' ה' איש מלחמה, משא\"כ לע\"ל לא יהי' צריך למלחמה לפי שלע\"ל נא' אז אהפוך אל עמים שפה ברורה לקרוא כולם בשם ה' ולעבדו שכם אחד כו' וממילא יהיו בטלים כו'.",[["653","17","<b>וחמושים עלו בנ\"י. . חמשה כלי זיין</b>: ראה בכ\"ז אוה\"ת בשלח ע' שעד. סה\"מ תרל\"ב ח\"א ע' נב ואילך. וע' רכד ואילך."]]],[2000460239,"<h3>אז ישיר כו'</h3>\n<b></b><b>בס\"ד. (שביעי של פסח, ט\"ל).</b>\nעל ג\"ד העולם עומד כו' שירת המל'\nשש\"פ\n<b>אז</b> ישיר משה<sup data-n=\"654\">1</sup> ובנ\"י, ואיתא בילקוט כל פרקמטיא של משה היתה באז, באז חטא ובאז תיקן, קינטורו באז ומאז באתי אל פרעה כו' הרע לעם הזה כו', ושירתו באז אז ישיר משה. ומה שיש לדקדק בפסוק זה למה כתיב ישיר הול\"ל ישירו, גם מ\"ש ויאמרו לאמר כפל הלשון. הנה ענין קרי\"ס<sup data-n=\"655\">2</sup> הי' בכדי שידעו מצרים כי אני ה', וצ\"ל והלא כתי' לא נשאר בהם עד אחד<sup data-n=\"656\">3</sup> וכתיב ויכסו מים צריהם אחד מהם לא נותר (תילי' ק\"ו י\"א).",[["654","1","<b>אז ישיר משה</b>: מאמר זה מיוסד והגהות על ד\"ה וישרנה הפרות להצ\"צ בכת\"י 1029 סו, ב ואילך. [והוא הנחה בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש מחה\"פ תרט\"ז]. ובתוס' הגהות בד\"ה וישרנה בסה\"מ תרכ\"ו ע' סג ואילך. תר\"ל ע' קיח ואילך. וכאן הוא בתוס' עוד הגהות ובהשמטת ההתחלה וסיום.\nהמאמר נמצא בתוס' ביאור והוספות וכו' בד\"ה זה: בסה\"מ תרס\"ח ע' צ ואילך. עזר\"ת ס\"ע קנז ואילך. תר\"פ [מכ\"ק אדמו\"ר מהוריי\"צ] ע' יג ואילך. וע' טו ואילך. תש\"ז ע' 245 ואילך.\nמאמר הצ\"צ מיוסד על ד\"ה אז ישיר ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370279\" data-slug=\"torah-or\" data-id=\"3901370279\">תו\"א בשלח סב, ב</a> ואילך. ונו\"א [הנחות אדהאמ\"צ] בס' מאמרי אדה\"ז תקס\"ג ח\"א ע' קנג ואילך [בנוסחא הא']. ובתורת חיים שמות (כת\"י הר\"ש סופר) רכז, א ואילך. ונוסחא נוספת [הנחת הר\"מ בן אדה\"ז] בס' מאמרי אדה\"ז תקס\"ג שם ע' קנג ואילך [בנוסחא הב']. לחלק מהמאמר ראה ד\"ה אז ישיר ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470029\" data-slug=\"or-hatorah-hb\" data-id=\"8316470029\">אוה\"ת בשלח ע' תצג</a> ואילך.\nוראה עוד לקמן, מאמר זה בחלק ההנחות."],["655","2","<b>הנה ענין קרי\"ס</b>: בהבא לקמן בפיסקא זו ושלאחרי' — ראה ד\"ה אז ישיר ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370279\" data-slug=\"torah-or\" data-id=\"3901370279\">תו\"א בשלח שם סב, ב</a>."],["656","3","<b>קרי\"ס הי' בכדי שידעו מצרים כי אני ה' וצ\"ל הלא כתי' לא נשאר בהם עד אחד</b>: בהמאמר כאן לא נת' תירוץ קושיא זו. וראה ד\"ה אז ישיר בתו\"א בשלח שם שמתרץ: אלא הענין כי הנה יש מצרים בכל אדם ובכל זמן, ולכן אמרו בכל דור ודור חייב אדם לראות את עצמו כאילו הוא יצא ממצרים וכתי' למען תזכור את יום צאתך מאמ\"צ כל ימי חייך ואיתא בתוספתא שצריך לזכור ג\"כ קריעת ים סוף."]]],[2000460240,"<b>והענין</b> הוא דהנה ארז\"ל על שלשה דברים העולם עומד על התורה ועל העבודה ועל גמ\"ח דכתיב אם לא בריתי יומם ולילה חוקות שמים וארץ לא שמתי זהו ברית התורה, וכתיב לנטוע שמים וליסוד ארץ וקאי על עבודת הקרבנות וכמ\"ש סולם מוצב ארצה וראשו מגיע השמימה וארז\"ל סולם מוצב ארצה דא כבש המזבח וראשו מגיע השמימה שריחן עולה לשמים וזה עמוד העבודה, וכתיב חסד ה' מעולם ועד עולם זה עמוד הגמ\"ח.\n<b>ולהבין</b> ענין עמוד העבודה וגמ\"ח שעליהם העולם עומד, הנה ענין הקרבן ע\"י שהי' מקריבין בהמה ע\"ג המזבח הי' אש שלמעלה יורד ואוכל את הקרבן שז\"ע המשכה מלמעלמ\"ט, ובזהר איתא ארי' דאכיל קורבנין<sup data-n=\"657\">4</sup>, שהאש הי' בדמות ארי' כו'. ועכשיו תפלה כנגד תמידים תקנום, הנה ז\"ע הקרבת נה\"ב שתוכלל באש של מעלה בחי' אהבה רבה הבאה מלמעלה. ורמז דוגמת בחי' ירידת אש של מעלה שהי' בבהמק\"ד זהו ח\"י ברכות שבשמו\"ע ברוך אתה הוי', ופי' ברוך אתה הוא המשכה והיינו שהוא המשכה מעולם עד העולם כמו ברוך ה' אלקי ישראל שהוא ההמשכה מעלמא דאתכסיא לעלמא דאתגלי' כן פי' ברוך אתה ה' שבשמ\"ע הוא ג\"כ המשכה מעלמא דאתכסי' לעלמא דאתגלי' כו'.\n<b>וביאור</b> ענין עלמא דאתכסי' ועלמא דאתגלי'<sup data-n=\"658\">5</sup>, הנה ארז\"ל כל מה שיש ביבשה יש בים, רק שהברואים שבים מכוסים שהים מכסה עליהם משא\"כ ברואים שביבשה, ועוד שהברואים שבים המה מקבלים חיות מהים באופן שא\"א להם ליפרד מן הים כמשארז\"ל דגים מיד שפורשים מהים מתים, והברואים שביבשה אפי' בחי' צומח אנו רואים שהארץ תוציא צמחה ואח\"כ מפרידים התבואה מן הארץ ושוב אינה מקבלת חיות מן הארץ, וכ\"ש בחי' החי והמדבר כו' הגם שמקבלים חיותם ממה שגדל מן הארץ וכמ\"ש ארץ ממנה יצא לחם (איוב ך\"ח ה'), עכ\"ז ה\"ה חיים באויר ושטים ע\"פ המים כו'. משא\"כ הברואים שבים המה מובלעים תמיד בים וא\"א להם ליפרד כלל מן הים כו'. ובנפש האדם הוא בחי' מח' ודבור, דיבור הוא בחי' עלמא דאתגלי' שנפרד ונגלה לזולתו, אבל בחי' מח' הוא מכוסה כו'. והנה במשה כתיב מן המים משיתיהו והיינו ששרשו הי' מבחי' עלמא דאתכסי' רק שנשפל למטה בעלמא דאתגלי', ולכן אמר כבד פה וכבד לשון אנכי<sup data-n=\"659\">6</sup>, כי ענין הדיבור הוא בחי' עלמא דאתגלייא ושרשו הי' מבחי' עלמא דאתכסי', ולכן אמר כבד פה שמצד שרשו בעלמא דאתכסי' הוא כבד פה כו'. ולזאת זהו ענין מדרגת הכהן שעבודתו היא להמשיך",[["657","4","<b>ובזהר איתא ארי' דאכיל קורבנין</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380352\" data-slug=\"likkutei-torah\" data-id=\"4001380352\">לקו\"ת במדבר יא, א</a>."],["658","5","<b>וביאור ענין עלמא דאתכסיא ועלמא דאתגליא</b>: בהבא לקמן — ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370279\" data-slug=\"torah-or\" data-id=\"3901370279\">תו\"א בשלח שם סב, ב</a>-ג. וראה בארוכה ביאוה\"ז לאדהאמ\"צ מב, ג ואילך. מאמרי אדה\"ז פרשיות ח\"א ע' רנה ואילך. וע' רסז."],["659","6","<b>במשה כתי' מן המים משיתיהו. . ולכן אמר כבד פה וכבד לשון אנכי</b>: ראה בכ\"ז בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370232\" data-slug=\"torah-or\" data-id=\"3901370232\">תו\"א שמות נא, ד</a> ואילך. סידור עם דא\"ח קי, ג-ד. סה\"מ תרכ\"ז ע' ב."]]],[2000460241,"מבחי' עלמא דאתכסי' בעלמא דאתגלי'. וכ\"ה עכשיו בתפלה שאומרים ברוך אתה, ברוך הוא המשכה מן העולם ועד העולם מעלמא דאתכסי' בעלמא דאתגלי' כו', שגם בעלמא דאתגלי' יומשך הביטול כמו שהוא בעלמא דאתכסיא<sup data-n=\"660\">7</sup>, שזהו שרש ענין הברכות ועבודת הכהן כו'. ואמנם עבודת הלוים הוא מלמטלמ\"ע<sup data-n=\"661\">8</sup>, שעבודתם הו\"ע השיר שהוא בחי' העלאה מלמטה למעלה<sup data-n=\"662\">9</sup>, וכנודע מענין הניגון שהוא גורם התפעלות<sup data-n=\"663\">10</sup>, שכאשר יתבונן באיזה דבר בלא ניגון שאף שהתבוננות פועל איזה פעולה עכ\"ז אינה ניכרת כ\"כ, אבל כשמתבונן בהתבוננות זה גופא רק שמשורר איזה שיר וניגון הנה ע\"י הניגון תתעורר ההתפעלות, כי הניגון הוא תנועות וכל תנועה מוליד חום שהוא בחי' התפעלות לצאת מן הכלי כו'. וזהו משארז\"ל כל בעלי השיר יוצאי' בשיר ונמשכי' בשיר, וקאי על מלאכים<sup data-n=\"664\">11</sup> שכאשר יוצאים מגדר הכלי הוא ע\"י השיר דוקא, כי המלאכים יש להם ג\"כ גופים רק שהגופים שלהם הוא מאש ורוח<sup data-n=\"665\">12</sup> בלבד כמ\"ש עושה מלאכיו רוחות משרתיו אש לוהט, וכן אפי' נשמות בג\"ע כאשר יוצאים מהשגה זו להשיג השגה יותר עליונה הוא ג\"כ ע\"י השיר, כי השגה הוא ג\"כ בחי' גבול בחי' כלי, ולכן כאשר צריכים לצאת מהשגה זו להשיג השגה עליונה יותר הוא ג\"כ ע\"י השיר, וזהו כל בעלי השיר הם מלאכים ונשמות יוצאין בשיר כו'.\n<b>ומעתה</b> צ\"ל מ\"ש כאן בשירת הים<sup data-n=\"666\">13</sup> השירה הזאת, פי' זאת, הנה כתיב לזאת יקרא אשה כי מאיש לוקחה זאת, פי' איש זה הקב\"ה, ובחי' זאת הוא בחי' אשה בחי' מל'<sup data-n=\"667\">14</sup> מקור כנס\"י שמקבלים מבחי' איש זה הקב\"ה, וא\"כ צ\"ל מהו\"ע השירה הזאת דהיינו מה שבחי' המל' אומרת שירה כמ\"ש בזהר נהורא תתאה קארי תדיר לנהורא עילאה וכתיב אלקים אל דמי לך אל תחרש כו', איך שייך שבחי' מל' אומרת שירה, התינח המלאכים וכל צבא השמים שהם נבראים ויש להם גוף ונפש שייך ענין השיר לצאת מגדר הגבלתם, אבל איך יתכן שבחי' מדת המל' שהיא ספי' מעשר ספירות תאמר שירה<sup data-n=\"668\">15</sup> כו'.",[["660","7","<b>הכהן שעבודתו היא להמשיך מבחי' עלמא דאתכסיא</b>: ראה עד\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380314\" data-slug=\"likkutei-torah\" data-id=\"4001380314\">לקו\"ת במדבר א, ג</a>. דרושים לחה\"ס פ, א. יהל אור להצ\"צ ע' תסז. בהבא לקמן בענין הכהנים ולוים ראה גם אוה\"ת ויצא קפח, סע\"א ואילך. ביאוה\"ז שבהערה שלאח\"ז."],["661","8","<b>ואמנם עבודת הלוים הוא מלמטלמ\"ע</b>: בהבא לקמן בפיסקא זו — ראה ד\"ה אז ישיר ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370280\" data-slug=\"torah-or\" data-id=\"3901370280\">תו\"א בשלח שם סב, ג</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310055\" data-slug=\"tanya\" data-id=\"3401310055\">תניא פ\"נ (ע, ב</a>). ביאוה\"ז להצ\"צ ח\"ב ע' תרפט. אוה\"ת ויצא שם."],["662","9","<b>השיר שהוא בחי' העלאה מלמטה למעלה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370028\" data-slug=\"torah-or\" data-id=\"3901370028\">תו\"א בראשית ז, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670027\" data-slug=\"torat-chaim\" data-id=\"2300670027\">תו\"ח בראשית לג, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560237\" data-slug=\"or-hatorah-hb\" data-id=\"8316560237\">אוה\"ת בראשית (כרך ג) תקפה, א</a>. ובכ\"מ."],["663","10","<b>כנודע מענין הניגון שהוא גורם התפעלות</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370172\" data-slug=\"torah-or\" data-id=\"3901370172\">תו\"א</a> בשלח שם. מאמרי אדה\"ז תקס\"ג ח\"א שם ע' קס [בנוסחא הב']. וראה גם תו\"א מקץ לז, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380114\" data-slug=\"likkutei-torah\" data-id=\"4001380114\">לקו\"ת צו ט, סע\"ג</a>. ועוד."],["664","11","<b>וזהו משארז\"ל כל בעלי השיר. . וקאי על מלאכי'</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381119\" data-slug=\"likkutei-torah\" data-id=\"4001381119\">לקו\"ת ברכה צח, א</a>. סידור עם דא\"ח ערה, ד. מאמרי אדה\"ז על מארז\"ל ע' קכ. אוה\"ת בשלח שם ע' תצד. סה\"מ תרל\"ג ח\"א ע' רסט. וש\"נ."],["665","12","<b>המלאכי' יש להם ג\"כ גופי'. . מאש ורוח</b>: ראה לקו\"ת ברכה שם. וסה\"מ תרל\"ג ח\"א שם ע' רסט. וראה בהמובא ע\"ז ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091431\" data-slug=\"likkutei-sichot\" data-id=\"1300091431\">לקו\"ש ח\"ט ע' 405</a>. וש\"נ."],["666","13","<b>ומעתה צ\"ל מ\"ש כאן בשירת הים</b>: בהבא לקמן בפיסקא זו — ראה ד\"ה אז ישיר ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470029\" data-slug=\"or-hatorah-hb\" data-id=\"8316470029\">אוה\"ת בשלח שם ע' תצג</a> ואילך."],["667","14","<b>פי' זאת. . לזאת יקרא אשה. . בחי' מל'</b>: ראה בכ\"ז סה\"מ תרכ\"ט ע' נא-ב [ובהנסמן שם]."],["668","15","<b>איך יתכן שבחי' מדת המל'. . תאמר שירה</b>: בד\"ה זה תרס\"ח שם מעיר ע\"ז בהגה\"ה: ועמ\"ש מזה בהביאור דוישובו [מאמרי אדה\"ז תקס\"ג ח\"א ע' שיח. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830054\" data-slug=\"or-hatorah-hb\" data-id=\"8158830054\">אוה\"ת בשלח ע' תב</a> ואילך], וכאן מבואר באו\"א. ועד\"ז מעיר בד\"ה זה בסה\"מ עזר\"ת שם: ועמ\"ש בהביאור דוישובו שזהו כתירוץ הרמ\"ק. [ראה ביאור הרמ\"ק ע\"ז במאמרי אדה\"ז ואוה\"ת שם]. וראה גם אוה\"ת במדבר ע' נד."]]],[2000460242,"<b>אך</b> הענין הוא דהנה איתא בזהר איהו וחיוהי חד איהו וגרמוהי חד, פי' חיוהי קאי על האורות, וגרמוהי הוא בחי' הכלים<sup data-n=\"669\">16</sup>, דהנה מה שאנו קורים חכמה או חסד זהו קאי על כלי החכמה או כלי החסד אבל האור הוא שוה בכל הע\"ס<sup data-n=\"670\">17</sup>, ולפעמים נק' הכלים בשם גופים כמ\"ש בת\"ז וכד אנת תסתלק מנייהו אשתארו כולא שמהן כגופא בלא נשמתא<sup data-n=\"671\">18</sup>, שנמשלו הכלים לגופים, שכד אנת הוא האורות מסתלק אשתארו כגופא בלא נשמתא, פי' שהוא ע\"ד כמו בלילה בשעת שינה שהנשמה מסתלק מהגוף ולא נשאר בגוף כ\"א קיסטא דחיותא לבד, וכך הוא כאשר מסתלק האור המאיר בהכלים אשתארו בחי' הכלים כגופא בלא נשמתא, רק קיסטא דחיותא שהוא בחי' איהו וגרמוהי, שיש בחי' איהו המאיר בגרמוהי בלא בחי' חיוהי והיינו שהוא כדמיון הקיסטא דחיותא.\n<b>והנה</b> לפי הדמיון לקיסטא דחיותא שנשאר בזמן השינה שזהו מהארת הנפש המחי' את הגוף בהיותו ער בלתי ישן, א\"כ צ\"ל בנמשל שזהו ממה שנשתייר מהאור, שהגם בעת שאנת הוא האור מסתלק מהכלים עכ\"ז נשאר רשימה מן האור בכלים, כי דבר שבקדושה אינו נעקר ממקומו לגמרי<sup data-n=\"672\">19</sup> כמ\"ש והשמותי את מקדשיכם וארז\"ל במשנה ג' פ\"ג דמגילה לענין בית הכנסת שחרב, קדושתן אף כשהם שוממין, והיינו מטעם הנ\"ל להיות שבהכ\"נ הוא בחי' מקדש מעט כמ\"ש ואהי להם למקדש מעט, לכן גם בחורבנו יש בו קצת קדושה מפני שדבר שבקדושה אינו נעקר ממקומו לגמרי. ועד\"ז יובן שגם כשאנת הוא האורות מסתלקים מהכלים עכ\"ז נשאר רשימו מהאור בהכלים, וזהו בחי' איהו שמתייחד עם גרמוהי לברוא בהן וע\"י יש מאין (שזהו ממה שנשאר מהארת הקו דוקא כמ\"ש באגה\"ק סי' ך' ד\"ה איהו וחיוהי ע\"ש), וזהו בחי' הקיסטא דחיותא שנת' כאן. לכאו' הי' אפ\"ל<sup data-n=\"673\">20</sup> שמה שנשארי' כגופא זהו",[["669","16","<b>חיוהי קאי על האורות וגרמוהי. . הכלים</b>: ראה אגה\"ק רס\"כ (קכט, סע\"א). וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370011\" data-slug=\"torah-or\" data-id=\"3901370011\">תו\"א בראשית ג, ב</a>. לקו\"ת ראה כז, ריש ע\"ב. שה\"ש נ, ג-ד. סה\"מ תרל\"ג ח\"ב ע' שמו ואילך. וש\"נ."],["670","17","<b>חכ' או חסד. . קאי על כלי החכ'. . אבל האור הוא שוה בכל הע\"ס</b>: ראה בכ\"ז בארוכה בדרוש ג' שיטות באוה\"ת ענינים ע' רנט ואילך. וש\"נ. וע' רפה. וש\"נ."],["671","18","<b>וכד אנת תסתלק. . כגופא בלא נשמתא</b>: ראה בכ\"ז בארוכה סידור עם דא\"ח קסד, סע\"ב ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490145\" data-slug=\"or-hatorah-hb\" data-id=\"8316490145\">אוה\"ת וירא (כרך ד) תשמב, א</a> ואילך."],["672","19","<b>דבר שבקדושה אינו נעקר ממקומו לגמרי</b>: ראה אגה\"ק ביאור לס' ז\"ך (קמז, ב). אוה\"ת לך לך (כרך ב) תרעה, א. סה\"מ תרכ\"ט ע' פב. וש\"נ. תרל\"ג ח\"א ע' קל. תרל\"ד ע' לט. וע' קעה. מים רבים תרל\"ו פי\"ג (ע' יט). סה\"מ תר\"פ [לכ\"ק אדמו\"ר מהוריי\"צ] ע' י. לקו\"ש חל\"ב ע' 24. וש\"נ."],["673","20","<b>לכאו' הי' אפ\"ל. . שנשאר בשינה]</b>: הגה\"ה זו נרשמה בגוכתי\"ק בצידי הגליון לאחרי פיסקא: והנה לפי הדמיון, וכנראה שייך כאן. [הגה\"ה זו נרשמה בתחלה בגוכתי\"ק בתור ביאור שני (לפיסקא: והנה לפי הדמיון), וז\"ל: ”ועוי\"ל ששורש הכלים הוא מבחי' הרשימו שנשאר בחלל הצמצום שלפני המשכת הקו\". ואח\"כ העביר ע\"ז הקולמוס, וכתב: לכאו' הי' אפ\"ל. . (כבפנים)]. וראה ד\"ה זה תרס\"ח שם שמעיר ע\"ז: והנה במ\"א מבואר דמה שאשתארו כגופא הוא מצד חיות הכלי עצמה ששרשה מהרשימו, וכאן מבואר שהוא מהאור המתלבש, ובאמת בהכרח לומר שיש בה גם מהאור המתלבש ע\"כ. עיי\"ש בארוכה. וראה עד\"ז בד\"ה זה עזר\"ת שם."]]],[2000460243,"מפני ששרשם מהרשימו כמ\"ש בסדור בד\"ה וכד אנת תסתלק, אמנם א\"א לומר כאן כן שהרי גם בעת שמסתלק ג\"כ מחי' ומהוה בי\"ע שזהו ע\"י איהו דוקא הוא בחי' הארת הקו כמ\"ש באגה\"ק ד\"ה איהו וחיוהי ע\"ש א\"כ מוכרח לומר שגם בעת שמסתלק נשאר רשימו מהאור שהאיר מהקו שזהו כדוגמת קיסטא דחיותא שנשאר בשינה.\n<b>וזהו</b> ענין פי' שירה<sup data-n=\"674\">21</sup> שהמל' אומרת שירה, שזהו נהורא תתאה קארי תדיר לנהורא עילאה שהוא מה שכלי המל' אומרת שירה להכלל ולהבטל בבחי' איהו וחיוהי. וזה\"ע שירת הים שהוא בחי' שירה הזאת, שהוא למעלה מבחי' שיר הנבראי' בחי' שיר הלוים כו', דהנה הלוים אומרים שירה בחי' העלאה מעלמא דאתגלי' לעלמא דאתכסי', אבל בקרי\"ס שהים נעשה יבשה אמרו שירה עליונה יותר דהיינו בחי' שירה הזאת כו'. וכמ\"כ יש בעבודה ג\"כ בחי' שירה הזאת, כי שיר והתפעלות זהו דוגמת שיר הלוים, אכן יש בחי' רעו\"ד כמ\"ש אם ישים אליו לבו זהו כדוגמת בחי' שירה הזאת כו'. וזהו מ\"ש אתה הוא ה' לבדך, אתה זהו בחי' ומדרגת הכהן כמ\"ש אתה כהן לעולם, בחי' המשכה מלמעלמ\"ט<sup data-n=\"675\">22</sup> מבחי' עלמא דאתכסי' לעלמא דאתגלי', הוא זהו בחי' ומדרגת הלוי כמ\"ש ועבד הלוי הוא<sup data-n=\"676\">23</sup> בחי' העלאה מעלמא דאתגלי' בעלמא דאתכסי' כו'. אכן בהגלות נגלות בחי' לבדך שהוא עדמ\"ש ונשגב ה' לבדו ביום ההוא כו' אז אמרו שירת הים דהיינו בחי' שירה הזאת שלמעלה משיר הנבראים. ולכן בבחי' זו ישיר משה ובנ\"י יחד בשוה<sup data-n=\"677\">24</sup>, כי אף שמשה הוא מבחי' עלמא דאתכסי' ובנ\"י הוא מבחי' עלמא דאתגלי', אכן מצד בחי' היותר גבוה אף מבחי' עלמא דאתכסי' שלכן הפך ים ליבשה, מצד זה משה ובנ\"י כל אחד בשוה שבנ\"י היו במדריגת משה ולכן ישיר ל' יחיד כו'.\n<b>וזהו</b> אז ישיר משה ובנ\"י, א\"ז הוא בחי' אל\"ף זיי\"ן, זיי\"ן הוא בחי' ז' ימי בראשית, ואל\"ף הוא למעלה מבחי' ז'<sup data-n=\"678\">25</sup> ימי בראשית<sup data-n=\"679\">26</sup>, שבז' ימים אלו יש בחי' שבת, ואל\"ף",[["674","21","<b>וזהו ענין פי' שירה</b>: בהבא לקמן בפיסקא זו — ראה ד\"ה אז ישיר ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470029\" data-slug=\"or-hatorah-hb\" data-id=\"8316470029\">אוה\"ת בשלח שם ע' תצג</a> ואילך."],["675","22","<b>אתה זהו בחי' ומדרגת הכהן כמ\"ש אתה כהן לעולם. . מלמעלמ\"ט</b>: ראה סידור עם דא\"ח לט, ג. ובארוכה בפיה\"מ לאדהאמ\"צ ס, סע\"א-ב [ובהנסמן לעיל הערה ד\"ה: הכהן שעבודתו]."],["676","23","<b>הוא זהו בחי' ומדריגת הלוי כמ\"ש ועבד הלוי הוא</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380535\" data-slug=\"likkutei-torah\" data-id=\"4001380535\">לקו\"ת קרח נה, ב</a>-ג. ועוד."],["677","24","<b>ישיר משה ובנ\"י יחד בשוה. . שבנ\"י היו כמדרגת משה. . ישיר ל' יחיד</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470029\" data-slug=\"or-hatorah-hb\" data-id=\"8316470029\">אוה\"ת בשלח שם ע' תצג</a> ואילך. וע' תקח-ט. וראה לקו\"ש חל\"א ע' 69 ואילך."],["678","25","<b>אז הוא בחי' אל\"ף זיי\"ן. . ואל\"ף הוא למעלה מבחי' ז'</b>: ראה לקו\"ת דרושים לשמע\"צ פח, ב. סה\"מ תרכ\"ט ע' קנ. סה\"מ מלוקט ח\"ד ע' קט. וש\"נ."],["679","26","<b>זיי\"ן. . ז' ימי בראשית ואל\"ף הוא למעלה מבחי' ז' ימי בראשית</b>: בד\"ה וישרנה בסה\"מ תרכ\"ו שם: זיי\"ן. . ז' ימי בראשית שהוא בחי' אור ז' הימים ז' תחתונות דעתיק יומין, ואל\"ף הוא למעלה מבחי' ז' ימי בראשית היינו מבחי' ג' ראשונות."]]],[2000460244,"הוא למעלה מבחי' שבת וכמ\"ש אז תתענג על הוי' שלמעלה מבחי' ש' הוי', ובשבת כתיב שבת להוי', ולכן צ\"ל וקראת לשבת ענג שצריכין לקרות בשבת בחי' עונג, שבחי' עונג למעלה משבת, כי אף שכתיב שער הפנימי' כו' סגור יהי' ששת ימי המעשה וביום השבת יפתח שבחי' זו מתגלה בשבת, מ\"מ בחי' עונג הוא למעלה מבחי' שבת וצריכין לקרות בחי' עונג בשבת. וזהו אז כשנעשה גילוי בחי' אל\"ף בזיי\"ן כו' ישיר משה ובנ\"י בשוה בחי' שירה הזאת, שע\"י שירה הזאת יצאו מבחי' איהו וגרמוהי לבחי' איהו וחיוהי. ויאמרו לאמר, כפל הלשון ע\"ד משארז\"ל כל עסקא דשבתא כפול מזמור שיר, שבתא דמעלי שבתא ושבתא דיומא, שהוא בחי' עילוי אחר עילוי כו'. אשירה להוי', שהוא בחי' המשכה בשם הוי', סוס ורוכבו רמה בים היינו כי המכוון הוא שידעו מצרים כי אני הוי', כי הנה המצרים<sup data-n=\"680\">27</sup> הגביהו א\"ע לקבל חיות מבחי' גבוה מאד אשר שם כחשיכה כאורה, אך זהו רק מבחי' חיצוני', שזהו פרעה אותיות הערף כנודע שמבחי' אחוריים יכולים לקבל<sup data-n=\"681\">28</sup>, אבל בחי' פנימי' אינו מאיר אלא לנש\"י דוקא, כמ\"ש יאר ה' פניו אליך דוקא ולכן בקרי\"ס סוס ורוכבו רמה בים לשון השלכה בים כו'<sup data-n=\"682\">29</sup>, ע\"ד מ\"ש אם תגביהי כנשר משם אורידך נאום הוי', וזהו וידעו מצרים כי אני הוי'.\n<b>וזהו</b> על שלשה דברים העולם עומד, פי' כי עולם לשון העלם<sup data-n=\"683\">30</sup> בחי' שינויים, וכדי שיהי' בבחי' עמידה, דהיינו בבחי' קיום עדמ\"ש אני הוי' לא שניתי שזהו ממקום גבוה מאד, זהו ע\"י ג' קוין, בחי' כהנים בעבודתם בחי' קו הימין בחי' חסד ה' מעולם ועד עולם מעלמא דאתכסייא לעלמא דאתגלי' כו', ולוים בדוכנם בחי' שיר שהוא העלאה מעלמא דאתגלי' לעלמא דאתכסיא, ותורה היא בחי' קו האמצעי כו'.",[["680","27","<b>סוס ורוכבו רמה בים. . כי הנה המצרים</b>: בד\"ה וישרנה בסה\"מ תרכ\"ו שם: סוס ורוכבו רמה בים ואמרז\"ל במד\"ר זהו שר של מצרים כי המצרים. . [כבפנים]."],["681","28","<b>כנודע שמבחי' אחוריי' יכולי' לקבל. . אם תגביהי כנשר</b>: ראה הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370452\" data-slug=\"torah-or\" data-id=\"3901370452\">תו\"א ויחי קב, ב</a> ואילך. סה\"מ תרל\"ב ח\"א ע' נג ואילך. ובכ\"מ."],["682","29","<b>לשון השלכה בים כו'</b>: בד\"ה וישרנה בסה\"מ תרכ\"ו שם נוסף כאן עוד קטע: וזהו וידעו מצרים כי אני הוי', שבחי' אני הוא עצמותו ומהותו ית' ושם הוי' כולא חד, ולכן אם מגביהים את עצמם כנשר שדרך הנשר בשמים, מ\"מ משם אורידך נאום הוי'. ועפ\"ז יובן מה שתיקן משה באז ישיר, בהיות ידוע מארז\"ל ברבות ע\"פ ומאז באתי אל פרעה, שאמר משה נטלתי ספר בראשית ומדת הדין היתה, אלו הצאן מה חטאו, והוא לא ידע כי הם היו גלגול דור הפלגה כו', ולכן הי' התיקון שלהם בחומר ובלבנים כו', ולכן אמר אד' למה הרעות שסבר שנמשך הדין מבחי' שם אד', כנודע מענין א' דין, ולזה השיב לו הקב\"ה וידבר אלקים אני הוי', שבחי' שם אלקים ושם אד' ושם הוי' ובחי' אני שהוא בחי' עצמותו ומהותו כולא חד. ולכן כאן בעת קרי\"ס שהי' בכדי להודיע כי אני הוי' שכולא חד לכן תיקן החטא שלו שאמר ומאז באתי ואמר אז ישיר שהוא בחי' האל\"ף על הזיי\"ן כנ\"ל."],["683","30","<b>עולם לשון העלם</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380330\" data-slug=\"likkutei-torah\" data-id=\"4001380330\">לקו\"ת במדבר ה, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380463\" data-slug=\"likkutei-torah\" data-id=\"4001380463\">שלח לז, ד</a>. ובהנסמן ע\"ז בלקו\"ש חל\"ד ע' 112 הערה 63."]]],[2000460245,"<b>וז\"ע</b> ישראל במעמדם<sup data-n=\"e18\">*</sup>, וכמ\"ש ויקם עדות כו' ותורה שם בישראל, ופי' במעמדם שע\"י ג' קוין אלו נמשך קיום ועמידה לעולם מבחי' אני הוי' לא שניתי. ולהיות כי קרי\"ס הי' הכנה למ\"ת לכן גם בקרי\"ס הי' ג' קוין שהמים להם חומה מימינם ומשמאלם<sup data-n=\"684\">31</sup> וישראל הלכו באמצע זהו בחי' ג' קוין כו'.",[["684","31","<b>בקרי\"ס הי' ג' קוין שהמים להם חומה מימינם ומשמאלם</b>: ראה סד\"ה אז ישיר ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370281\" data-slug=\"torah-or\" data-id=\"3901370281\">תו\"א בשלח שם סב, ד</a>."],["e18","*","<b>וז\"ע ישראל במעמדם</b>: בשולי הגליון נרשם בגוכי\"ק: ישראל במעמדם שיומשך בחי' עמידה וקיום לעולם ע\"י בחי' ג' קוין מבחי' אני ה' לא שניתי כו'."]]],[2000460246,"<h3>והמשכילים יזהירו כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ תזו\"מ, ט\"ל).</b>\n<b></b>קמיפלגי במתיבתא דרקיע כו' הדן דין אמת לאמיתו\nתזו\"מ\n<b>והמשכילים</b> יזהירו<sup data-n=\"685\">1</sup> כזהר הרקיע כו' (בדניאל י\"ב), וארז\"ל בב\"ב ד\"ח ע\"ב במתניתא תנא זה הדן דין אמת לאמתו וגבאי צדקה, וצ\"ל מהו שייך הדן דין אמת וגבאי צדקה לזהר הרקיע.\n<b>ובכדי</b> להבין ענין זהר הרקיע יובן בהקדם ענין לשון מתיבתא דרקיע שארז\"ל בגמ' דב\"מ פ' הפועלים קא מפלגי במתיבתא דרקיע<sup data-n=\"686\">2</sup> אם בהרת קודמת לשער לבן טמא, ואם שער לבן קודם לבהרת טהור, ספק, הקב\"ה אמר טהור וכולהו מתיבתא דרקיע אמרי טמא, ואמרי מאן נוכח, נוכח רבה בר נחמני דאמר רבה בר נחמני אני יחיד בנגעים אני יחיד באהלות כו' עד אמר טהור טהור. ובגמ' במס' נזיר",[["685","1","<b>והמשכילים יזהירו</b>: מאמר זה (עד קרוב לסופו, פיסקא ד\"ה: והנה בענין הספק, מלבד ההתחלה) מיוסד והגהות על ד\"ה קא מיפלגי במתיבתא דרקיע ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380169\" data-slug=\"likkutei-torah\" data-id=\"4001380169\">לקו\"ת תזריע כב, סע\"ב</a> ואילך — פרקים א-ב. [בכ\"מ כאן הוא ע\"פ ל' הלקו\"ת שם בשינויים ובתוס' הגהות]. נו\"א ממאמר הלקו\"ת נמצא בס' מאמרי אדה\"ז הנחות הר\"פ ע' קנד. ובארוכה בס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תמג ואילך וע' תנו ואילך. ובשינויים בדרמ\"צ מצות טומאת המצורע פ\"ג (קב, ב ואילך). והערות וכו' על מאמר הלקו\"ת באוה\"ת ויקרא ס\"ע רנב ואילך. שם (כרך ב) ע' תקלא ואילך. שם (כרך ג) ע' תתטו ואילך. שם (כרך ד) ע' א'נב ואילך. ובארוכה בסה\"מ תרל\"ה ח\"א ע' רכ ואילך. ד\"ה זאת תהי' תורת המצורע בסה\"מ עזר\"ת ע' קעו ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121064\" data-slug=\"likkutei-sichot\" data-id=\"1300121064\">לקו\"ש חי\"ב ע' 64</a> ואילך.\nלהתחלת וסיום המאמר ראה ד\"ה והמשכילים יזהירו ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600698\" data-slug=\"or-hatorah-hb\" data-id=\"8316600698\">אוה\"ת נ\"ך (כרך א) ס\"ע תרחצ</a> ואילך.\nמאמר זה נמצא בגוכי\"ק כ\"ק אדמו\"ר מהר\"ש בכת\"י 1077 רעח, א ואילך [כת\"י זה כולל הנחות בגוכי\"ק אדמו\"ר מהר\"ש ממאמרי אדמו\"ר הצ\"צ]. שם נרשמו בהמשך לזה עוד הגהות על מאמר הלקו\"ת ונדפסו לקמן בהוספות.\nוראה לקמן מאמר זה בהנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע, ובהנחת השומעים. ובהוספות נמצא ביאור והבנת המאמר מהרד\"צ ע\"ה חן."],["686","2","<b>ובכדי להבין ענין זהר הרקיע. . קא מפלגי במתיבתא דרקיע</b>: בהבא לקמן בפיסקא זו ושלאחרי' ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380169\" data-slug=\"likkutei-torah\" data-id=\"4001380169\">לקו\"ת תזריע שם כב, סע\"ב</a>-ג."]]],[2000460247,"דס\"ה ע\"ב פי' הטעם דאמר קרא לטהרו או לטמאו הואיל ופתח בו הכתוב בטהרה תחלה (והובא בהר\"ש ספ\"ד דנגעים). וצריך להבין ענין התנאים ואמוראים שאנו רואים את המופתים העצומים שהיו יכולים לעשות<sup data-n=\"687\">3</sup> כמו ברפב\"י פ\"ק דחולין שאמר גינאי נהרא חלוק לי מימיך ומיד נתקיים, מה שבהתאסף יחד משה רבינו וששים רבוא ישראל גבי קרי\"ס הי' זה פלא, וכן אמרו זוטרא דבכו מחיה מתים שלא מצינו כן כ\"א באלי' ואלישע ויחזקאל, וזכו לכ\"ז ע\"י עסק תורתם.\n<b>ובכדי</b> להבין ענין קוב\"ה אמר טהור צ\"ל תחלה פי' קריאת שם הקב\"ה<sup data-n=\"688\">4</sup> שקראו בו חז\"ל את הבורא ית'. והענין הוא דהנה קדוש פי' מובדל שמובדל ומרומם, שלא כמו הנשמה שמחי' את הגוף שמתלבשת בתוך הגוף ולכן היא מתפעלת ממקרי הגוף<sup data-n=\"689\">5</sup> שפעם כך ופעם כך, אבל הוא ית' מובדל ומרומם, שזהו בחי' סוכ\"ע שאינו מתלבש כו', ולכן אני ה' לא שניתי שאין בו שום שינוי בין קודם הבריאה לאחר הבריאה, והגם כי עיקר החיות הוא מבחי' סוכ\"ע כנודע עכ\"ז הנה מחי' בבחי' מקיף ואינו מתלבש ולכן הוא קדוש שקדוש ומובדל מבחי' העולמות כו'. וע\"פ הקבלה ג' בחי' נק' קדוש, דעת, ת\"ת, יסוד<sup data-n=\"690\">6</sup>, להיותם מקו האמצעי דת\"י (שעולה עד הכתר), אמנם בג' בחי' אלו יש מלמטלמ\"ע ומלמעלמ\"ט, כי פי' דעת הוא התקשרות<sup data-n=\"691\">7</sup>, והיינו לקשר דעתו ומחשבתו בחוזק איך שהוא ית' קדוש ומובדל, ולכן אני ה' לא שניתי ואתה הוא קודם שנבה\"ע ואתה הוא לאחר שנבה\"ע, שהוא בחי' דעת והתקשרות לבחי' קדוש, וכמ\"ש דע את אלקי כו' שפי' דע הוא התקשרות שידע ויתקשר לבחי' קדוש בחי' סוכ\"ע שלמעלה מבחי' ממכ\"ע, וזהו בחי' קדוש מלמטלמ\"ע. ויש ב' בחי' קדוש מלמעלמ\"ט, וז\"ע תפארת ויסוד שהם בחי' המשכות והשפעות מלמעלמ\"ט, וזהו פי' קדוש.\n<b>וכמו\"כ</b> בפי' ברוך יש בו ג\"כ ב' פירושים<sup data-n=\"692\">8</sup>, הא' ברוך הוא כמו רחום וחנון, שאין הפי' רחום שמקבל רחמים כ\"א שמשפיע בחי' רחמים וכן חנון, ועד\"ז הוא פי' ברוך שהוא מקור הברכה שהיא ראשית בחי' ממכ\"ע שמברך ומשפיע לכל הבחי' שלמטה כו', וזהו ברוך ר\"ת ראש ומקור כל ברכה<sup data-n=\"693\">9</sup>. והפי' הב' בתיבת ברוך הוא",[["687","3","<b>התנאים ואמוראים שאנו רואים המופתים העצומים שהיו יכולים לעשות</b>: נת' ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770115\" data-slug=\"or-hatorah-hb\" data-id=\"8316770115\">אוה\"ת שה\"ש (כרך ב) ע' תפא</a>. סה\"מ מלוקט ח\"ד ע' רנג. ח\"ו ע' מו-ז. [ובהדרושים שנסמנו לעיל בתחלת המאמר]."],["688","4","<b>פי' קריאת שם הקב\"ה</b>: בהבא לקמן ראה [נוסף להדרושים שנסמנו בתחילת המאמר] <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381214\" data-slug=\"likkutei-torah\" data-id=\"4001381214\">לקו\"ת שה\"ש כא, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381290\" data-slug=\"likkutei-torah\" data-id=\"4001381290\">מ, ג</a>. סה\"מ תרל\"ד ס\"ע צז ואילך. ועוד."],["689","5","<b>הנשמה. . מתפעלת ממקרי הגוף</b>: ראה גם לעיל ד\"ה ששים המה מלכות. וש\"נ."],["690","6","<b><a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380219\" data-slug=\"likkutei-torah\" data-id=\"4001380219\">וע\"פ הקבלה ג</a>' בחי' נק' קדוש דעת ת\"ת יסוד</b>: בהבא לקמן עד סוף הפיסקא ראה אוה\"ת ויקרא (כרך ד) ע' א'נג-ד. וראה גם לקו\"ת אמור לג, סע\"ב ואילך."],["691","7","<b>פי' דעת הוא התקשרות</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא ספ\"ג (ז, ב</a>). ובכ\"מ."],["692","8","<b>וכמו\"כ בפי' ברוך יש בו ג\"כ ב' פירושי'</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380170\" data-slug=\"likkutei-torah\" data-id=\"4001380170\">לקו\"ת תזריע שם כב, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381244\" data-slug=\"likkutei-torah\" data-id=\"4001381244\">לקו\"ת שה\"ש כח, ד</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380716\" data-slug=\"likkutei-torah\" data-id=\"4001380716\">לקו\"ת דברים א, ג</a>."],["693","9","<b>ברוך ר\"ת ראש ומקור כל ברכה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380170\" data-slug=\"likkutei-torah\" data-id=\"4001380170\">לקו\"ת תזריע כב, ג</a> שם בשם הפרדס ערך ברוך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370238\" data-slug=\"torah-or\" data-id=\"3901370238\">תו\"א שמות נג, ב</a>."]]],[2000460248,"כמ\"ש והמלך שלמה ברוך שפירושו שמתברך<sup data-n=\"694\">10</sup> והיינו שמקבל הברכה וצ\"ל תחלה פי' מלך שלמה שארז\"ל מלך שהשלום שלו פי' שלום שמחבר שני הפכים כנודע, ועד\"ז יובן למעלה שבחי' המל' מחבר אלקות עם הנבראים דאין מלך בלא עם שצריך להיות עם נפרדים דוקא, ולאלקות צ\"ל בחי' ביטול דוקא כנודע, ובחי' המל' מחבר שיומשך אלקותו ית' בעולמות הנבראים ונפרדים כו', וזהו מלך שהשלום שלו שמחבר ב' הפכים כו' (וצ\"ל שזהו ע\"י ביטול היש כו' דאל\"כ אין אני והוא יכולים לדור), והיינו בחי' ממכ\"ע שמתלבש להחיות כו', וזהו פי' והמלך שלמה ברוך שהוא מתברך ומקבל הברכה מאוא\"ס, והיינו בחי' חכמה תתאה בחי' חכמת שלמה, ושרש ומקור הברכה נמשך מבחי' ח\"ע שהיא ראש ומקור כל ברכה (כי בח\"ע שורה אוא\"ס ב\"ה כמ\"ש בסש\"ב פל\"ה, בהג\"ה) וכ\"ז הוא בחי' ממכ\"ע. ונמצא כי יש ג' בחי', הא' הוא בחי' קדוש שקדוש ומובדל לגמרי, הב' בחי' ברוך מקור הברכה, הג' בחי' ברוך שמקבל הברכה כו', ומפני כי אור המקיף ואור הפנימי דבקים זה בזה שמאיר הארת המקיף בהפנימי לכן קראו חז\"ל בשם הקב\"ה שני הבחי' ביחד.\n<b>ומעתה</b> יובן ענין המתיבתא דרקיע<sup data-n=\"695\">11</sup>, כי הנה כתיב ודמות על ראשי החיה רקיע כעין הקרח כו', ויש חיוון תתאין וחיוון עילאין, חיוון תתאין הם המרכבה דבי\"ע מחנה מיכאל מחנה גבריאל, והרקיע שעל ראשיהם זהו מבחי' מל' דאצי', וחיוון עילאין הם האבות אברהם יצחק ויעקב חג\"ת דאצי', והרקיע שעל ראשם הוא מ\"ש ודמות על ראשי החיה<sup data-n=\"696\">12</sup> רקיע. והנה צ\"ל מ\"ש ראשי החיה דלכאורה הל\"ל ראשי החיות, אך הענין הוא דהנה חי' קאי על בחי' מל' שמתלבשת ויורדת להחיות עולמות ע\"ש ואתה מחי' את כולם, והאבות חג\"ת הם ראשי החיה, כי כדי שיהי' בחי' זו דואתה מחי' את כולם זהו ע\"י בחי' אברהם יצחק יעקב, יצחק הוא בחי' גבורות בחי' צמצומים כו', ואברהם בחי' חסד, ויעקב קו האמצעי ולכן הם ראש ומקור החי' הוא בחי' ואתה מחי' את כולם כו', ועל ראשי החיה אלו יש בחי' רקיע. וענין הרקיע דהנה יש בחי' אור מים רקיע<sup data-n=\"697\">13</sup>, ויובן זה מנפש האדם שיש בו בחי' משכיל שהוא מקור השכל, ויש בחי' גילוי השכל, ויש בחי' השגה והבנה, דהיינו כשבא השכל להשגה והבנה באורך ורוחב אז הוא כמשל הרקיע שאגלידו מיא שא\"א לנטותו, כך השכל כשבא לידי השגה והבנה א\"א לנטותו ולשנות את טעמו, משא\"כ כשעדיין לא בא השכל לידי השגה והבנה גמורה דהיינו כשהשכל עדיין בבחי' ברק המבריק אז הוא כמשל המים דניידי, ואור הוא בחי' מקור השכל כו'. ועד\"ז יובן למעלה שיש ג' בחי'",[["694","10","<b>והמלך שלמה ברוך שפירושו שמתברך</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381244\" data-slug=\"likkutei-torah\" data-id=\"4001381244\">לקו\"ת שה\"ש שם כח, ד</a>. ביאוה\"ז לאדהאמ\"צ קכ, א."],["695","11","<b>ומעתה יובן ענין המתיבתא דרקיע</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380171\" data-slug=\"likkutei-torah\" data-id=\"4001380171\">לקו\"ת תזריע שם כב, ד</a>. וראה אוה\"ת ויקרא שם ע' רנב-ג."],["696","12","<b>והרקיע שעל ראשם הוא מ\"ש ודמות על ראשי החיה</b>: בלקו\"ת תזריע שם: והרקיע שעל ראשם הוא בחי' בינה, [וראה לקמן בהמאמר]."],["697","13","<b>דהנה יש בחי' אור מים רקיע</b>: ראה בארוכה סידור עם דא\"ח ע, א ואילך. סה\"מ תרל\"ה ח\"ב ע' תנא ואילך. תרל\"ח ע' קסא ואילך. תשי\"ט ע' 560 ואילך."]]],[2000460249,"אור מים רקיע, והרקיע הוא כמשל השכל כשבא לידי השגה והבנה כנ\"ל. וז\"ע להבין דבר מתוך דבר, פי' תוך דבר הוא בחי' ממכ\"ע, ודבר הוא בחי' סוכ\"ע<sup data-n=\"698\">14</sup>, וצריך להבין דבר מתוך דבר שמבחי' תוך דבר היינו בחי' ממכ\"ע יבין בחי' דבר סוכ\"ע כו', וז\"ע הרקיע. ובחי' מתיבתא דרקיע היינו מה שנמשך מבחי' רקיע<sup data-n=\"699\">15</sup> זה שעל ראשי החיה, וזהו בחי' גבוה מאד שהרקיע הוא בחי' בינה, ובבינה הוא התגלות אוא\"ס ב\"ה כנודע<sup data-n=\"700\">16</sup>.\n<b>והנה</b> הזוכים לישב במתיבתא דרקיע<sup data-n=\"701\">17</sup> זו שהיא בחי' גבוה מאד וקוב\"ה אתי לאשתעשע עמהן, הם התנאים ואמוראים והיינו ע\"י עסק התורה לשמה, ורב יהודה הי' מצלי מתלתין יומין כו', כי הנה התפלה היא הקדמה והכנה לעסק התורה<sup data-n=\"702\">18</sup>, כי שרש ענין התפלה הוא להתבונן איך שלגדולתו אין חקר, וכל השתלשלות העולמות מריש כל דרגין עד סוף כל דרגין מקור התהוותם הוא רק מהארה אחת שאינה בערך כלל אפי' כמו טפה לגבי ים<sup data-n=\"703\">19</sup> אוקיינוס, כי טפה לגבי הים ארז\"ל יכולני לשער כמה טיפות יש בים, אבל הארה זו אינה בערך כלל, ולית מח' תפיסא בי' כלל, ומהתבוננות זו יומשך הדאגה והמרירות וכמשארז\"ל אין מוסרין רזי תורה אלא למי שלבו דואג בקרבו, שענין הדאגה והמרירות הוא שא\"א להשיג גילוי עצמותו<sup data-n=\"704\">20</sup>, ככל מה שאפשר להשיג אפי' בעולמות העליונים אינה אפי' כערך טפה מים כו', כי לית מח' תפיסא בי' כלל. וז\"ע ההתבוננות בתפלה שאו מרום עיניכם וראו מי ברא אלה, אל\"ה הוא בחי' ו\"ק<sup data-n=\"705\">21</sup> שהם ראשי החיה כנ\"ל, ובחי' מי ברא אל\"ה ע\"ד מ\"ש והחכ' מאין תמצא שאפי' בחי' החכ' תמצא מאין ע\"ד בריאה יש מאין, ועד\"ז יובן עכ\"פ בבחי' מי ברא אלה שבחי' אלה הוא ו\"ק שהוא ראשי החי' בחי' ואתה מחי' את כולם נברא מבחי' מי. והנה מבטן מי יצא הקרח שבחי' רקיע שהוא כעין הקרח נמשך מבטן מי, ולכן ע\"י ההתבוננו' בתפלה איך שמי ברא אלה ממשיכים בבחי' מתיבתא דרקיע כו'.",[["698","14","<b>וז\"ע להבין דבר מתוך דבר. . תוך דבר. . ממכ\"ע ודבר. . סוכ\"ע</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370002\" data-slug=\"torah-or\" data-id=\"3901370002\">תו\"א בראשית א, א</a>. לקו\"ת ואתחנן ו, ג."],["699","15","<b>ובחי' מתיבתא דרקיע היינו מה שנמשך מבחי' רקיע</b>: ראה בארוכה אוה\"ת ויקרא ע' תג."],["700","16","<b>ובבינה הוא התגלות אוא\"ס ב\"ה כנודע</b>: בלקו\"ת תזריע שם נוסף כאן: רקיע נק' בחי' בינה שהוא הרקיע שע\"ג חיוון עילאין כנ\"ל, והתפשטותה והארתה להאיר בג\"ע העליון נק' מתיבתא דרקיע, ודוקא מבחי' בינה שהוא בחי' רקיע דהיינו כשנמשך האור בגדר השגה מזה יוכל להיות נמשך הג\"ע שיהיו נהנין מזיו השכינה בבחי' השגה ממש."],["701","17","<b>והנה הזוכים לישב במתיבתא דרקיע</b>: בהבא לקמן בפיסקא זו ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380175\" data-slug=\"likkutei-torah\" data-id=\"4001380175\">לקו\"ת תזריע שם כג, סע\"ד</a> ואילך."],["702","18","<b>התפלה היא הקדמה והכנה לעסק התורה</b>: בלקו\"ת תזריע שם: שהתפלה היא כמו עד\"מ הקדמה והכנה לעסק התורה."],["703","19","<b>שאינה בערך כלל אפי' כמו טפה לגבי ים</b>: בלקו\"ת תזריע שם: שהיא רק עד\"מ כטפה נגד הים ויותר מזה אין ערוך כו'."],["704","20","<b>שענין הדאגה והמרירות הוא שא\"א להשיג גילוי עצמותו</b>: בלקו\"ת תזריע שם: דבודאי אין ר\"ל עצבות ח\"ו, שהעצבות הרחיקו מאד חכמי האמת, אלא ר\"ל מה שידאוג לבו ויתמרמר ממה שא\"א להשיג גילוי עצמיות אלקותו ית'."],["705","21","<b>אל\"ה הוא בחי' ו\"ק</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380058\" data-slug=\"likkutei-torah\" data-id=\"4001380058\">לקו\"ת פקודי ד, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380335\" data-slug=\"likkutei-torah\" data-id=\"4001380335\">במדבר ו, ד</a>. ובכ\"מ."]]],[2000460250,"<b>ואח\"כ</b> ע\"י התורה<sup data-n=\"706\">22</sup> ממשיכים להיות משמחי לב כי פקודי הוי' ישרים משמחי לב<sup data-n=\"707\">23</sup>, שבתחלה ע\"י התפלה הוא בחי' הדאגה כנ\"ל, אכן ע\"י עסק התורה שהנפש היא תפיסא בה אזי עי\"ז היא תפיסא ומתלבשת בהקב\"ה<sup data-n=\"708\">24</sup> ממש דאורייתא וקוב\"ה כולא חד ולכן משמחת את הלב. ופי' ענין פקודי ה' ישרים, דהנה בהשתלשלו' הוא בחי' מיעוט אחר מיעוט, שכל מה שנמשך למטה יותר מתמעט במיעוט אחר מיעוט, וכנודע מענין יחידות עשירות מאות<sup data-n=\"709\">25</sup>, שבבריאה הוא בחי' מאות, וביצי' מתמעט על עשירות, ובעשי' רק יחידות, אבל פקודי הוי' ישרים שנמשך האור ישר למטה כמו למעלה. וזהו עוד פי' בהקב\"ה שהקדוש בעצמו יתברך וימשך כו', וזהו פי' הקב\"ה שהקדוש יתברך כו', ולכן אומרים בנוסח הברכה אשר קדשנו במצותיו וציונו על דברי תורה, וכן בכל המצות, שממשיכים שהקדוש בעצמו יתברך ויומשך.\n<b>והנה</b> עיקר ענין מצות לימוד התורה הוא בדבור, ולכן מצינו שזה למד מאה פעמים וזה למד מאה פעמים וא'. כי הנה מבואר בס\"י שעשר ספירות בלי מה כשלהבת קשורה בגחלת, ועד\"מ השלהבת כשהיא בתוך הגחלת היא בבחי' העלם (ועמ\"ש סד\"ה כי ביום הזה יכפר<sup data-n=\"710\">26</sup> בענין בחי' צור עליון, צור חיינו שהוא מקור ההויות כו') וכדי להמשיך השלהבת מהעלם אל הגילוי הוא ע\"י רוח הנופח בכח, וכך עד\"מ ע\"י הבל פה של המדבר ד\"ת שהוא בחי' לרוח ממללא עי\"ז ממשיך אור התורה ממקורה מההעלם אל הגילוי (ועיין באגה\"ק סד\"ה ויעש דוד שם<sup data-n=\"711\">27</sup> גבי ובאורייתא מתקיים עלמא כו' כי בדבורם ממשיכים כו'), וזהו שמברכים נותן התורה לשון הוה, כי רוח שרשו גבוה מאד כמ\"ש עד יערה עלינו רוח ממרום וכמ\"ש בס\"י עשר ספירות כו' כשלהבת קשורה בגחלת כו' אחת רוח אלקים חיים כו', שע\"י הרוח נמשך אח\"כ גם בחי' אש שהוא גילוי בחי' השלהבת כו' ע\"ש, ועמ\"ש סד\"ה ביום השמע\"צ<sup data-n=\"712\">28</sup> גבי ואשים דברי בפיך כו' מוצא פי' ה', ועמ\"ש סד\"ה ענין ק\"ש<sup data-n=\"713\">29</sup> בפי' קורא בתורה. אך רוח זה הכל לפי מה שהוא אדם, והתנאים ואמוראים<sup data-n=\"e19\">*</sup> שהיו מבחי' מוחין דגדלות הי' בכחם להמשיך בדבורם בחי'",[["706","22","<b>ואח\"כ ע\"י התורה</b>: בהבא לקמן בפיסקא זו ושלאחרי', ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380172\" data-slug=\"likkutei-torah\" data-id=\"4001380172\">לקו\"ת תזריע שם כג, א</a>."],["707","23","<b>ע\"י התורה. . פקודי הוי' ישרים משמחי לב</b>: ראה בארוכה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380633\" data-slug=\"likkutei-torah\" data-id=\"4001380633\">לקו\"ת פנחס עח, ב</a>."],["708","24","<b>ע\"י עסק התורה. . היא תפיסא ומתלבשת בהקב\"ה</b>: ראה תניא פ\"ד ופ\"ה [הובא בלקו\"ת תזריע שם]."],["709","25","<b>וכנודע מענין יחידות עשירות מאות</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380615\" data-slug=\"likkutei-torah\" data-id=\"4001380615\">לקו\"ת בלק עד, ב</a>."],["710","26","<b>ועמ\"ש סד\"ה כי ביום הזה יכפר</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380190\" data-slug=\"likkutei-torah\" data-id=\"4001380190\">לקו\"ת אחרי כו, ג</a>."],["711","27","<b>באגה\"ק סד\"ה ויעש דוד שם</b>: אגה\"ק ס\"ה (קט, רע\"א)."],["712","28","<b>ועמ\"ש סד\"ה ביום השמע\"צ</b>: לקו\"ת דרושים לשמע\"צ פד, ב."],["713","29","<b>ועמ\"ש סד\"ה ענין ק\"ש</b>: לקו\"ת ואתחנן יב, סע\"ג."],["e19","*","<b>והתנאי' ואמוראי'. . היו יכולים לעשות נסים ומופתים גדולים</b>: בהעתקה הב' של המאמר נרשם בגוכי\"ק בשולי הגליון: והרבותא דקריעת ים סוף, צריך לומר שזה מפני שהי' קודם מתן תורה."]]],[2000460251,"גילוי אור התורה והשלהבת כו' שהוא בחי' ש' הוי' כמ\"ש כי הוי' אלקיך אש אוכלה הוא, וע\"כ היו יכולים לעשות נסים ומופתים גדולים, וזהו דאמר רפב\"י גינאי חלוק לי מימיך<sup data-n=\"714\">30</sup>, והיינו כי ים ויבשה הוא עלמא דאתכסי' ועלמא דאתגלי'<sup data-n=\"715\">31</sup> והיינו ההעלם והגילוי שבסדר ההשתל', אבל גילוי אוא\"ס שנמשך ע\"י התורה הוא מלמעלה מסדר ההשתל' וקמי' שוין ההעלם והגילוי שבהשתלשלו' העולמות כו', שהוא בחי' למקצה השמים ועד קצה כו', וכמ\"ש בזהר פ' תרומה דקל\"ז סע\"א קצה השמים דא עלמא עילאה והוא בחי' עלמא דאתכסי' כו', משא\"כ אור א\"ס ב\"ה אין שייך בו בחי' קצה ח\"ו שאינו בבחי' גבול ח\"ו, ולכן ע\"י המשכת האור שע\"י התורה פעל שהנהר חלק לו מימיו כו' כענין הפך ים ליבשה שעלמא דאתכסי' ועלמא דאתגלי' שוין נגד המשכה זו שמלמעלה מסדר ההשתל' וכמ\"ש במ\"א ע\"פ כי טובים דודיך מיין<sup data-n=\"716\">32</sup> כו'.\n<b>והנה</b> בענין הספק מתיבתא דרקיע אמרי טמא, כי כל ספיקא דאורייתא לחומרא, אבל קוב\"ה אומר טהור שהוא מבחי' אור המקיף בחי' סוכ\"ע, מאן נוכח רבה בר נחמני, כי רבה בר נחמני הי' מן המשכילים, שפי' והמשכילים יזהירו שהם משכילים בעסק התורה והתפלה, ועי\"ז ממשיכים מבחי' אור הסובב ומקיף ולכן ידע שספיקו טהור. וביאור הענין דהנה כתיב משכיל לאיתן האזרחי, פי' איתן הוא ל' חוזק<sup data-n=\"717\">33</sup> והיינו בחי' הביטול שלמעלה מן הטעם ודעת, ובחי' זו נמשך מבחי' משכיל שהוא מקור השכל היינו בחי' אור בנמשל שלמעלה מבחי' מים ורקיע כנ\"ל, וזהו פי' זהר הרקיע שהוא בחי' האור המאיר בהרקיע שהוא למעלה מן הרקיע וממשיכים בחי' זו ע\"י שמשכילים בתורה ותפלה כנ\"ל. וגם זהו משארז\"ל והמשכילים יזהירו אלו גבאי צדקה, שבצדקה נאמר ג\"כ וצדקה כנחל איתן, שע\"י צדקה ממשיכים ג\"כ בחי' איתן<sup data-n=\"718\">34</sup> שהוא נמשך מן בחי' המשכיל כו'. ועיקר פי' הפשוט והמשכילים יזהירו כזהר הרקיע הוא כנ\"ל שמשכילים בעסק התורה והתפלה להיות משכיל על דבר, ובלימוד התורה הוא שילמוד בעיון רב ובעמקות כו', ולכן רבה בר נחמני שהי' מן המשכילים המשיך גם על נפשו מאור המקיף<sup data-n=\"719\">35</sup> לכן ידע שספיקו טהור.",[["714","30","<b>וזהו דאמר רפב\"י גינאי חלוק לי מימיך</b>: ראה סה\"מ מלוקט ח\"ד ע' רנג. [ראה שם ע' רנד הע' 31]. ח\"ו ע' מח."],["715","31","<b>ים ויבשה הוא עלמא דאתכסיא ועלמא דאתגליא</b>: ראה בכ\"ז לעיל ד\"ה אז ישיר. וש\"נ."],["716","32","<b>וכמ\"ש במ\"א ע\"פ כי טובים דודיך מיין</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381138\" data-slug=\"likkutei-torah\" data-id=\"4001381138\">לקו\"ת שה\"ש ב, ב</a>."],["717","33","<b>דהנה כתי' משכיל לאיתן האזרחי. . ל' חוזק</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380788\" data-slug=\"likkutei-torah\" data-id=\"4001380788\">לקו\"ת ראה יח, א</a>. סה\"מ תרל\"ג ח\"ב ע' תמד. [ובהנסמן שם בתחילת המאמר]."],["718","34","<b>וצדקה כנחל איתן שע\"י צדקה ממשיכים. . איתן</b>: ראה תניא קו\"א קסא, סע\"א-ב. סה\"מ תרל\"ג ח\"ב ע' תמח. ובכ\"מ."],["719","35","<b>ולכן רבה בר נחמני. . המשיך. . מאור המקיף</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380177\" data-slug=\"likkutei-torah\" data-id=\"4001380177\">לקו\"ת תזריע שם כד, סע\"ב</a> ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940120\" data-slug=\"or-hatorah-hb\" data-id=\"8159940120\">אוה\"ת ויקרא (כרך ב) ע' תקלו</a>. דרמ\"צ קסז, ב."]]],[2000460252,"<b>ומעתה</b> יובן ג\"כ משארז\"ל במתניתא תנא זה הדן דין אמת לאמתו, כי הנה ארז\"ל כל דיין הדן דין אמת לאמתו כאלו נעשה שותף להקב\"ה במע\"ב. והענין הוא דהנה בריאת העולם הוא בבי\"ת, ועשרים וששה דורות קרא האל\"ף תגר עד מ\"ת שהוא באל\"ף, ונתבאר הטעם ע\"ז<sup data-n=\"720\">36</sup> מה שלא הי' ברה\"ע באל\"ף, כי אל\"ף הוא ר\"ת ארור, משא\"כ בי\"ת ברכה, והיינו כי לעוצם רוממות בחי' האל\"ף יכול להיות נמשך גם בבחי' ארור כי כחשיכה כאורה כו'. ולכאורה צ\"ל איך הי' מ\"ת באל\"ף. אך הענין הוא דכשנבה\"ע בבי\"ת שהוא בחי' ברכה בחי' חכמה יכול להיות אח\"כ מ\"ת באל\"ף ואעפ\"כ לא יומשך לסט\"א כ\"א לסטרא דקדושה כנודע, וכמ\"ש בד\"ה מצה זו בלק\"ת<sup data-n=\"721\">37</sup> בענין בעבור זה שיש מצה כו', כי אף שנמשך מבחי' גבוה מאד אשר שם כחשיכה כאורה, מ\"מ בעבור זה היינו בחי' מצה בחי' ביטול בחי' חכמה נמשך לי ולא לו, ועד\"ז הוא בענין הקב\"ה. וזהו עוד פי' בהקב\"ה שבחי' קדוש יומשך בבחי' ברוך דוקא, כי מצד בחי' קדוש יכול להיות נמשך גם לסט\"א, אבל כשנמשך בבחי' ברוך היינו בחי' חכמה כנ\"ל לא יומשך כ\"א לסטרא דקדושה, וממשיכים בחי' זו ע\"י הדן דין אמת לאמתו שלא יהי' דין מרומה כמ\"ש התוס', והיינו אף שהעדים והטענות מוכיחים כדברי הא' מהבעלי דין, עכ\"ז יבין הדיין בחכמתו, וזהו משכיל כו', ולכן ממשיכים עי\"ז בחי' קדוש בברוך כו'. וענין הדין למעלה כי הנה בר\"ה ויבאו בני האלקים, שבני האלקים<sup data-n=\"722\">38</sup> אומרים שישראל חטאו ג\"כ, והנה הוא טענה חזקה, ועכ\"ז מבין הדיין שעם ישראל הצדק כו'. ונמצא מובן שע\"י שדן דין אמת לאמיתו נעשה שותף שממשיך האל\"ף בבי\"ת, ע\"י היותו משכיל. ולכן המשכילים שדן דין אמת לאמיתו יזהירו כזוהר הרקיע היינו בחי' אור שלמעלה מבחי' מים ורקיע שמאיר בבחי' רקיע ע\"י שדן כו' שהוא משכיל על דבר כו'.",[["720","36","<b>בריאת העולם הוא בבי\"ת. . מ\"ת שהוא באל\"ף ונתבאר הטעם ע\"ז</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרסו ואילך. מאמרי אדהאמ\"צ קונטרסים ע' ריב ואילך. ביאוה\"ז להצ\"צ ח\"א ע' תקעא וע' תקעט. ח\"ב ע' תשיח ואילך. וע' תשכא. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200143\" data-slug=\"or-hatorah-hb\" data-id=\"8159200143\">אוה\"ת</a> בשלח (כרך ז) ע' ב'תרנד. ויקרא (כרך ג) ע' תתנז. תורת שמואל דרושי חתונה ע' יח. וע' כ ואילך."],["721","37","<b>וכמ\"ש בד\"ה מצה זו בלק\"ת</b>: פ' צו יב, ג."],["722","38","<b>שבני האלקים</b>: בבוך גוכי\"ק תרל\"ט נרשם: ”שע' שרים\". וממעל להשורה נרשם בגוכי\"ק: שבני האלקים. [וכנראה היא תיקון מחמת הצענזור]."]]],[2000460253,"<h3>הללו כו' במרומים כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ אחו\"ק, ט\"ל).</b>\nוירם קרן\nאחו\"ק\n<b>הללוי'</b> הללו את ה' מן השמים<sup data-n=\"723\">1</sup> הללוהו במרומים כו'. הנה מזמור זה הוא מעיקר פסוד\"ז, וכמ\"ש רש\"י בשבת דקי\"ח ע\"ב שפסוד\"ז הם שני מזמורים של הילולים הללו את ה' מן השמים, ומזמור הללו אל בקדשו. ואפ\"ל שזהו מפני שבזהר פ' פקודי דרל\"א ע\"א אמרו ששני מזמורים אלו הם כלליות כל התשבחות ע\"ש, שבמזמור הללו אל בקדשו נחשב כל הע\"ס, ובמזמור הללו כו' מן השמים נחשב כל הבחי' שיש בשמים ובארץ. והנה בסידור האריז\"ל פי' הללויה הללו את הוי' מן השמים אצי', הללוהו במרומים בריאה, מלאכיו יצירה, צבאיו עשי'. הללוהו שמש וירח בחי' התכללות עשי' ביצי', כוכבי אור התכללות יצי' בבריאה, שמי השמים בריאה באצי', והמים אשר מעל השמים אצי' בעצמיות המאציל כו'. ואח\"כ קחשיב הללו את ה' מן הארץ תנינים כו' אש יסוד האש, ברד שלג וקיטור יסוד המים, כי קיטור העשן עיקרו מיסוד המים, ולכן אנו רואים כשהעצים הם לחים יוצא עשן הרבה יותר, רוח סערה עושה דברו יסוד הרוח, ההרים וכל גבעות בחי' דומם, עץ פרי כו' בחי' צומח, החי' וכל בהמה בחי' חי הבלתי מדבר, מלכי ארץ כו' בחי' מדבר, ומסיים הודו על ארץ ושמים וירם קרן לעמו כו' לבנ\"י עם קרובו, וקאי על ש' הוי' שהזכיר תחלה יהללו את ש' הוי', דאלו לגבי בחי' ש' אלקים כתיב אשר לו אלקים קרובים אליו כמ\"ש במד\"ר פ' ואתחנן פ\"ב אשר לו גוי קרוב אין כתיב כאן ע\"ש, אך לגבי בחי' שם הוי' נק' ישראל עם קרובו, כמ\"ש בלק\"ת פ' שלח בד\"ה בפ' נסכים ססי' ב' בהג\"ה<sup data-n=\"724\">2</sup>.",[["723","1","<b>הללוי' הללו את ה' מן השמים</b>: מאמר זה מיוסד והגהות על ד\"ה אדם כי יקריב להצ\"צ משנת תרח\"י. נמצא בגוכי\"ק כ\"ק אדמו\"ר מהר\"ש בכת\"י 1077 קי, א ואילך. וכאן הוא בהשמטת ההתחלה וסיום (ע\"פ אדם כי יקריב) ובתוס' הגהות וכו'. מעל ההגהות נרשם בגוכי\"ק: הגהות לס' מזמור לתודה.\nמאמר זה נמצא עם הגהות אחרות בד\"ה זה בסה\"מ תרכ\"ז ע' קסט ואילך. ובשינוי ההתחלה וסיום בד\"ה א\"ר יוסי יהא חלקי בסה\"מ תרכ\"ט ע' ל ואילך. וחלקו נמצא בשינויים והוספות בד\"ה א\"ר יוסי יהא חלקי בסה\"מ תש\"א ע' 10 ואילך. מאמר זה עם חלק מההגהות מתרכ\"ז (שנרשמו בגוכי\"ק אדמו\"ר מהר\"ש) נדפס באוה\"ת נ\"ך (כרך ג) ע' א'שלא ואילך.\nמאמר הצ\"צ הנ\"ל מיוסד על ד\"ה הללוי' לאדה\"ז בסידור עם דא\"ח סה, ב ואילך. ונו\"א בס' מאמרי אדה\"ז על מארז\"ל ותפלה ע' תח ואילך. וראה גם ד\"ה זה באוה\"ת נ\"ך (כרך ב) ע' א'ו ואילך. יהל אור לתהלים ע' תקסב ואילך. וראה עוד על פסוק זה בס' מאמרי אדה\"ז הקצרים ע' רמט ואילך וע' רנב. כתובים ח\"א ע' קפב ואילך.\nראה גם לקמן מאמר זה בהנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע.\nואפ\"ל שזהו מפני שבזהר פ' פקודי דרל\"א ע\"א אמרו ששני מזמורי' אלו הם כללות כל התשבחות: הובא ונת' ביהל אור לתהלים שם. בד\"ה זה תרכ\"ז נוסף כאן הגה\"ה אחרת בגוכי\"ק: וכן משמע בזח\"ב פקודי דרל\"ב א' ת\"ח תושבחתא דא אמר דוד לקבל רזא דשמא קדישא דאיהו כללא דתושבחתא דכולא ואינון דא (היינו הללו את ה' מן השמים), ותושבחתא בתראה דכתי' הללו אל בקדשו, אבל דא הוה על עשר מינים (פי' המק\"מ הם ע\"ס הנרמזי' בהללו אל בקדשו), ודא הוה על שבעה מינים (פי' המק\"מ ז\"ק הנרמזי' בהללו את ה' מן השמים)."],["724","2","<b>כמ\"ש בלק\"ת פ' שלח בד\"ה בפ' נסכים ססי' ב' בהג\"ה</b>: דף מ, ד. וז\"ל שם: אשר לו אלקים קרובים אליו כו' שהם עיקר לגבי שם אלקים לפי שנמשכים משם הוי' שלמעלה משם אלקים."]]],[2000460254,"<b>ולהבין</b> כ\"ז, הנה פסוד\"ז הוא הקדמה לבוא לבחי' ק\"ש, וכמ\"ש בלק\"ת פ' ואתחנן בד\"ה ענין ק\"ש<sup data-n=\"725\">3</sup> אחד ואהבת פ\"ב ופ\"ג שענין פסוד\"ז וברכת ק\"ש ז\"ע המאריך באחד, ולבוא לבחי' ואהבת, ואמת שהתנאים והאמוראים לא היו מאריכים כ\"כ בתפלה ובפרט בפסוד\"ז, זהו מפני שהיו גבוהים מאד במעלה כמו רשב\"י שאמר בחד קטירא אתקטרנא כו' בי' אחידא כו', שהי' נתפס אחד אמת בלבם בהתבוננות מועטת, והיתה תקועה בלבבם בל תמוט עולם ועד, משא\"כ אנחנו מגושמים ורחוקים מרוחניות הרי אנו צריכים להאריך באריכות כל ההתבוננות דפסוד\"ז וברכת ק\"ש עד שיותפס בשכלינו ולבינו, שנוכל לבוא לבחי' אחד ואהבת כו' שאומרים בק\"ש שמע ישראל ה' אלקינו ה' אחד כו' ואהבת כו', וכתיב שמע ישראל דוקא לפי שישראל עם קרובו.\n<b>והנה</b> בענין ה' אחד צ\"ל מפני מה לא נאמר יחיד<sup data-n=\"726\">4</sup> שמורה יותר על אחדות, כי אחד יש שהוא אחד המנוי שיש שני ושלישי, כמו בששת ימי בראשית שהם ששה ומ\"מ יום הראשון נאמר בתורה עליו יום אחד, וכן שבטי ישראל הם י\"ב וכתיב שלחו מכם אחד, אחיכם אחד (בפ' מקץ פמ\"ב ט\"ז י\"ט), מה שאין שייך ח\"ו וח\"ו לומר כן באלקות, שהוא אחד ואין שני לו, אבל לשון יחיד מורה על אחדות יותר, ובאמת בברוך שאמר אנו אומרים יחיד חי העולמים מלך, ובישתבח אנו אומרים מלך יחיד חי העולמים, ומפני מה בק\"ש אומרים אחד, אלא עכצ\"ל שיש רבותא טפי במה שאומרים אחד דוקא.\n<b>והנה</b> מצות לייחדו יוצא מפסוק שמע כו' ה' אחד<sup data-n=\"727\">5</sup> כמ\"ש הרמב\"ם בהל' יסוה\"ת. והענין הוא דהנה יחיד מורה על אוא\"ס שלמעלה מבחי' סוכ\"ע וממכ\"ע אשר אני ה' לא שניתי ואתה הוא קודם שנברא ואתה הוא לאחר שנברא, משא\"כ אחד מורה על בחי' המהוה ז' רקיעים וארץ וד' רוחות, כי חי\"ת שבתיבת אחד מורה על ז' רקיעים וארץ, ולמעלה הוא בחי' ז' מדות לך הוי' הגדולה, וד' רומז לד' רוחות העולם, והאל\"ף הוא בחי' המהוה ומחי' הז' רקיעים והארץ והד' רוחות, והיינו שאע\"פ שנתהוו ז\"ר וארץ וד' רוחות אעפ\"כ הם בטלים לאוא\"ס ב\"ה. ולכן אומרים אחד דוקא, שזהו רבותא טפי, שמתיבת יחיד אינו מובן זה כלל, כ\"א דוקא מתיבת אחד הוא מצות לייחדו, שהגם שנבראו שמים וארץ וכל אשר בהם ה\"ה בטלים בתכלית לגבי בחי' אוא\"ס המחי' ומהוה אותם בכל עת ובכל רגע, ונמצא כי הוא ית' הוא אחד האמת, שאחד זה פירושו הוא כמו יחיד ממש. ולכן מפסוק זה דאחד יוצא",[["725","3","<b>בלק\"ת פ' ואתחנן בד\"ה ענין ק\"ש</b>: דף יב, ב-ג [והבא לקמן (מהתיבות: ואמת שהתנאים, עד: בשכלינו ולבינו) הוא ע\"פ ל' הלקו\"ת שם]. וראה גם לקמן ד\"ה עבדו את ה' בשמחה."],["726","4","<b>ה' אחד. . לא נא' יחיד</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370248\" data-slug=\"torah-or\" data-id=\"3901370248\">תו\"א וארא נה, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380174\" data-slug=\"likkutei-torah\" data-id=\"4001380174\">לקו\"ת תזריע כג, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380598\" data-slug=\"likkutei-torah\" data-id=\"4001380598\">בלק ע, א</a>. אמ\"ב שער הק\"ש פ\"ח. דרמ\"צ קכד, א-ב. סה\"מ תרכ\"ו ע' קצג-ד. תרכ\"ז ע' רכג-ד. תרכ\"ט ע' קנו ואילך. ועוד."],["727","5","<b>והנה מצות לייחדו יוצא מפסוק שמע כו' ה' אחד</b>: ראה סה\"מ תרכ\"ו ע' טז. נג. וס\"ע קסב ואילך. תרכ\"ט ע' קנו ואילך."]]],[2000460255,"מצות לייחדו שהוא ל' יחיד כו', והיינו מפני כי מתיבת אחד מובן איך שהוא יחיד ומיוחד והכל בטלים אליו בתכלית כו'<sup data-n=\"728\">6</sup>.\n<b>והנה</b> הז' רקיעים למעלה הוא בחי' ז' מדות כי כדי שיומשך השפע למטה צ\"ל ע\"י מדות דוקא, כי אוא\"ס ב\"ה הוא לאו מכל אלין מדות כלל, שגם החכמה כעשי' גשמיות נחשבת לפניו ית' וכ\"ש בחי' המדות, וזהו בחי' יחיד שהוא למעלה מבחי' סוכ\"ע וממכ\"ע, אכן כדי שיומשך השפע למטה צ\"ל ע\"י בחי' מדות דוקא. והנה כתיב ביום ההוא יהי' הוי' אחד ושמו אחד וארז\"ל בפסחים ספ\"ג דף נו\"ן סע\"א, על ושמו אחד, אטו האידנא לאו אחד הוא, ותירצו לא כמו שאני נכתב אני נקרא כו'.\n<b>והענין</b> הוא דהנה אנו מבקשים הבט משמים וראה וכתיב השקיפה ממעון קדשך מן השמים וברך את עמך ישראל, וצ\"ל מהו הבקשה מן השמים דוקא. אך הענין הוא דהנה שמים הוא בחי' אש ומים, אש הוא בחי' גבורה בחי' העלאה מלמטלמ\"ע, ומים יורדים מגבוה לנמוך שהוא בחי' חסד<sup data-n=\"729\">7</sup> שמלמעלמ\"ט, ומדת הת\"ת מחבר חו\"ג כנודע<sup data-n=\"730\">8</sup>, וזהו בחי' שמים שהוא כללות המדות ז\"א דאצי', ולכן בתיבת שמים יש תיבת מים בשלימות, אבל מתיבת אש אין בו רק אות השי\"ן בלבד<sup data-n=\"731\">9</sup>, והיינו מפני כי ז\"א רובו חסדים כו' וכמ\"ש זכר חסדו. וזהו הבקשה הבט משמים והשקיפה כו' מן השמים דוקא כי כשנמשך במדות אז ואוהב את יעקב כו'<sup data-n=\"732\">10</sup>, כי מצד המדות הנה אהבה היא פנימיות החסד<sup data-n=\"733\">11</sup> והשנאה היא בחי' הגבורה<sup data-n=\"734\">12</sup>, ולכן כשנמשך במדות אזי ואוהב את יעקב, אבל בזמן חורבן בהמ\"ק הנה אמרו בזהר קוב\"ה בגלותא סליק לעילא לעילא דהיינו לבחי' יחיד שלאו מכל אינון מדות כלל שגם החכמה כעשי' גשמיות נחשבת לפניו וכ\"ש בחי' המדות אשר שם כחשיכה כאורה ואם צדקת מה",[["728","6","<b>מתיבת אחד מובן איך שהוא יחיד. . בתכלית כו'</b>: בד\"ה זה תרכ\"ז נוסף כאן הגה\"ה: ועל בחי' יחיד זה נאמר יש אחד ואין שני לו (קהלת ד' ח'), פי' הגם כי אחד יש גם אחד המנוי כמו יום אחד, אבל יש אחד שאין שני לו כלל."],["729","7","<b>ומים יורדי' מגבוה לנמוך. . חסד</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד (ח, ב</a>)."],["730","8","<b>ומדת הת\"ת מחבר חו\"ג כנודע</b>: ראה בארוכה לקמן ד\"ה מזמור לתודה. ובהנסמן שם."],["731","9","<b>מתיבת אש אין בו רק אות השי\"ן בלבד</b>: בד\"ה זה תרכ\"ז נוסף כאן הגה\"ה: (ואות אל\"ף מתיבת אש י\"ל שיוצא מניקוד הקמץ שתחת השי\"ן שמוציא אל\"ף כנודע מספרי הדקדוק). וראה בהנסמן ע\"ז בסה\"מ תרכ\"ז שם ע' קעא."],["732","10","<b>אז ואוהב את יעקב כו'</b>: בד\"ה אדם כי יקריב להצ\"צ הנ\"ל נרשם כאן בגוכי\"ק אדמו\"ר מהר\"ש: ”אז ואוהב את יעקב ואת עשו שנאתי\". אך בהגהות כ\"ק אדמו\"ר מהר\"ש למאמר זה בס' תרל\"ט הורה להשמיט את התיבות ”ואת עשו שנאתי\" [וכנראה הוא מחמת הצענזור]."],["733","11","<b>אהבה היא פנימיות החסד</b>: ראה בארוכה מאמרי אדה\"ז תקס\"ה ח\"א ע' תיד ואילך. דרמ\"צ יב, ב ואילך. ד\"ה זכור גו' עמלק בסה\"מ תרל\"א. וש\"נ."],["734","12","<b>והשנאה היא בחי' הגבורה</b>: בד\"ה אר\"י יהא חלקי בסה\"מ תש\"א שם: והשנאה היא פנימיות הגבורה."]]],[2000460256,"תתן לו, לכן מצד זה נמשך הגלות, שמצד בחי' זו יכול להיות נמשך השפע לעוברי רצונו<sup data-n=\"735\">13</sup> כו'<sup data-n=\"736\">14</sup>, ולכן הבקשה הבט משמים דוקא. וזהו ענין הללו את ה' מן השמים, ששמים הוא בחי' מדות והללו מן השמים הוא בחי' ביטול המדות לאוא\"ס ב\"ה שלאו מכל אינון מדות<sup data-n=\"737\">15</sup>.\n<b>וזהו</b> לך ה' הגדולה<sup data-n=\"738\">16</sup> כו' כי כל בשמים ובארץ, הנה לך וכל הוא בחי' א', רק שלך הוא בחי' העלאה מלמטלמ\"ע וכל הוא בחי' המשכה מלמעלמ\"ט. והנה לך הוא גימ' נו\"ן שהוא בחי' חמשים שערי בינה שנבראו בעולם (ר\"ה דף ך\"א סע\"ב), ופי' שערי בינה<sup data-n=\"739\">17</sup> כי כדי שיתהוו המדות מן השכל זהו ע\"י שערים, שהוא בחי' ההטי' במוח אל המדה, שעיקר המדה הוא בלב, אמנם בעת שמתבונן בשכלו שכך טוב לפניו נעשה הטי' בשכלו כן, וזהו בחי' השער שע\"י השער הזה נעשית המדה אח\"כ בלב, ומספר מ\"ט שע\"ב הוא כי ז' מדות וכ\"א כלול מז' הם מ\"ט, ושער הנו\"ן הוא עצם הבינה. וזהו לך ה' הגדולה שהעלאת המדות הוא ג\"כ ע\"י השערים, כי השער משמש כניסה ויציאה, וכשם שהתהוות המדה הוא ע\"י השער כמו\"כ עליית המדה הוא ג\"כ ע\"י השער, וזהו לך ה' הגדולה שהוא בחי' ביטול המדות לבחי' אוא\"ס שלאו מכל אינון מדות, שאע\"פ שמדת הגדולה הוא בחי' גבוה שע\"י הוא הנהגת העולמות<sup data-n=\"740\">18</sup>, אעפ\"כ היא בטילה לך ועלייתם הוא ע\"י נש\"ב.\n<b>וזהו</b> כגוונא דאינון מתייחדין<sup data-n=\"741\">19</sup> לעילא באחד, פי' דאינון קאי על המדות שמתייחדים לעילא, דהיינו בחי' ביטול ועלייתם לעילא דהיינו בבחי' בינה ע\"י הנש\"ב. וזהו ג\"כ מאמר השבטים ליעקב כשם שאין בלבך<sup data-n=\"742\">20</sup> אלא אחד, כי יעקב ויצחק גימ' שמים<sup data-n=\"743\">21</sup>, והיינו מפני יעקב הוא בחי' מדת הת\"ת שמחבר בחי' יצחק ואברהם שהוא בחי' שמים, כנ\"ל שהשמים הוא בחי' מדות, ופי' בלבך אלא אחד שהוא בחי' ביטול",[["735","13","<b>אבל בזמן חורבן בהמ\"ק. . לעוברי רצונו</b>: בד\"ה אדם כי יקריב להצ\"צ הנ\"ל נרשם כאן בגוכי\"ק: ”אבל בגלותא. . לאומות העולם\". אך בהגהות כ\"ק אדמו\"ר מהר\"ש על המאמר בס' תרל\"ט תיקן כבפנים. [וכנראה הוא שינוי מחמת הצענזור]."],["736","14","<b>שמצד בחי' זו יכול להיות נמשך השפע לעוברי רצונו כו'</b>: בד\"ה זה תרכ\"ז נוסף כאן הגה\"ה מד\"ה כי עמך מקור חיים ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370160\" data-slug=\"torah-or\" data-id=\"3901370160\">תו\"א מקץ לד, ד</a>. עיי\"ש."],["737","15","<b>והללו מן השמים הוא בחי' ביטול המדות לאוא\"ס ב\"ה שלאו מכל אינון מדות</b>: בד\"ה זה תרכ\"ז נוסף כאן בסוף הפיסקא: וע\"י העלאה זו נמשך אח\"כ בחי' המשכות אוא\"ס ב\"ה."],["738","16","<b>וזהו לך ה' הגדולה</b>: ראה בכ\"ז סה\"מ תר\"ל ע' קסט ואילך. תרל\"ד ע' רל ואילך. המשך מים רבים תרל\"ו פמ\"ו ואילך. ועוד."],["739","17","<b>ופי' שערי בינה</b>: בהבא לקמן ראה בארוכה לקמן ד\"ה מזמור לתודה. [ובהנסמן שם]."],["740","18","<b>שמדת הגדולה הוא בחי' גבוה שע\"י הוא הנהגת העולמות</b>: בד\"ה זה תרכ\"ז נוסף כאן הגה\"ה: כמארז\"ל הגדולה זו מעשה בראשית והגבורה זו קרי\"ס והתפארת זו מ\"ת."],["741","19","<b>וזהו כגוונא דאינון מתייחדי'</b>: בהבא לקמן בפיסקא זו ראה בארוכה סידור עם דא\"ח קסח, א ואילך."],["742","20","<b>וזהו ג\"כ מאמר השבטים כשם שאין בלבך</b>: בהבא לקמן ראה גם תו\"א תצוה פד, סע\"ד. פז, ג. ובארוכה סידור עם דא\"ח שם קסח, א-ב. שערי תשובה לאדהאמ\"צ ח\"ב יט, רע\"א ואילך. סה\"מ תרכ\"ז ע' שפד-ה, וע' תקג-ד. סה\"מ מלוקט ח\"ד ע' קמא ואילך."],["743","21","<b>כי יעקב ויצחק גימ' שמים</b>: בד\"ה זה תרכ\"ז נוסף כאן הגה\"ה: כמ\"ש בפנ\"י [בס' פנים יפות] פ' הברכה ע\"פ רוכב שמים בעזרך."]]],[2000460257,"השמים בחי' מדות לאוא\"ס ב\"ה שלאו מכל אינון מדות, שזהו בחי' אחד כנ\"ל שהז' רקיעים כו' בטלים לבחי' אל\"ף, ולמעלה הוא בחי' ביטול הז' מדות לאוא\"ס שלאו מכל מדות שז\"ע שמתייחדים לעילא כו', ועי\"ז נעשה כי כל בשמים ובארץ שנמשך בחי' כל שהוא בחי' הכלליות בשמים ובארץ, ופי' כל הוא ע\"ד מ\"ש אמרו אליו כל תשא עון שנת' במ\"א בשם הה\"מ נ\"ע שהוא בחי' מקיף הכללי<sup data-n=\"744\">22</sup>, ועד\"ז יש לומר כאן שהגם דסליק לעילא ולעילא בבחי' יחיד שלמעלה מסוכ\"ע היינו מקיף הפרטי, מ\"מ ע\"י ביטול המדות לך ה' הגדולה כו' לאוא\"ס שלאו מכל אינון מדות שהוא בחי' יחיד כו', יומשך בחי' הכלליות מבחי' יחיד בשמים ובארץ שכולל אבי\"ע וד' יסודות ארמ\"ע וד' בחי' דצח\"ם, כנ\"ל בפי' סידור האריז\"ל. וזהו שע\"י בחי' הללו כו' מן השמים נמשך שיהי' הללוהו במרומים ובמלאכיו וצבאיו שהוא בחי' בי\"ע<sup data-n=\"745\">23</sup> כמ\"ש לעיל. וע\"ד שאמרו השבטים ליעקב כשם שאין בלבך אלא אחד כך אין בלבינו אלא אחד, ופי' מה שאין בלבינו בחי' מרכבתא תתאה י\"ב בקר דבריאה אלא אחד נמשך מבחי' מה שאין בלבך אלא אחד כו'.\n<b>וזהו</b> ע\"ד מי עלה שמים וירד, ופי' בזהר<sup data-n=\"746\">24</sup> ששמים עולה לבחי' מי, וא\"כ בחי' מי הוא למעלה מבחי' שמים, והיינו כמ\"ש מי יתן והי' לבבם זה להם ליראה אותי כל הימים, וארז\"ל הכל בידי שמים חוץ מיר\"ש שאינו בידי שמים, ולכאורה הלא דוד המלך ע\"ה ביקש יחד לבבי ליראה את שמך וכמו\"כ אנו מבקשים ויחד לבבינו ליראה<sup data-n=\"747\">25</sup>. אך הענין דבחי' יראת שמים אינו בידי שמים כ\"א הוא תלוי בבחי' מי שלמעלה מבחי' שמים, שבחי' מי הוא בחי' שאינו מושג כלל וכמ\"ש שאו מרום עיניכם וראו מי ברא אלה, אל\"ה הוא ו\"ק ו' פעמים ו' גימ' אל\"ה, אבל מי הוא בחי' שאינו מושג כלל, וזהו מי יתן מציון ישועת ישראל כו', מי יתן טהור מטמא, ובבחי' מי זה תלוי ענין יראת שמים, כי אם הי' תלוי ענין יר\"ש בבחי' שמים לא הי' הבחירה חפשית שהי' הידיעה מכריח את הבחירה, אבל כשתלוי בבחי' מי אין הידיעה מכריח את הבחירה<sup data-n=\"748\">26</sup> כו'. ולפי פי' הזהר מי עלה שמים ששמים עולים לבחי' מי, היינו כמו לך ה' הגדולה ביטול המדות לבחי' אור א\"ס שלאו מכל אינון מדות כו', ועי\"ז נעשה",[["744","22","<b>אמרו אליו כל תשא עון שנת' במ\"א בשם הה\"מ נ\"ע שהוא בחי' מקיף הכללי</b>: ראה סה\"מ תרכ\"ט ע' קכו. וראה גם שם ע' קיג. המשך תער\"ב ח\"א ע' קמט. סה\"מ תרצ\"ו ע' 129. סה\"מ מלוקט ח\"א ע' קע. ח\"ג ע' כא."],["745","23","<b>שע\"י בחי' הללו. . נמשך שיהי' הללוהו במרומים ובמלאכיו וצבאיו שהוא בחי' בי\"ע</b>: בד\"ה זה תרכ\"ז נוסף כאן הגה\"ה: וזהו אוף הכי איהי אתייחדת לתתא ברזא דאחד, רק שזהו רק רזא דאחד, ולא כמו דאינון מתייחדין לעילא כמ\"ש בסידור ע\"ז [סידור עם דא\"ח שם]."],["746","24","<b>וזהו ע\"ד מי עלה שמים וירד ופי' בזהר</b>: בהבא לקמן בפיסקא זו ראה בארוכה ביאוה\"ז לאדהאמ\"צ נה, ד ואילך. ולהצ\"צ ח\"ב ע' תתלד ואילך."],["747","25","<b>וארז\"ל הכל בידי שמים חוץ מיר\"ש. . ולכאו' הלא. . אנו מבקשי' ויחד לבבינו ליראה</b>: בהבא לקמן ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380368\" data-slug=\"likkutei-torah\" data-id=\"4001380368\">לקו\"ת במדבר טו, א</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316520329\" data-slug=\"or-hatorah-hb\" data-id=\"8316520329\">אוה\"ת בשלח ע' תרעג</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450561\" data-slug=\"or-hatorah-hb\" data-id=\"8316450561\">ואתחנן ע' קצה</a>-<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650105\" data-slug=\"or-hatorah-hb\" data-id=\"8316650105\">ו. עקב ע' תקסא</a>. דרושים לשבת שובה ע' א'תצב. ביאוה\"ז להצ\"צ ח\"א ע' מו. ח\"ב שם ע' תתלד. יהל אור לתהלים ס\"ע לה-ו. סה\"מ תרל\"ה ח\"א ע' רכו."],["748","26","<b>אין הידיעה מכריח את הבחירה</b>: בד\"ה זה תרכ\"ז נוסף כאן הגה\"ה מד\"ה ארדה נא ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370067\" data-slug=\"torah-or\" data-id=\"3901370067\">תו\"א וירא טו, א</a>. עיי\"ש."]]],[2000460258,"אח\"כ וירד שזהו ע\"ד כי כל בשמים ובארץ. וזהו מ\"ש היושבי בשמים שלכאורה אות יו\"ד שבתיבת היושבי מיותר<sup data-n=\"749\">27</sup> דהל\"ל היושב בשמים. אך הנה יו\"ד זה הוא בחי' ההמשכה שנמשך בשמים ובארץ הנעשה ע\"י עליית וביטול בחי' שמים לבחי' אוא\"ס שלאו מכל אינון מדות כו'.\n<b>וזהו</b> שמבחי' הללו מן השמים נעשה אח\"כ הללוהו במרומים שהוא בחי' בריאה, כנודע ההפרש בין שמים למרום<sup data-n=\"750\">28</sup>, שמרום אינו עצם השמים כ\"א מה שנראה לנו גוון השמים, שבאמת אינו בחי' השמים עצמם כי השמים לעוצם גבהו אינו נראה לנו כלל, ומה שנראה לנו הוא רק מה שנעשה באויר מגוון השמים, וזהו הנק' מרום, ולמעלה הוא בחי' עולם הבריאה<sup data-n=\"751\">29</sup>. הללוהו כל מלאכיו הוא בחי' היצי', כי מלאכים הם בחי' שלוחי ההשפעה והם המלאכים דיצי' כמ\"ש אלף אלפים ישמשוני' וריבוי רבבן קדמוהי יקומון, פי' אלף אלפים ישמשוני' הוא בחי' המלאכים דיצי' שהם שלוחים, אבל בחי' ריבוי רבבן קדמוהי יקומון הם אינם שלוחים כי הם בעולם הבריאה שהם למעלה מבחי' השפעה, כי בורא חשך כתיב שעולם הבריאה נק' בשם חשך שהוא בחי' העלם שלמעלה מבחי' השפעה כו', ויצי' נק' אור כו'. הללוהו כל צבאיו הם מלאכים דעשי' שנק' צבאיו ע\"ש כי על ידם נעשה הרצון עליון, כי צבאיו הוא ל' רצון, שעושים צביוני בעולם פי' שעושים רצוני.\n<b>הללוהו</b> שמש וירח הוא בחי' התכללות עשי' ביצי', ונקראים יצי' ועשי' בשם שמש וירח לפי ששמש הוא בחי' ז\"א וירח הוא בחי' מל' וז\"א מקננא ביצי' ומל' בעשי'. הללוהו כל כוכבי אור הוא בחי' התכללות יצי' בבריאה<sup data-n=\"752\">30</sup>, ונק' בריאה ע\"ש כוכבי אור לפי שהכוכבים הם ברקיע תמינאה שהוא בינה אימא עילאה, ואימא עילאה מקננא בבריאה כו' כנודע. ואח\"כ כתיב יהללו<sup data-n=\"753\">31</sup> את שם הוי' כי הוא צוה ונבראו, פי' נבראו ממילא<sup data-n=\"754\">32</sup>, כי אע\"פ שנאמר בראשית ברא אלקים שהבריאה היא משם אלקים, אך זהו ברא לנוכח שהוא בחי' כח הפועל בנפעל, אבל עיקר הבריאה הוא מש' הוי' רק שהוא ע\"ד בחי' ונבראו ממילא בלתי התלבשות ע\"ד מי שאמר והי' העולם כו'. ויעמידם לעד לעולם שבחי' אלו הוא רק בחי' עמידה<sup data-n=\"755\">33</sup> וכמשי\"ת אי\"ה.",[["749","27","<b>וזהו מ\"ש היושבי בשמים. . יו\"ד שבתיבת היושבי מיותר</b>: ראה יהל אור לתהלים ע' תפח. סה\"מ תרל\"ו ח\"ב ע' שסו."],["750","28","<b>כנודע ההפרש בין שמים למרום</b>: ראה בארוכה סידור עם דא\"ח שם סה, סע\"א-ב. מאמרי אדה\"ז על מארז\"ל שם ע' תיא."],["751","29","<b>מרום. . הוא בחי' עולם הבריאה</b>: ראה סידור עם דא\"ח שם סה, ג."],["752","30","<b>הללוהו שמש וירח. . התכללות עשי' ביצי'. . הללוהו כל כוכבי אור. . התכללות יצי' בבריאה</b>: כ\"ה גם בס' מאמרי אדה\"ז על מארז\"ל שם. אך בסידור עם דא\"ח שם פי' הללוהו שמש וירח (שמש הוא בחי' ז\"א שמקננא ביצי', וירח בחי' מל' הוא בעשי') הוא התכללות עשי' ויצירה בבריאה, והללוהו כל כוכבי אור הוא התכללות בריאה באצי'. עיי\"ש."],["753","31","<b>ואח\"כ כתי' ביהללו</b>: במאמר זה לא נת' כאן הפסוק הללוהו שמי השמים גו', וראה סידור עם דא\"ח שם סו, סע\"א-ב."],["754","32","<b>כי הוא צוה ונבראו פי' נבראו ממילא</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381187\" data-slug=\"likkutei-torah\" data-id=\"4001381187\">לקו\"ת שה\"ש יד, ג</a> ואילך. סה\"מ תרכ\"ט ע' קלה ואילך. תרל\"ג ח\"א ע' כב. וש\"נ."],["755","33","<b>שבחי' אלו הוא רק בחי' עמידה</b>: בד\"ה זה תרכ\"ז נוסף כאן: ועכ\"ז יש בזה ג\"כ הגדלה וריבוי."]]],[2000460259,"<b>הללו</b> את ה' מן הארץ כו' אש כו', קחשיב בכאן ד' יסודות ארמ\"ע וד' מדרגות דצח\"ם<sup data-n=\"756\">34</sup>, ומסיים הודו על ארץ ושמים וירם קרן לעמו כו' לבנ\"י עם קרובו, פי' הודו על ארץ ושמים בתחלה ארץ ואח\"כ שמים מפני כי מבחי' זו שמים מקבל מארץ, כי הודו קאי על התורה שזהו שביקשו המלאכים תנה הודך על השמים, שביקשו שיתן להם התורה ולא ניתן להם כ\"א על הארץ, ולכן בחי' זו מקבלים שמים דהיינו המלאכים מארץ דהיינו מנשמות, וזהו כמ\"ש היושבת בגנים חברים מקשיבים לקולך השמיעני, פי' היושבת בגנים קאי על הנשמות היושבים בג\"ע, חבירים מקשיבים לקולך קאי על מלאכי השרת<sup data-n=\"757\">35</sup> שמקשיבים לשמוע מהם דברי תורה, לכן בבחי' זו מקבלים שמים מארץ כו'.\n<b>וירם</b> קרן לעמו, הנה כתיב יראו את ה' קדושיו כי אין מחסור ליריאיו, וצ\"ל מהו קדושיו דוקא הלא כתיב יראו מה' כל הארץ. אך יראו מה' כל הארץ זהו מהוי' בחי' יראה מרחוק, אבל את הוי' בחי' בטל וטפל לש' הוי' הוא קדושיו דוקא כמ\"ש במ\"א בד\"ה וירא ישראל את היד הגדולה (תרח\"י)<sup data-n=\"758\">36</sup>, ופי' יראו את ה' קדושיו פי' קדושיו קאי על המצות שפי' מצוה הוא ל' צוותא וחיבור. וזהו ג\"כ ענין עם קרובו [שקרובים] לבחי' ש' הוי'<sup data-n=\"759\">37</sup> והיינו ע\"י קבעומ\"ש שהוא בחי' יראה כמשי\"ת לקמן, וע\"י קבלת עול מצות, שמצוה הוא לשון צוותא להיות בבחי' את הוי' בטל וטפל לש' הוי'. והענין הוא כי בחי' בריאת העולמות הוא רק מהארה בעלמא אבל ע\"י המצות נעשה צוותא וחיבור עם עצמיות אוא\"ס ב\"ה, וזהו כי אין מחסור ליריאיו, הנה אין הוא בחי' שאינו מושג כלל שהוא למעלה מבחי' סדר השתלשלו', שסדר השתלשלו' הוא מבחי' החכמה ואילך, אבל אין הוא למעלה מן החכמה וכמ\"ש והחכמה מאין תמצא, וע\"י בחי' היראה יכולים לבוא לבחי' אין כמשי\"ת.\n<b>ובזה</b> יובן ענין וירם קרן, כי הנה נודע ממ\"ש בזהר על מארז\"ל ובא לו לקרן דרומי' מזרחית<sup data-n=\"760\">38</sup> כו', ובא לו לקרן בקדמיתא, שמתחלה צ\"ל בחי' קרן, ואח\"כ יוכל לבוא לבחי' דרומי' שהוא בחי' אהבה הלוך ונסוע הנגבה. וענין הקרן, הנה הקרן יש בו כמה פירושים, הא' לשון קרן זוית<sup data-n=\"761\">39</sup>, שענין הקרן זוית אינו מהות בפ\"ע",[["756","34","<b>הללו את ה' מן הארץ. . קחשיב כאן. . וד' מדרגות דצח\"מ</b>: ראה בארוכה סידור עם דא\"ח שם סו, ד שכאן קאי על בחי' מל' דעשי' שגם בזה יש ב' ענינים הנ\"ל דהמשכה מלמעלמ\"ט והתכללות מלמטלמ\"ע. עיי\"ש."],["757","35","<b>היושבת בגנים קאי על הנשמות היושבים בג\"ע חברים מקשיבים. . מלאכי השרת</b>: ראה גם סה\"מ תש\"י ע' 119. ע' 125. סה\"מ מלוקט ח\"א ע' יג ואילך. ח\"ב ע' רלה-ו. ועוד."],["758","36","<b>במ\"א בד\"ה וירא ישראל את היד הגדולה (תרח\"י)</b>: <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8315950460\" data-slug=\"or-hatorah-hb\" data-id=\"8315950460\">אוה\"ת בשלח ע' תס</a> ואילך. וראה גם שם ע' תלב ואילך. סה\"מ תרכ\"ז ע' רמז ואילך. וש\"נ. לעיל ד\"ה זאת חוקת. ועוד."],["759","37","<b>שקרובים] לבחי' שם הוי'</b>: בגוכי\"ק בס' תרל\"ט אינו ברור אם תיבת שקרובים נמחקה או לא [ולכן הודפס בין חצאי ריבוע]."],["760","38","<b>ממ\"ש בזהר על מארז\"ל ובא לו לקרן דרומית מזרחית</b>: ראה בכ\"ז ביאוה\"ז לאדהאמ\"צ קמד, ב ואילך. ולהצ\"צ ח\"א ע' תסד ואילך. אוה\"ת נ\"ך ע' קלו ואילך. וראה גם סה\"מ תרכ\"ט ע' רפט."],["761","39","<b>הקרן יש בו כמה פירושים הא' לשון קרן זוית</b>: בד\"ה זה בס' תרכ\"ז נוסף כאן: הב' ל' מלוכה כמו קרן חזית בדניאל, הג' ל' קרן עור פני משה. — וראה בכ\"ז בהנסמן בהערה שלפנ\"ז."]]],[2000460260,"כלל רק שהוא מחבר ב' הכתלים, כמו עד\"מ דרום ומזרח הנה כל הנמשך בדופן דרום הוא דרום, והנמשך בדופן מזרח הוא מזרח, והקרן נק' מקום חיבורם זל\"ז שאינו מהות בפ\"ע כלל. וכמו\"כ בחי' מלוכה נק' ג\"כ קרן כמ\"ש רמה קרני וארז\"ל דוד שנמשח בקרן נמשכה מלכותו כו', וכן כתי' בדניאל קרן חזית שקאי על מלוכה, והיינו מפני כי ענין המלוכה הוא ג\"כ אינו מהות בפ\"ע רק הוא בחי' חיבור המלך עם העם, כי המלך הוא בפ\"ע והעם המה בפ\"ע, וחיבורם הוא בחי' המלוכה, והו\"ע בחי' יראה וביטול של העם לגבי המלך ולכן נק' בשם קרן. ובנפש האדם בעבודה בחי' קרן הוא בחי' קבעומ\"ש שהוא בחי' יראה, ולמעלה הוא בחי' מל' מלכותך מלכות כל עולמים. ופי' וירם קרן היינו שע\"י בחי' יראה יגיע לבחי' אין כי אין מחסור ליריאיו, ובאמת א\"א להגיע לבחי' אין כ\"א ע\"י יראה דוקא שהוא בחי' ביטול, כי אהבה הוא בחי' יש מי שאוהב, אבל יראה הוא בחי' ביטול, ולכן על ידה יכול להגיע לבחי' אין שלמעלה מן השגה. וז\"ע רוממות קרן, והיינו כמו הפי' הג' בתיבת קרן שהוא מל' כי קרן עור פני משה, והיינו ג\"כ כנ\"ל כי משה הי' בחי' מ\"ה ונחנו מ\"ה דהיינו בחי' חכ', ופי' קרן עור פני משה הנה ההארת פנים הוא בחי' שלמעלה מן משה בעצם<sup data-n=\"762\">40</sup> והיינו בחי' אין שלמעלה מן החכמה כו' וז\"ע רוממות קרן כו'.\n<b>והנה</b> בד\"כ ענין בחי' הביטול דשמים ומרומים ומלאכיו וצבאיו הוא להמשיך בחי' חיות העולמות בחי' ובטובו מחדש בכי\"ת מע\"ב, שצ\"ל אתעדל\"ת לזה, והוא בחי' אתעדל\"ת דנבראים ומלאכים שהוא בחי' השירה שלהם כמשארז\"ל כל בעלי השיר<sup data-n=\"763\">41</sup> יוצאין בשיר כו'. וע\"פ הקבלה הוא להמשיך זווג חיצוני דחו\"ב שזיווגייהו תדיר לצורך קיום העולמות, כי בינה נק' יש כמ\"ש להנחיל אוהבי יש והחכמה נק' אין<sup data-n=\"764\">42</sup> כמ\"ש והחכמה מאין תמצא וזיווגייהו תדיר שאל\"כ הי' חוזר העולם לתהו ובהו, ואעפ\"כ צ\"ל אתעדל\"ת לזה והוא בחי' השיר והביטול של המלאכים כו'. וזהו ויעמידם לעד לעולם שבחי' זו נק' עומדים לפי שאין בה התחדשות כ\"א חידוש הישינות, והנה אף שנק' עומדים אעפ\"כ בבחי' עמידה גופא יש עליות וירידות וכמו שאנו רואים ששנה זו נשפע רוב טובות משא\"כ בשנה אחרת, וכמו שבע שני השבע ושבע שני הרעב, ובד\"כ נק' עמידה כנ\"ל<sup data-n=\"765\">43</sup>, אבל נש\"י ממשיכים אור חדש, וזהו וירם קרן שע\"י הרוממות קרן ממשיכים אור חדש מבחי' אין כו'.",[["762","40","<b>קרן עור פני משה. . הוא בחי' שלמעלה מן משה בעצם</b>: בד\"ה זה תרכ\"ז מוסיף כאן: שזה זכה ע\"י התורה לוחות העדות שקיבל בהר כמ\"ש בס\"פ כי תשא."],["763","41","<b>אתעדל\"ת דנבראי' ומלאכים. . השירה שלהם. . כל בעלי השיר</b>: ראה בכ\"ז בארוכה לעיל ד\"ה אז ישיר. וש\"נ. לקמן ד\"ה עבדו את ה' בשמחה."],["764","42","<b>בינה נק' יש. . והחכ' נק' אין</b>: ראה גם לקמן ד\"ה מזמור לתודה. וש\"נ."],["765","43","<b>ובד\"כ נק' עמידה כנ\"ל</b>: בד\"ה זה תרכ\"ז נוסף כאן: לגבי הזיווג פנימי דחו\"ב להמשיך בחי' אור חדש."]]],[2000460261,"<h3>והי' ברכה</h3>\n<b>ש\"פ לך ל\"ט</b>\n<b>והי'</b> ברכה<sup data-n=\"766\">1</sup>, ואמרז\"ל שברכה ראשונה דאבות חותמין במגן אברהם, דכל הברכה ראשונה אמרו על פסוק זה, ואעשך לגוי גדול זהו מה שאומרים אלקי אברהם, ואברכך זהו מה שאומרים אלקי יצחק, ואגדלה שמך אלקי יעקב, יכול יהא חותמין בכולם ת\"ל והי' ברכה בך חותמין. וצ\"ל למה חותמין באברהם דוקא ולא בכל האבות, דהנה במ\"א נת' ע\"פ ועשיתי לך שם גדול כשם הגדולים<sup data-n=\"767\">2</sup>, וקאי על מגן דוד כשם הגדולים אברהם יצחק ויעקב<sup data-n=\"768\">3</sup>, והלא אין חותמין רק מגן אברהם ומתרצין שם תירוצים ע\"ז, ולכאורה למה אין חותמין כאן בכל האבות. והענין דהנה צ\"ל תחילה הברכה דמגן אברהם שיש בה ב' פי', הא' דאברהם הוא המגן, הב' דאברהם צריך מגן שלא<sup data-n=\"769\">4</sup> גילוי כ\"כ, דהנה אמרז\"ל לעתיד הקב\"ה מוציא חמה מנרתקה כו' וזהו המגן שהוא הנרתק.\n<b>והנה</b> כאן נדבר שאברהם צריך מגן כמ\"ש אנכי מגן לך. דהנה ברוב דרושים אי' דאברהם הוא חסד עולם<sup data-n=\"770\">5</sup> אהבת עולם והכל א', ועל ל' הקבלה הוא חסד דמ\"ה, ועל ל' החסידות הוא חסד דביטל, כמו אברהם שהי' אבר מ\"ה, אבר וכלי לבחי' ביטל וכמ\"ש ואנכי עפר ואפר, מפני שהי' בטל לכן השפיע לזולתו מפני הביטל שהוא גרוע מזולתו לכן השפיע הכל לזולתו בלי דיקדוקים כלל וכמ\"ש באוצ\"ד<sup data-n=\"771\">6</sup> בשער הנדיבות שהי' נדיב בנפשו ובגופו ובממונו, דכל הדברים שיש בדברים האלו הי' נדיב בהם (בנפשו היינו בהשפעת דבר שכל, ובגופו היינו בטרחה שלא הניח לא' מעבדיו לשמש את האורחים אלא הוא בעצמו, ובממונו שהשפיע ממון לכל אחד) ובלי דיקדוק כלל שהיה מאכיל ומשקה גם לערביים וזה הי' מצד הביטל. ויש בחי' ורב חסד שהוא מצד ולגדולתו אין חקר שלגדולתו העצמיות אין חקר כלל, לכן נמשך לבחי' גדולה (הנה בכ\"מ נת' דרב חסד הוא חסד דאריך<sup data-n=\"772\">7</sup> והוא נק' גדולה וכמ\"ש בד\"ה מים רבים בענין לך ה' הגדולה<sup data-n=\"773\">8</sup>, אך כפי מ\"ש לקמן שהוא",[["766","1","<b>והי' ברכה</b>: הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע מד\"ה זה הנדפס לעיל ע' א. וראה בהמ\"מ בתחילת המאמר שם."],["767","2","<b>במ\"א נת' ע\"פ ועשיתי לך שם גדול כשם הגדולים</b>: אוה\"ת שמות ע' לא. סה\"מ תר\"ל ע' עא וע' ק."],["768","3","<b>וקאי על מגן דוד כשם הגדולים אברהם יצחק ויעקב</b>: ע\"פ פסחים קיז, ב: ועשיתי לך שם גו' זהו שאומרים מגן דוד. ובפי' רש\"י (ועי' רשב\"ם שם): כשם הגדולים, אברהם יצחק ויעקב כו'."],["769","4","<b>שלא</b>: נראה דצ\"ל: שלא יהי'."],["770","5","<b>דהנה ברוב דרושים אי' דאברהם הוא חסד עולם</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370308\" data-slug=\"torah-or\" data-id=\"3901370308\">תו\"א יתרו סט, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370366\" data-slug=\"torah-or\" data-id=\"3901370366\">תצוה פב, א</a> ואילך. מאמרי אדה\"ז תקס\"ה ח\"א ס\"ע דש ואילך. תקס\"ו ע' רכד ואילך. מאמרי אדהאמ\"צ שמות ח\"ב ס\"ע שלח ואילך [ובהנסמן שם בתחלת המאמר]. סה\"מ תרכ\"ז ע' קצט."],["771","6","<b>באוצ\"ד</b>: באורחות צדיקים. ראה מזה גם באוה\"ת וירא צ, ב. תזריע ע' תקכא. סה\"מ תרפ\"ט ע' 90 ואילך. תרח\"צ ע' קכט ואילך."],["772","7","<b>בכ\"מ נת' דרב חסד הוא חסד דאריך</b>: ראה אוה\"ת וירא צ, א ואילך. סה\"מ תרכ\"ז ע' קצז ואילך. וש\"נ."],["773","8","<b>וכמ\"ש בד\"ה מים רבים בענין לך ה' הגדולה</b>: המשך מים רבים תרל\"ו פמ\"ז (ע' נד ואילך)."]]],[2000460262,"בחי' כי חפץ חסד מוכרח לומר שכוונתו על חסד דעתיק. אך אפ\"ל חפץ הוא פנימיות הרצון אך לא בחי' עתיק, דעתיק הוא תענוג בכחות הנפש, אך ממ\"ש לקמן נהורא קדמאה כו' מוכרח לומר שכוונתו על בחי' עתיק דאור שבעת הימים הם ז\"ת דעתיק. ומ\"ש דאברהם אפ\"ל מפני שחסד הוא יומא דאזיל עם כולא יומין. ופי' ולגדולתו, הנה כאן פי' ולגדולתו העצמיות למעלה מחסד דעתיק, ובסידור בפי' ולגדולתו אין חקר<sup data-n=\"774\">9</sup> פי' לגדולתו העצמיות היינו בחי' חכ' טרם התפשטותו בכלים מכלים שונים).\n<b>וצ\"ל</b> דהנה נת' במ\"א ע\"פ וחסדי מאתך לא ימוש<sup data-n=\"775\">10</sup>, שהוא בחי' חסד עליון אהבה רבה הבאה מלמעלה והוא בחי' כי חפץ חסד (ובק\"י<sup data-n=\"776\">11</sup> ערך חס פי' חסד עליון חסד דחכמה, אך כאן מפרש שהוא חסד דעתיק כמשנת\"ל), ונת' ע\"ז משל מחסד דאברהם, וא\"כ אברהם הוא ג\"כ בחי' [כי חפץ חסד], וכ\"כ באדרא שהוא חסד דלגאו<sup data-n=\"777\">12</sup> וא\"כ הוא ג\"כ בחי'<sup data-n=\"778\">13</sup> זו, וכ\"כ בזהר במא' אלה תולדות השמים וארץ בהבראם באברהם וזה אי' בכ\"מ<sup data-n=\"779\">14</sup> ולא דוקא בזהר, וכ' עוד שם נהורא קדמאה דגניז לי' קוב\"ה ודא הוא אברהם, א\"כ מפרש דאברהם הוא נהורא קדמאה והוא בחי' כי חפץ חסד חסד דלגאו (נהורא קדמאה הוא אור שבעת הימים וידוע דאור שבעת הימים הוא ז\"ת דעתיק כנ\"ל) וא\"כ בב' מקומות בזהר משמע שאברהם הוא רב חסד. והענין דהנה יש אברהם באצי' והוא בחי' חסד דמ\"ה ולכן השפיע לכל אדם וכמ\"ש בפרדס בשם ס' הבהיר אמרה מדת החסד לפני הקב\"ה כל ימי היות אברם בארץ לא הוצרכתי אני לעשות מלאכתי שהרי אברם עומד ומשמש במקומי, הרי שהחליף מקום מדת החסד שלא הי' צריך לעשות מלאכתו כלל שמביא ע\"ז פסוק וישמור משמרתי ששמר משמרת מדת החסד שבהשפעתו שהשפיע למטה גרם שיהי' מכלכל חיים בחסד שיומשך השפעת החיים [וזה המשיך אפי' אברם ולא אברהם], (וצ\"ע דהנה ידוע דאברם הוא שכל הנעלם מכל רעיון שא\"א שיתגלה למטה, ונתוסף לו ה' היינו שיהי' הגילוי למטה, וקודם שנתוסף לו הה' עדיין לא הי' גילוי בלמטה בבי\"ע, וע' בתו\"ח פ' לך בד\"ה ויאמר ה' אל אברם<sup data-n=\"780\">15</sup> וכמדומה שמשם כאן שכ' שם שגם קודם שנתוסף לו הה' נמשך ג\"כ בבי\"ע אך בצמצום כפי המדה ולא יותר, ונתוסף לו הה' שיומשך יותר מכפי המדה) וזהו בחי' חסד דמ\"ה. אך מוכרח לומר שיש בחי' אברם גם לפני",[["774","9","<b>ובסידור בפי' ולגדולתו אין חקר</b>: סידור עם דא\"ח מז, א."],["775","10","<b>נת' במ\"א ע\"פ וחסדי מאתך לא ימוש</b>: <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560292\" data-slug=\"or-hatorah-hb\" data-id=\"8316560292\">אוה\"ת נח (כרך ג) תריב, ב</a> ואילך."],["776","11","<b>ובק\"י</b>: ובקהלת יעקב, לבעהמח\"ס מלא הרועים."],["777","12","<b>וכ\"כ באדרא שהוא חסד דלגאו</b>: זח\"ג קלג, ב."],["778","13","<b>בחי' </b>[כי חפץ חסד]: כ\"ה בגוכי\"ק בתוך חצאי מוסגר. בכת\"י הנחות זה נמצא במקומות רבים כמה תיבות בתוך מוסגרים, ואפשר בכ\"מ הוא ממה שנאמר מכ\"ק אדמו\"ר מהר\"ש נ\"ע בעת חזרת המאמר בפעם שני'."],["779","14","<b>בזהר במא' </b>[ במאמר]<b> אלה תולדות. . בהבראם באברהם. . בכ\"מ</b>: זח\"א פו, ב. צא, ב. צג, א. רל, ב. רמז, א. ועוד. מד\"ר בראשית פי\"ב, ט. תנחומא (באבער) בראשית טז. מדרש תהלים קד, יח."],["780","15","<b>וע' בתו\"ח פ' לך בד\"ה ויאמר ה' אל אברם</b>: דף פ, ב ואילך. וראה שם פג, ד ואילך."]]],[2000460263,"אצי' וכמ\"ש בעבר הנהר ישבו אבותיכם [ואי' בזהר הוא טורי חשוכא דלפני אצי'], והוא בחי' ורב חסד (הגה. ע' בתו\"א פ' וישלח בד\"ה ויקם בלילה הוא, ובתו\"ח שם בד\"ה ויקח מן הבא בידו<sup data-n=\"781\">16</sup>, וצ\"ע. עכ\"ה.) שנמשך מצד ולגדולתו כו', וזהו אברהם שלפני אצי', ולכן אמר לו ישמעאל יחי' לפניך, שידע את ישמעאל<sup data-n=\"782\">17</sup> מ\"מ אמר יחי' לפני\"ך, ונת\"ל שהוא כמ\"ש לפני הוי' (ע' בד\"ה פי' פתחה בחכמה<sup data-n=\"783\">18</sup>) והוא מצד הגדולה, לפ\"ז אין צריך לומר שמה שהאכיל והשקה לכל אדם הוא מצד הביטל (ובפ\"א<sup data-n=\"784\">19</sup> ד?ס איז ד?ך א ?שעטיל) אלא מצד הגדולה, (ובפ\"א בחי' ורב חסד למעלה מאצי' בעצם). (והנה כפי משנ\"ת במ\"א שרב חסד הוא חסד דאריך<sup data-n=\"785\">20</sup>, ויש דעה דח\"ס הוא ראשית האצי', מ\"מ אצי' בעצם הוא מחכמה ולמטה. ואפי' כמשנ\"ת כאן דרב חסד הוא חסד דעתיק, אך הנה אי' במק\"מ בשם האריז\"ל בהקדמת הזהר ד\"א ע\"ב וז\"ל, שכל עולם האצי' מן עתיק עד המל' כו' עכ\"ל לעניננו, הרי שגם עתיק בכלל עולם האצי' יחשב, מ\"מ אצי' בעצם הוא מחכמה ולמטה, לכן אמר כאן למעלה מאצי' בעצם).\n<b>ומפני</b> שאברהם הוא בחי' ורב חסד לכן צריך מגן. דהנה אמרז\"ל בתחלה עלה במחשבתו לברוא את העולם במדת הדין ראה שאין העולם מתקיים עמד ושיתף עמו מדת הרחמים, וצ\"ל הלא כתיב טוב וישר הוי', ואי' בע\"ח כשעלה ברצונו כו' מצד טבע הטוב להיטיב (הגה, בכ\"ד מביאין הע\"ח שער הכללים פ\"א<sup data-n=\"786\">21</sup>, וצ\"ע דתיבות מצד טבע הטוב להטיב כי חפץ חסד הוא אינו נמצא בע\"ח<sup data-n=\"787\">22</sup>, וז\"ל שם כשעלה ברצונו ית' שמו לברוא את העולם להיטיב לברואיו עכ\"ל. ואפשר שמדייקינן למה",[["781","16","<b>ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370117\" data-slug=\"torah-or\" data-id=\"3901370117\">תו\"א</a> פ' וישלח בד\"ה ויקם בלילה הוא. ובתו\"ח שם בד\"ה ויקח מן הבא בידו</b>: תו\"א כה, א ואילך. תו\"ח קצו, ב ואילך."],["782","17","<b>ולכן א' לו ישמעאל יחי' לפניך, שידע את ישמעאל</b>: ראה בהמ\"מ לעיל בהמאמר ע' ב."],["783","18","<b>ע' בד\"ה פי' פתחה בחכמה</b>: ראה ס' מאמרי אדה\"ז הקצרים ר\"ע רסג."],["784","19","<b>ובפ\"א</b>: ר\"ל בפעם הא' שנאמר המאמר מאת כ\"ק אדמו\"ר מהר\"ש, הוא הוסיף גם תיבות אלו. (ועד\"ז להלן בסמוך)."],["785","20","<b>כפי משנ\"ת במ\"א שרב חסד הוא חסד דאריך</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380410\" data-slug=\"likkutei-torah\" data-id=\"4001380410\">לקו\"ת נשא כה, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380433\" data-slug=\"likkutei-torah\" data-id=\"4001380433\">בהעלותך ל, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380516\" data-slug=\"likkutei-torah\" data-id=\"4001380516\">שלח נא, א</a>. ובכ\"מ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670522\" data-slug=\"torat-chaim\" data-id=\"2300670522\">תו\"ח וירא קז, א</a>. וראה סה\"מ תרמ\"ח ע' קצ ואילך."],["786","21","<b>בכ\"ד מביאין הע\"ח שער הכללים פ\"א</b>: סידור עם דא\"ח קט, ב. עטרת ראש ס, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680433\" data-slug=\"torat-chaim\" data-id=\"2300680433\">תו\"ח מקץ רכה, א</a>. בשלח (הוצאה החדשה) קנב, ג. ריח, א. רמח, א. ויקהל תמב, א. מאמרי אדהאמ\"צ דברים ח\"ג ע' תתמג (ובהמ\"מ שם. וע\"ש בהמ\"מ גם בענין כי חפץ חסד הוא). קונטרסים ע' ה (ובהמ\"מ שם)."],["787","22","<b>וצ\"ע דתיבות מצד טבע הטוב להטיב כי חפץ חסד הוא אינו נמצא בע\"ח</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241348\" data-slug=\"likkutei-sichot\" data-id=\"1300241348\">לקוטי שיחות חכ\"ד ע' 334</a> אחרי שמביא בהערה לשון מאמר כ\"ק אדהאמ\"צ (קונטרסים שם) אשר הוא ”עצם הטוב ומטבע הטוב להטיב\", כותב ע\"ז: לע\"ע לא מצאתיו בע\"ח — ואולי הדיוק ”בענין\", ולא הל' ממש. אבל ג\"ז צ\"ע ממש\"כ בהמשך תרס\"ו (בתחלתו ובד\"ה אם בחוקותי). אין לתרץ ע\"פ מש\"כ בד\"ה יו\"ט של ר\"ה, תרנ\"ט בתחלתו, ובד\"ה איתא במדרש תהלים, תרנ\"ג (נדפס בספר המאמרים ה'תש\"ח 273) — כי בשני מקומות הנ\"ל המדובר במדות שלמטה ממוחין (תורה), וכאן המדובר בענין כל יכול. — נמצא בעמה\"מ ש' שעשועי המלך רפ\"א. ש' היחוד והאמונה פ\"ד. שומר אמונים ויכוח ב' סי' יד. ולהעיר משו\"ת ח\"צ סי\"ח. ע\"כ. וראה הנסמן בהערה הקודמת."]]],[2000460264,"עלה ברצונו כך הוא מצד טבע הטוב להיטיב. גם במק\"מ בראשית ד\"א א' כ' כשרצה הא\"ס לגלות גודל<sup data-n=\"788\">23</sup> ולהטיב לזולתו, ולא כ' מצד טבע כו' עכ\"ה), א\"כ טבעו להטיב ואיך עלה במחשבתו לברוא העולם במדת הדין שהוא היפך טבעו. והענין דהנה כתיב אשר ברא אלקים לעשות לתקן, אפי' תורמסין צריכין תיקון, ופי' תורמוסין הוא משל שעולם העשי' ורפ\"ח ניצוצי' צריכין תיקון. והנה אם הי' הבריאה במדת החסד לא הי' יכול להיות הבירורים כמ\"ש במדרש דהי' חטאין סגיאין לכן ברא במדת הדין, (הג\"ה, ע' בתו\"א בד\"ה מי שם פה לאדם<sup data-n=\"789\">24</sup> כ' שתיקון הוא שמיטה שני' בחי' דין משא\"כ תהו הי' בבחי' חסד, עכ\"ל, והוא מפני ששם לא הי' עבודת הבירורים לכן הי' בבחי' חסד משא\"כ עולם התיקון שצ\"ל בירורים הוא מבחי' דין), ואם הי' הבירור במדת הדין לבד הי' הבירור במעט זמן אך לא הי' העולם מתקיים דמצד מדת הדין הן שמים לא יזכו בעיניו, אפי' שמים שהם מספרים כבוד אל והנבראים הגבוהים מ\"מ לא יזכו בעיניו, לכן שיתף עמו מדת הרחמים, (הג\"ה, ע' בשערי אורה בשער הפורים בד\"ה יביאו לבוש מל' באות ז', וכ\"מ בע\"ח שער הכללים פ\"ד, וז\"ל וא\"ת למה המאציל העליון לא עשה מתחילה ה' פרצופים אלו ולא יעשה אותם נקודות שיהיו נשברות, והלא גלוי וידוע כי בהיותן נקודות לא יוכלו לסבול האור, התשובה כי כוונת המאציל העליון היתה כדי שיהי' בחירה ורצון ביד האדם באשר שיהי' רע וטוב בעולם כו', עכ\"ל. הרי שגם קודם שנתהווה עולם התהו הי' ג\"כ מצד השכל כדי שיהי' בחירה ושכר ועונש, שכר לצדיקים כו', עכ\"ה), כמו\"כ כאן מפני רב חסד דאברהם צריך מגן.\n<b>וענין</b> המגן הנה בדרוש א' פי' רבינו (הוא בד\"ה אנכי מגן לך<sup data-n=\"790\">25</sup>) שהוא הקשת שמורה חיצים, לובש האדם מגן בל\"א פאנציר להגן עליו מפני החיצים, כמו\"כ כתיב שמש ומגן הוי' אלקים, שהוא מגן ונרתק השמש שהוא כדי שלא יאיר השמש בתוקף, דלעתיד הקב\"ה מוציא חמה מנרתקה רשעים נידונין בה (הוא לתרץ דלכאו' אין המשל מכוון אל הנמשל דשם המגן לשמור מהרע כנ\"ל, אבל בנמשל מה שייך שם רע, לכן אמר דהיינו מה שרשעים נידונין בה, כ\"א בפ\"א<sup data-n=\"791\">26</sup>), כמו\"כ הוא מגן אברהם (הג\"ה, ז\"ל בתו\"א ד\"ה אנכי מגן לך, דהנה נודע שאברהם הוא בחי' חסד גדול עד מאד בלי שום מונע וכולם טובים בעיניו ולכן אמר לו ישמעאל כו' לפניך שהוא בחי' א\"ס בלי גבול (והו\"ע לפני הוי' שנת\"ל כו'), אבל באמת אינו מהראוי כן דהנה בביאת משיח אי\"ה כתיב בלע המות לנצח ואת רוח הטומאה אעביר מן הארץ כו', והנה נודע כי מגן נק' דבר המכסה למשל במלחמה כו', והנה נודע שבכל בוקר דאברהם בחי' חסד מתעורר בעולם וישכם אברהם בבוקר, וכדאי' בזהר, והקב\"ה רוצה להנהיג את העולם בבחי' חסד, אם לא הי' מגן לבחי' חסד הנ\"ל לצמצם חסדו וטובו ולתת דרך צמצום כמו שצריך רק להחיות הקליפות מפני שצריכין בשביל סטרא",[["788","23","<b>לגלות גודל</b>: אוצ\"ל כאן: לגלות גודל חסדו. [ולע\"ע צ\"ב מקומו במק\"מ]."],["789","24","<b>ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370232\" data-slug=\"torah-or\" data-id=\"3901370232\">תו\"א</a> בד\"ה מי שם פה לאדם</b>: נא, ד ואילך."],["790","25","<b>בד\"ה אנכי מגן לך</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370052\" data-slug=\"torah-or\" data-id=\"3901370052\">תו\"א לך לך יב, א</a>."],["791","26","<b>כ\"א בפ\"א</b>: כן אמר (כ\"ק אדמו\"ר מהר\"ש) באמירתו דרוש זה בפעם א'."]]],[2000460265,"דקדושה שיהי' אתהפכא חשוכא לנהורא וכידוע, ואם לא הי' דרך צמצום הי' חיותם בלי גבול עכ\"ל, הרי שהמגן הוא שלא ימשך למקום שאינו ראוי וכמשי\"ת אי\"ה. עכ\"ה).\n<b>אך</b> ברוב דרושים פי' שהמגן הוא הפרוכת<sup data-n=\"792\">27</sup>, היינו הפרסא המפסקת בין אצי' לבריאה (וע' מענין הפרסא בתו\"א בד\"ה ולא יקרא עוד שמך אברם ובד\"ה והבדילה הפרוכת<sup data-n=\"793\">28</sup>, וכ' שם שהפרסא הוא כדי שבי\"ע יהי' ביכולת לקבל האור. נמצא ההפרש בין הב' הפירושים, דלפירוש הא' המגן הוא כדי שלא יומשך לסט\"א, ולפירוש הב' המגן הוא כדי שיוכלו בי\"ע לקבל האור), וכ\"כ בכהאריז\"ל שהקו (ובפ\"א שחוט הא\"ס<sup data-n=\"794\">29</sup>) נמשך במחשבה הקדומה ונעשה שם פרסא (ע' בד\"ה ג' מיני אדם<sup data-n=\"795\">30</sup> שכ' שהפרסא היא אחר א\"ק, דא\"ק מא\"ס נעשה ע\"י צמצום ומקום פנוי, ועתיק נעשה מא\"ק ע\"י פרסא), והכוונה היא מהפרסא כדי שיתמעט האור, ונתמעט והולך עד שיוכלו לקבלו וזהו\"ע התיקון. וא\"כ מובן דבתהו לא הי' פרסא וזהו סיבת השבירה. אך בביאור דאד\"ר על מאמר נפק חד פרסא מקמי' כתב שהוא (עתיק) תהו, א\"כ הי' שם ג\"כ פרסא. וצ\"ל שלכן הי' השבירה מפני שלא הי' רק חד פרסא, משא\"כ בתיקון ריבוי פרסות ומסכים (ובפ\"א ונעשה פרסא בין עולמות א\"ס ובין אצי'). (הג\"ה, בין אצי' ר\"ל דכתר ג\"כ בכלל אצי' יחשב, דבין כתר לאצי' לא יש פרסא כמ\"ש בע\"ח בשער הכללים פרק א', וא\"כ צ\"ל מה הם עולמות הא\"ס שכ', וצ\"ע. עכ\"ה), [וזהו מעלת התיקון על תהו].\n<b>ובזה</b> יובן משנת\"ל (בד\"ה בראשית)<sup data-n=\"796\">31</sup> שתיקון למעלה מתהו, דתהו נפש ותיקון רוח, וכ\"כ בע\"ח עיגולים נפש ויושר רוח (ע' לעיל במאמר הראשון של ר\"ה<sup data-n=\"797\">32</sup> וצ\"ע). ובדרוש (ובפ\"א בשער) הנקודים<sup data-n=\"798\">33</sup> כ' שסיבת השבירה הוא מפני שהי' בחי' נפש, וכ\"כ רבינו בכמה דרושים שתיקון למעלה מתהו<sup data-n=\"799\">34</sup>, והמעלה דתיקון על תהו (הג\"ה, ר\"ל מאחר שתהו נפש ותיקון רוח, א\"כ צ\"ל שיש מעלה בתיקון על תהו ומהו המעלה, עכ\"ה) דבתיקון נעוץ תחילתן בסופן וסופן בתחילתן דביושר שייך ראש ורגל והראש צריך להרגל (הג\"ה, ע' בתו\"א בד\"ה מי שם פה<sup data-n=\"800\">35</sup> לאדם,",[["792","27","<b>אך ברוב דרושים פי' שהמגן הוא הפרוכת</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370017\" data-slug=\"torah-or\" data-id=\"3901370017\">תו\"א בראשית ד, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370365\" data-slug=\"torah-or\" data-id=\"3901370365\">תצוה פא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380514\" data-slug=\"likkutei-torah\" data-id=\"4001380514\">לקו\"ת שלח נ, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380593\" data-slug=\"likkutei-torah\" data-id=\"4001380593\">בלק סח, ד</a>. ועוד."],["793","28","<b>ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370052\" data-slug=\"torah-or\" data-id=\"3901370052\">תו\"א</a> בד\"ה ולא יקרא עוד שמך אברם ובד\"ה והבדילה הפרוכת</b>: פ' לך לך יב, א ואילך. יב, ג ואילך."],["794","29","<b>ובפ\"א שחוט הא\"ס</b>: ובפעם א' (שאמר כ\"ק אדמו\"ר מהר\"ש את המאמר) אמר בלשון: שחוט הא\"ס."],["795","30","<b>בד\"ה ג' מיני אדם</b>: אוה\"ת על מארז\"ל וענינים ע' פד."],["796","31","<b>משנת\"ל (בד\"ה בראשית)</b>: נדפס בסוף סה\"מ תרל\"ח, בע' שנו. וע\"ש בהמ\"מ."],["797","32","<b>ע' לעיל במאמר הראשון של ר\"ה</b>: ראה סה\"מ תרל\"ח שם ע' שיג ואילך."],["798","33","<b>ובדרוש (ובפ\"א בשער) הנקודים</b>: בפעם א' כשאמר כ\"ק אדמו\"ר מהר\"ש את המאמר, אמר בלשון: בשער הנקודים."],["799","34","<b>וכ\"כ רבינו בכמה דרושים שתיקון למעלה מתוהו</b>: ראה במובא לעיל במאמר ע' ד. וש\"נ."],["800","35","<b>ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370233\" data-slug=\"torah-or\" data-id=\"3901370233\">תו\"א</a> בד\"ה מי שם פה</b>: תו\"א שמות נב, א ואילך."]]],[2000460266,"וע' לעיל בד\"ה אנכי אנכי<sup data-n=\"801\">36</sup>, עכ\"ה), (ראיתי בכי\"ק שמסתפק<sup data-n=\"802\">37</sup> אם כוונות רבינו ז\"ל שנעיצת התחילה בסוף יותר מבראש המתפשט, או שרק הראש צריך להרגל, וכ' שזהו נעוץ תחלתן בסופן וסופן בתחלתן כו', וכפי שכאן הכריע שהראש צריך להרגל). וצ\"ל הלא ברוב דרושים נת' דתהו למעלה מתיקון<sup data-n=\"803\">38</sup>, דבתהו ריבוי אור ולכן ירדה הנשמה למטה להתלבש בגוף, דכמו שהיתה למעלה כתיב חי ה' אשר עמדתי לפניו שעמדה באהוי\"ר וביטל לאלקות ונתלבשה בגוף ונה\"ב המעלים ומסתיר, והוא כדי לברר הניצוצות ולירש אורות דתהו ואיך אמר דתיקון למעלה מתהו.\n<b>והנה</b> ענין זה יובן מענין החשמל שהוא מלביש לזו\"נ בכל צדדיו, וגם הוא נעשה הפרסא שבין אצי' לבריאה, והוא הנעל (הג\"ה, ע' מענין החשמל בתו\"א בד\"ה והבדילה הפרוכת<sup data-n=\"804\">39</sup> עכ\"ה). ושרש החשמל הוא מבינה, מחיצוניות בינה, וידוע דחיצוני שבעליון למעלה יותר מפנימי שבתחתון (הגה, וכידוע דכל מה שלמטה מטה יותר שרשו למעלה מעלה יותר, עכ\"ה), והוא כמו משל לשכל שהמשל למטה מהשכל, מ\"מ לא כל אדם יכול לומר משל אלא מי שהוא בעל שכל גדול, כמו וידבר שלמה ג' אלפים משלים והוא מפני דכתיב ויחכם שלמה מכל אדם, לכן באפשרי לומר משלים וכמו ר\"מ שאמר תלתי מישלי, אבל מי שאינו בעל שכל גדול ויאמר איזה משל לא יהי' מכוון אל הנמשל. כמו\"כ אף שחשמל הוא לבוש המלביש זו\"ן, מ\"מ שרשו למעלה יותר, כמו\"כ יובן בתהו ותיקון, דבסדר השתל' תהו למעלה מתיקון ששם רובו אור, אבל בלמעלה מסדר השתל' תיקון למעלה מתהו.\n<b>ובזה</b> יובן מ\"ש במדרש אר\"י בן חלפתא משל כשאתה נותן ב' מרגליות לשפופרת לא זו שאתה נותנת ראשונה יוצאה אחרונה. ולכאורה הלא זה היפך האמת, שהרי עשו הבכור ואיך אמר שיעקב הבכור. אך דמה שעשו הבכור היינו בסדר השתל', אבל בלמעלה מסדר השתל' יעקב הבכור. ולפ\"ז אין סתירה מה שברוב דרושים נת' שתהו למעלה מתיקון, ופעמים נת' דתיקון למעלה יותר, דשניהם אמת, דבסדר השתל' תהו למעלה יותר מפני שבו ריבוי אור. וענין ריבוי האור לא שנאמר שהריבוי ומיעוט הוא [באור א'] דבאמת אינם בערך כלל, ויובן זה מעולם התיקון גופא דאמרז\"ל אור שנברא ביום ראשון הי' אדה\"ר צופה ומביט מסוף העולם ועד סופו, ומקשין שהי' לו לומר מתחילת עולם ועד סופו, והתירוץ הוא דפי' מסוף עלמא דאתכסיא מלמטלמ\"ע (שמלמעלמ\"ט הוא תחילת עלמא דאתכסיא), ועד סוף",[["801","36","<b>ועי' לעיל בד\"ה אנכי אנכי</b>: מאמר ר\"ה תרל\"ט, נדפס בסוף סה\"מ תרל\"ח, בע' שיג."],["802","37","<b>ראיתי בכי\"ק שמסתפק</b>: כתב-יד-קודש כ\"ק אדמו\"ר מהר\"ש (ממאמרי תרל\"ט), נדפס לעיל ע' ד וז\"ל: וצ\"ע אם כוונתו שכוונת נעיצת ההתחלה כו'."],["803","38","<b>הלא ברוב דרושים נת' דתהו למעלה מתיקון</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370039\" data-slug=\"torah-or\" data-id=\"3901370039\">תו\"א נח ט, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370113\" data-slug=\"torah-or\" data-id=\"3901370113\">וישלח כד, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370119\" data-slug=\"torah-or\" data-id=\"3901370119\">כה, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370274\" data-slug=\"torah-or\" data-id=\"3901370274\">בשלח סא, א</a> ואילך. ועוד."],["804","39","<b>ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370054\" data-slug=\"torah-or\" data-id=\"3901370054\">תו\"א</a> בד\"ה והבדילה הפרוכת</b>: פ' לך לך יב, ג ואילך."]]],[2000460267,"עלמא דאתגליא מלמעלמ\"ט (שמלמטלמ\"ע הוא תחילת עלמא דאתגליא), ובזה נכלל כל סדר השתל' דיש בזה כמה מדריגות, כמו בג\"ע העליון ותחתון שהם ב' מדריגות, אף שבאמת יש כמה מדריגות כמשארז\"ל צדיקים אין להם מנוחה לא בעוה\"ז ולא בעוה\"ב שנאמר ילכו מחיל אל חיל, מ\"מ נחלק רק על ב' מדריגות, כמו\"כ כאן כתיב ברוך הוי' אלקי ישראל מן העולם ועד העולם מעלמא דאתכסיא עד עלמא דאתגליא, ועכשיו אדם רואה מיל<sup data-n=\"805\">40</sup>, א\"כ המיעוט הוא שלא בערך כלל. ועוד יובן מענין שמים קדמה או ארץ קדמה, בסדר השתל' שמים, אבל בלמעלה מהשתל' ארץ קדמה. וזהו בתיקון גופא, וכמו\"כ יובן בתהו ותיקון. אך כ\"ז בסדר השתל' אבל בלמעלה מהשתל' תיקון למעלה מתהו. וזהו\"ע המסכים והפרסות ששרשם למעלה גם מריבוי האורות דתהו דשרשן מבחי' ישת חשך סתרו.\n<b>וזהו</b> אנכי מגן לך, שהמגן נמשך מאנכי מי שאנכי. ובעבודה בנפש האדם הוא המצות מעשיות [ששרשן מאנכי מי שאנכי], והוא מ\"ש בפ' ראשונה דק\"ש והיו הדברים האלה כו', וקשרתם, וכתבתם על מזוזות כו', מצוה הוא ל' צוותא וחיבור שהחיבור הוא כמו אח ואחות, והוא בא\"ס עצומ\"ה. ולפ\"ז המצות למעלה מההתבוננות דק\"ש, אחד דז' רקיעים וארץ וד' רוחות העולם בטלים לא\"ס עצומ\"ה, ואח\"כ ברוך שם כבוד מלכותו לעולם ועד, שכל העולם הוא רק משם והארה בעלמא, ויש כאן ג' לשונות שם וכבוד ומלכותו, והוא הארה, והארה דהארה, והארה דהארה דהארה, וזהו לעולם ועד [וא\"כ מי לי בשמים ועמך לא חפצתי בארץ, גן עדן העליון וגן עדן התחתון לא חפצתי, כ\"א א\"ס עצומ\"ה, דאפי' ג\"ע הוא ג\"כ רק הארה, אך הארה מהמהות, אבל מ\"מ הוא הארה], ועי\"ז יבוא לואהבת ב\"פ אור. ובזה גופא יש כמה מדריגות בכל לבבך ובכל נפשך ובכל מאדך שהוא לדבקה בו. אך זהו רק בהתבוננות ורוצה לידבק בו, אך כדי שידבק בו זהו שא' אח\"כ והיו הדברים האלה בדברי תורה הכתוב מדבר, דע\"י תומ\"צ בא לידבק בו. וזהו\"ע המצות שלמעלה מהתבוננות [שהוא השגה, משא\"כ מצות מעשיות הם למעלה מהשגה]. אך כ\"ז מההתבוננות דק\"ש, אבל עצם המצוה דק\"ש ה\"ה מצוה כמו כל המצות, וכתיב בה והיו הדברים האלה בדברי תורה הכתוב מדבר דעקימת שפתיו הוה מעשה, א\"כ ה\"ז מצות מעשיות. וזהו שהמצות הם כלים כידוע דחסד עולם כלי לרב חסד.\n<b>ועוי\"ל</b> בעומק יותר ובאו\"א, דהנה אמרז\"ל ולא עם הארץ חסיד, וצ\"ל מה שייך בחסידות אם הוא עם הארץ או לא. והענין דהנה חסיד הוא חסד, והיו\"ד שבו יש טעמים ע\"ז (הג\"ה, בס' קהלת יעקב כ' שהיו\"ד הוא הארת החכ' שבחסד, עכ\"ה), וצריכים לקבל האור, ולכן לא עם הארץ חסיד שאין לו כלים שיאחז בהם האור, דעם הארץ היינו כמו שהי' בזמנם הבורים שלא הי' להם לא תורה ולא מצות. וזהו כי ה' אלקיך אש אוכלה הוא, כמו אש צריך פתילה שיאחז בו האור וכמו\"כ [ה' אלקיך] צריך כלי שיאחז בו, והמצות הם כלים לבחי' זו, דהנה רמ\"ח פקודין רמ\"ח",[["805","40","<b>ועכשיו אדם רואה מיל</b>: ראה בנסמן ע\"ז באורך במילואים להמ\"מ בסה\"מ תרל\"ב ח\"א ע' שלב."]]],[2000460268,"אברין דמלכא, כמו אברים הם כלים להשראת החיות, כמו\"כ מצות הם כלים להשראת אוא\"ס, וזהו זאת תורת האדם רמ\"ח מ\"ע, והחשבון הוא ט' פעמים ט' פ\"א, ראש תוך סוף רמ\"ג, וה' חסדים המגדילים רמ\"ח, ויש להם מעלה על כלים, דכלים אינם ממשיכים בתוכם, משא\"כ המצות ממשיכים בתוכם האור כמו אברים.\n<b>אך</b> זהו המצות ע\"פ פשוט [בז\"א], אך יש מצות גם למעלה מבחי' זו והו\"ע מצות הוי' ומצותי, כמו תורת הוי' כמ\"ש כי אם בתורת הוי' חפצו, וכתיב ובתורתו יהגה יומם ולילה, דתורת הוי' היינו משארז\"ל דוד הי' מחבר תורה שלמעלה בהקב\"ה והיינו מה שנתגלה למטה ותורתו היינו [שעשועי העצמי], כמו\"כ במצות ג\"כ, וכמו מועדי הוי' ומועדי, לכן הם כלים וכמ\"ש אין עוד כלי ויעמוד השמן, שמן הוא האור לגבי הכלי, וכשהי' הכלי הי' האור, אך מאחר שאין עוד כלי ויעמוד השמן. וזהו\"ע נעשה ונשמע, נשמע הוא האור, ונעשה הוא הרצון הפרטי או הרצון הכללי, והעיקר שהוא התוס' אור שנמשך.\n<b>וזהו</b> והיה ברכה, בך חותמין, דיצחק הוא מדת הפחד, ויעקב הוא מדת הרחמים נותן מקום למדת הדין, אך אברהם שהוא מדת החסד צריך חותם טבעת שאינו תופס מקום כמ\"ש אם צדקת כו' ויוכל להימשך למקום שאינו ראוי, לכן צריכים חותם שיומשך למקום הראוי."],[2000460269,"<h3>כרמי שלי</h3>\n<b>ש\"פ וירא ל\"ט</b>\n<b>כרמי</b> שלי<sup data-n=\"806\">1</sup> לפני האלף לך שלמה ומאתים לנוטרים את פריו, ואי' בגמ' כל שלמה שבשה\"ש קודש, שלמה מלך שהשלום שלו, שיר למי שהשלום שלו, וכאן שלמה לדידי'. ובזהר אי' האלף אלין אלף יומין דחול דלאו איהו מסט' דקדושה, ונת' שם שהו\"ע מ\"ש להבדיל בין הקדש לחול ובין הטהור לטמא. וכ' שם אע\"ג דאתפרישו כו' חולקא חדא אית להו מסט' דקדושה מסט' דשמאלא, ופי' במק\"מ אלף יומין דחול הם ע\"ס דנוגה, חולקא חדא הם הבירורים דנוגה. ובכתבים פי' דחולקא חדא<sup data-n=\"807\">2</sup> הוא המקיף דלבונה זכה, דבקדושה עשר לא תשע עשר ולא אחד עשר, אבל בסט\"א י\"א כתרין דמסאבות', והוא מפני דבקדושה [האור] נחשב כמו ד\"א, דההוא נביעו איהו כנשמתא לגופא ואינו נחשב לדבר בפ\"ע, אבל בסט\"א הי' האור נבלע",[["806","1","<b>כרמי שלי</b>: הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע מד\"ה זה הנדפס לעיל ע' ח. וראה בהמ\"מ שם בתחילת המאמר."],["807","2","<b>ובכתבים פי' דחולקא חדא</b>: כתבי כ\"ק אדמו\"ר הצ\"צ, ד\"ה כרמי כו', נדפס ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770394\" data-slug=\"or-hatorah-hb\" data-id=\"8316770394\">אוה\"ת שה\"ש ריש ע' תשסב</a>."]]],[2000460270,"בהם וכתיב ואתה מחיה את כולם לכן צריכים המקיף דלבונה זכה שנמשך להם החיות מ\"מ אינו נבלע בהם וזהו חולקא חדא כו'. וצ\"ל אם חלוקים הם בכוונתם, דבפי' ודאי חלוקים אבל אם הם חלוקים בכוונתם ג\"כ או לא.\n<b>וצ\"ל</b> תחילה מ\"ש אם יש עליו מלאך מליץ אחד מני אלף להגיד לאדם ישרו ויחננו ויאמר פדעהו מרדת שחת מצאתי כופר, ופירש\"י אם יש כו' ממגידי פשעו והוא יליץ ישרו, ויחננו המקום, פדעהו כאלו הי' כתי' באל\"ף, מצאתי כופר פדיון נפשו. ויש בזה הרבה דקדוקים, מהו המספר דאחד מה תופס מקום נגד תתקצ\"ט, וצ\"ל דהמספר הוא בכוונה. ועוד צ\"ל אם הוא ג\"כ ממגידי פשעו אלא מ\"מ הוא יליץ ישרו, או שמגידי פשעו הם תתקצ\"ט מ\"מ נק' אל\"ף והאחד מליץ ישרו, וה' רחום וחנון לכן ויחוננו. ועוד צ\"ל מ\"ש רש\"י המקום דוקא. עוד צ\"ל מה שכ' פדעהו בעי\"ן וצ\"ל כאילו הי' כ' באל\"ף, הי' ל\"ל באל\"ף. ועוד צ\"ל למה אמר זה אליהו בן ברכאל דוקא הלא הג' רעים היו זקנים ממנו. והנה צ\"ל תחילה הקושיא האל\"ף מהו המספר אחד דוקא והוא פדעהו מרדת שחת, וכ' בזהר ובספרים דשחת הוא עומק מיצוי הדין קשה<sup data-n=\"808\">3</sup>, ובהיכלות הוא היכל הב' דסט\"א, ובעומק יותר הוא דזלעו\"ז עשה אלקים כמו שיש זה בקדושה כמו\"כ יש זה בסט\"א והוא זעיר, והעיקר הוא הנוק' דזעיר, דבסט\"א היפך מבקדושה והוא הוד דנוק' דזעיר, והו\"ע הנחש ושחת ר\"ת חיוא תקיפא שלטא, ובכלל הוא עמקי הקליפות ואיך אמר פדעהו מעמקי הקליפות.\n<b>והענין</b> דהנה כ' בזהר שהוא להבדיל בין קודש לחול ובין טמא לטהור. והנה הבדלה מצינו כ\"פ בתורה, והראשון הוא מ\"ש במע\"ב ביום א' ויבדל בין האור ובין החושך והוא מקור לכל ההבדלות, וכתיב והבדילה הפרוכת לכם בין קודש ובין קדש הקדשים ואי' בגמ' י\"ג פרוכת היו במקדש ז' נגד ז' שערים כו', ועל לשון ההבדלה אמרז\"ל הפוחת לא יפחות מג' והמוסיף אל יוסיף מז' והוא מפני דמצינו ז' הבדלות בתורה.\n<b>והענין</b> דהנה כתיב אשר ברא אלקים לעשות לתקן, דלעשות הוא כמו ועשתה את צפרני' ותרגם ותתקן, דכל מה שנברא בשימ\"ב צריכים תיקון, כמ\"ש ואדם אין לעבוד את האדמה משמע שצריכים אדם שיעבוד את האדמה, וכתיב ויניחהו בג\"ע לעבדה ולשמרה לעבדה רמ\"ח מ\"ע ולשמרה שס\"ה מל\"ת והו\"ע עבודת הגן ג\"ן סדרים דאורייתא, וזהו\"ע העבודה שחסר דבר מ\"ה בהבריאה כדי שיהי' עבודה, ואי' (בספרים) שבזה יש כוונה עמוקה<sup data-n=\"809\">4</sup>, ולפ\"ז נראה שהכוונה כדי שיהי' באתעדל\"ת אתעדל\"ע, וצ\"ל מהו הכוונה עמוקה כ\"כ. הגם שזהו ג\"כ מדריגה",[["808","3","<b>וכ' בזהר ובספרים דשחת הוא עומק מיצוי הדין קשה</b>: ראה זח\"ב רסג ב ואילך. זח\"א קעד, ב. ס' קהלת יעקב ערך שחת. וראה לעיל במאמר ס\"ע ט."],["809","4","<b>ואי' (בספרים) שבזה יש כוונה עמוקה</b>: ראה סידור עם דא\"ח קמה, א: ותהי' הבריאה חסר דבר מה וצריך שיתקן שיושלם כו' והכוונה בזה עמוק מאד."]]],[2000460271,"גבוה דמקשינן מה שייך עבודה למעלה<sup data-n=\"810\">5</sup> דמצינו כמה פעמים ענין העבודה כמו ועבדתם את ה' אלקיכם, תחת אשר לא עבדת, ולעבדו בכל לבבכם ואמרז\"ל איזו היא עבודה שבלב זה תפילה, ואדם אין לעבוד, לעבדה ולשמרה, והלא אנת (ובפ\"א א\"ס) שלימותא דכולא ועבודה שייך כשחסר וכלום חסר, ואמרז\"ל מה איכפת לי' להקב\"ה אם שוחט מהעורף או שוחט מהצואר אלא לא נתנו המצות אלא לצרף בהם את הבריות, בריות קאי על נה\"ב, דנה\"א אינו צריך תיקון שהוא נאצל, הגם דכתיב בראתי אבל כתיב טהורה (הג\"ה, ר\"ל טהורה דשרשה מטהירו עילאה, ובראתי היינו שעובר דרך בריאה וכמ\"ש במ\"א<sup data-n=\"811\">6</sup> עכ\"ה), וא\"כ מה שייך עבודה למעלה. והענין דהנה כתיב הוי' אלקיכם אפי' בהד' ספרים (ובפ\"א דבס' דברים רובא דרובא כתיב הוי' אלקיכם, ואפי' בהד' ספרים שהם כמו שלישי המדבר מ\"מ כתיב הוי' אלקיכם), והיינו המקור דנש\"י וכאן שייך עבודה, דהנה אמרז\"ל גדולים מעשה צדיקים ממעשה שמים וארץ<sup data-n=\"812\">7</sup>, דמעשה שמים וארץ הם מאין ליש ומעשה צדיקים מיש לאין.\n<b>ולכן</b> הי' חסר דבר מה כדי שיהי' ביטל היש לאין, ואפ\"ל חסר דבר מ\"ה היינו הביטול, וצדיקים היינו שמקיימים תומ\"צ הם גורמים ביטל היש לאין, נמצא שהוא מדריגה גבוה, וזה שייך בבריאת האדם. ובזה יש מדריגות, דכתיב וייצר הוי' אלקים את האדם עפר מן האדמה ואמרז\"ל וייצר בתרין יודי\"ן, בתרין יצרין ביצ\"ט ויצה\"ר, וכתב הרמ\"ז דהיו\"ד הא' הוא יו\"ד דגושה והוא מוציא יו\"ד. והענין דאף דהיצה\"ר זקן מהיצ\"ט, מ\"מ העיקר היצ\"ט, דניתן כח להיצ\"ט שהיצה\"ר יהי' כפוף וכפות להשכלות הנה\"א, דיצ\"ט הוא הז\"ת והנה\"א הוא ההשכלה והנהגת המדות עפ\"י שכל, וזהו שהיצה\"ר יהי' כפות להשכלת נה\"א, וזהו שייך לבריאת האדם. אבל באמת יש בזה עומק גדול, דבאצי' יש ב' בחי' סוד שרש וסוד תוס', סוד שרש היינו אצי' הספי', וסוד תוס' היינו מה שתוספתו של הקב\"ה מרובה על העיקר, עיקר הוא שרש האצי' והתוס' מרובה על העיקר, והוא ע\"י העבודה, וא\"כ גם באצי' אינו שלימות וא\"כ בבריאה אפשר שיהי' חסרון. וענין מ\"ה הוא מ\"ש ראומה<sup data-n=\"813\">8</sup> שיראה הביטול, דבמ\"ה נכלל ביטל היש וביטל האמיתי, וראו מה גרוע יותר מחסר מה, דאם הוא חסר ע\"י עבודה יבוא לבחי' ביטל ויהי' כדבעי, אבל כשיש הביטל אך הוא ראו מה זה גרוע יותר.",[["810","5","<b>דמקשינן מה שייך עבודה למעלה</b>: ראה סה\"מ תקס\"ח ח\"א ע' תב. אוה\"ת משפטים ע' א'קצח. סה\"מ תרל\"ג ח\"ב ס\"ע תכט ואילך. וש\"נ."],["811","6","<b>ר\"ל טהורה דשרשה מטהירו עילאה. . שעובר דרך בריאה וכמ\"ש במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380277\" data-slug=\"likkutei-torah\" data-id=\"4001380277\">לקו\"ת בחוקותי מו, ד</a> ואילך. שם דרושים ליוהכ\"פ סט, א. שה\"ש ח, ג. טז, ד. ובכ\"מ."],["812","7","<b>גדולים מעשה צדיקים ממעשה שמים וארץ</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370295\" data-slug=\"torah-or\" data-id=\"3901370295\">תו\"א בשלח סו, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380393\" data-slug=\"likkutei-torah\" data-id=\"4001380393\">לקו\"ת נשא כא, ב</a>. סה\"מ תרכ\"ז ע' רנה. סה\"מ תרל\"ג ח\"א ע' רסח. ח\"ב ע' תל ואילך. וש\"נ."],["813","8","<b>וענין מ\"ה הוא מ\"ש ראומה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380260\" data-slug=\"likkutei-torah\" data-id=\"4001380260\">לקו\"ת בהר מג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380173\" data-slug=\"likkutei-torah\" data-id=\"4001380173\">תזריע כג, ב</a>. סה\"מ תרל\"ג ח\"ב ע' תיד. וש\"נ."]]],[2000460272,"<b>ועפ\"י</b> הקדמה זו יובן מ\"ש במדרש אם חביבה עליו המילה למה לא ניתנה לאדה\"ר. והנה עדיין אינו מובן השאלה, ומהתירוץ מובן, שא\"ל להוציאך חלק אי אפשר, אבל כל מה שנברא בשימ\"ב צריכים תיקון, החרדל צריכים לימתק, התורמסין צריכים לימתק, החיטים צריכים ליטחן אפי' אדם צריך תיקון, ומובן שהשאלה היא למה לא נברא מהול, ופי' המת\"כ מאחר שצריכים להסיר הערלה למה נברא כך וצריכים לחסר את הבריאה למה לא נברא בלא ערלה, וא\"ל שהכל צריך עשי' ותיקון, ופירש\"י אשר ברא אלקים לעשות שהכל צריך תיקון. ולפי הקדמה זו מובן ענין זה בכלל שהוא כדי שיהי' עבודה.\n<b>וכדי</b> שיובן הענין בפרטיות אינו מספיק וצ\"ל תחילה ענין ההבדלה דהנה והבדילה הפרוכת לכם בין הקודש ובין קדש הקדשים ששם צריכים ג\"כ הבדלה, דאי' בסש\"ב דבקה\"ק מאיר מהקדה\"ק דבריאה, ובהביאור לפ' אלו<sup data-n=\"814\">9</sup> (ובפ\"א הוא שער הת\"ת<sup data-n=\"815\">10</sup>) כתב בפרטיות שבו מתנוצץ הארה מקה\"ק דאצי' שבו שורה אוא\"ס, דאי' בע\"ח דשרש קדה\"ק גבוה מאד דכתיב וכיפר על הקדש דיש קדש הקדשים, וקדש, וכיפר על הקדש. והענין דהנה דאם לא הי' הפרסא המפסקת לא הי' יכול להיות [בריאה יש מאין] שיברא מלאך וריבוי הנבראי' ופרטיות הנבראים לכן צ\"ל פרסא, וכ\"כ בפרד\"ס בברייתות דשמעון הצדיק פרגוד והוא כסה\"כ ופי' הפרדס שהוא בריאה, והוא מפני שהפרסא הוא כדי שיהי' בריאה (כנ\"ל כדי שיהי' בריאה יש מאין) לכן מפרש שהוא בריאה. וזהו המחדש בכל יום תמיד מע\"ב, דמפני שהפרסא מפסקת ונעשה אור של תולדה, לכן נק' חידוש. ומ\"ש בכל יום מפני שהיום מאפיל ומאיר כמו שהי' בתחילת הבריאה שמויהי ערב נעשה ויהי בוקר, כמו\"כ כאן כשמאפיל תחילה אח\"כ מאיר האור של תולדה.\n<b>וזהו\"ע</b> ההבדלה דבין שבת לחול אומרים להבדיל בין קדש לחול משא\"כ בין שבת ליו\"ט אומרים בין קדש לקדש, דיו\"ט ג\"כ קדש וצריכים להמשיך קדש דמוחין דאבא, וזהו שאומרים ביו\"ט מקדש ישראל והזמנים דישראל אינון דקדשינהו לזמני' אבל שבת מקדשא וקיימא, ובחול אומרים להבדיל בין קדש לחול והוא הפרסא המפסקת בין [עשי' לק\"נ].\n<b>וזהו</b> האלף לך שלמה, ונפרש עתה להפי' דמק\"מ שהו\"ע הבירורים דק\"נ, דשלמה הוא שלום, לבד מה שהוא מלך שהשלום שלו הלא כתיב כי בימיו יהי' שלום, והוא שבירר ק\"נ, וזהו האלף לך שלמה שהוא לך, [ואפ\"ל] שלמה הוא ענין שלום בפמליא של מטה, והיינו שהארת כחות הנפש המאירים בנה\"ב<sup data-n=\"816\">11</sup> שאף הנה\"ב יהי'",[["814","9","<b>דאי' בסש\"ב דבקה\"ק מאיר. . והביאור לפ' אלו</b>: <a class=\"ft-cite\" href=\"#/read/tanya/3401310057\" data-slug=\"tanya\" data-id=\"3401310057\">תניא</a> פנ\"ב-נ\"ג. סידור עם דא\"ח צז, ג ואילך."],["815","10","<b>ובפ\"א הוא שער הת\"ת</b>: ובפעם א' (בעת אמירת כ\"ק אדמו\"ר מהר\"ש המאמר בפעם א', אמר אשר הביאור בסידור) הוא בשער התלמוד תורה."],["816","11","<b>שלום בפמליא של מטה. . כחות הנפש המאירים בנה\"ב</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370301\" data-slug=\"torah-or\" data-id=\"3901370301\">תו\"א יתרו סז, ב</a>. סה\"מ תרל\"ב ח\"א ע' פד. תרל\"ג ח\"א ע' נט. ח\"ב ע' ס."]]],[2000460273,"מרוצה ומוסכם על השכלות דנה\"א, וכמו\"כ אפ\"ל שלמה למטה שבירר ק\"נ וזהו האלף, וכמו שלמה לדידי' שכ' בגמ'.\n<b>וענין</b> אלף, דאלף הם אותיות אל\"ף, והנה ברה\"ע לא הי' באל\"ף ולכאורה והלא הוא ראשון לכל אתוון וגם הוא למעלה מהבי\"ת, ואי' בזהר הטעם שהאל\"ף הוא ארור ובי\"ת ברכה, ופי' רבינו ז\"ל אף דאל\"ף הוא בכתר ובי\"ת הוא בחכמה כמ\"ש בחכמה יבנה בית, יבנה בי\"ת, מ\"מ לא הי' ברה\"ע באל\"ף<sup data-n=\"817\">12</sup> מפני ששם כחשיכה כאורה, מה איכפת לי' להקב\"ה כו', שממית בידים תתפש, אם תגביה כנשר<sup data-n=\"818\">13</sup>, דרך הנשר בשמים, ומצד הרוממות יכולים לקבל גם סט\"א, לכן לא הי' ברה\"ע באל\"ף, אבל מ\"ת הי' באל\"ף דאחר שהי' ברה\"ע בבי\"ת אף שהי' מ\"ת באל\"ף יומשך למקום הראוי וכמו ונפלינו אני ועמך.\n<b>וזהו</b> האלף לך שלמה, דהאלף היינו מה שהם מקבלים מצד הרוממות לך כו', דשלמה אמר אף חכמתי עמדה לי, חכמתי שלמדתי באף עמדה לי, דכתיב אף עשיתיו הפסיק הענין דאינו דומה יצי' לעשי', ואף מרבה בחי' רביעית<sup data-n=\"819\">14</sup> שע\"י שמברר עשי' נמשך מבחי' שלמעלה מהג' עולמות, וכמ\"כ שלמה שבירר את העשי' נמשך לו מבחי' שלמעלה מהג' עולמות (מאצי'), וזהו לי דשלמה הוא ג' אלפים כמו ג' אלפים משל, והיו\"ד הוא עוד עשרה והיינו הבחי' רביעית, וזהו האלף לך שלמה<sup data-n=\"820\">15</sup> שע\"י הבירורים ממשיך הבחי' רביעית כו'.\n<b>הג\"ה</b>, ומ\"ש חולקא חדא אית להו מסט' דקדושא מסט' דשמאלא, סט' דשמאלא הוא גבורה, והבירורים הם מצד הגבורה כמ\"ש בפי' המלות (של אאזמו\"ר זצללה\"ה) בפי' הק\"ש אות ד', עכ\"ה).",[["817","12","<b>ופי' רבינו ז\"ל. . לא הי' ברה\"ע באל\"ף</b>: ראה סה\"מ תקס\"ח ח\"ב ע' תרסב ואילך. ביאוה\"ז להצ\"צ ע' תשיג ואילך. לעיל ע' מה. וש\"נ."],["818","13","<b>שממית בידים תתפש אם תגביה כנשר</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370121\" data-slug=\"torah-or\" data-id=\"3901370121\">תו\"א וישלח כו, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370159\" data-slug=\"torah-or\" data-id=\"3901370159\">מקץ לד, ג</a>. ובכ\"מ."],["819","14","<b>דכתיב אף עשיתיו הפסיק הענין. . מרבה בחי' רביעית</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380596\" data-slug=\"likkutei-torah\" data-id=\"4001380596\">לקו\"ת בלק סט, ג</a> ואילך."],["820","15","<b>האלף לך שלמה</b>: הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע מד\"ה זה הנדפס לעיל ע' טו. וראה בהמ\"מ בתחילת המאמר שם. מאמר זה הוא המשך למאמר שלפנ\"ז ד\"ה כרמי גו'."]]],[2000460274,"<h3>האלף לך שלמה</h3>\n<b>ש\"פ חיי.</b>\n<b>האלף</b> לך שלמה ומאתים לנוטרים את פריו, הנה נת\"ל דהאלף קאי על ע\"ס דנוגה ושלמה מברר אותם, וזהו אף חכמתי עמדה לי, חכמתי שלמדתי באף עמדה, אף עשיתיו, ושרש הנוגה מבחי' אלף, דכחשיכה כאורה, וצ\"ל מאחר שהבירורים הם בירורים גבוהים (כנ\"ל דשרשם מבחי' אף שהוא בחי' כתר) ולמה נק' חול, (הג\"ה, ואפ\"ל עוד דהלא נת\"ל בענין אף עשיתיו שהם נק' בירורים דעשי' לכן יש בו מעלה דאף עשיתיו, וכמשנת\"ל הלשון וכמו\"כ שלמה שבירר העשי', ועשי' הוא קודש וא\"כ למה נק' חול, עכ\"ה). והענין דהנה אי' באגה\"ק על מ\"ש ברע\"מ<sup data-n=\"821\">1</sup> דתושבע\"פ הוא אילנא דטוב ורע, ולכאו' איך שייך לקרותו בשם טוב ורע. והתירוץ דהנה מל' יורד לברר בירורים והמברר צריך להתלבש בלבוש המתברר, והמתברר הוא רע, לכן נק' ג\"כ רע ע\"ש המתברר. וכמו\"כ מצינו בלשון חולין, דמט\"ט הוא ו\"ק דיצי' נק' חולין שנעשה בטהרה, והוא ענין משנה שיתא סדרי משנה, אסור מותר, טמא טהור כו', והם המבררים<sup data-n=\"822\">2</sup> [ק\"נ] ולמה נק' חולין, אלא מפני שמבררים ק\"נ לכן נק' חולין ע\"ש המתברר ונעשה בטהרה מפני שהם מבררים (הג\"ה, ואפ\"ל דהנה משנה הוא תושבע\"פ, והוא מל' דאצי' ונק' אילנא דטוב ורע, אך כשמתלבש ביצי' לברר בירורי הנוגה שמתחילין ביצי' כמ\"ש באגה\"ק הנ\"ל ששם מתחיל הדעת דנוגה, והתלבשותו הוא במל' דיצי', וזהו כמו מט\"ט שהוא ו\"ק דיצי' שהוא בחי' משנה תושבע\"פ שהוא בחי' מל' נק' חולין, כמו\"כ אח\"כ כשמתלבש משנה תושבע\"פ עוד בבחי' מל' דיצי' לברר בירורים דנוגה נק' ג\"כ חולין. הגם שבשרשו נק' אילנא דטוב ורע, אך כשמתלבש אח\"כ ביצי' נק' חולין. ולא ידעתי ההפרש בין רע לחולין, עכ\"ה). (הג\"ה, ולפ\"ז מובן ג\"כ הקושי' הב' דאף שמברר עשי' אך עיקר המתברר הוא קליפת נוגה והמברר צריך להתלבש בלבושי המתברר וכמ\"ש באגה\"ק הנ\"ל וז\"ל והנה העליונים אין בהם כח להעלות ולברר מהשבירה שבק\"נ אלא התחתונים לבד לפי שהם מלובשים בגוף חומרי משכא דחויא מק\"נ כו' עכ\"ל, ולכן נק' חולין, עכ\"ה).\n<b>והנה</b> י\"א בגמ' דשלמה זה הוא קודש, וחול הוא מ\"ש הנה מטתו שלשלמה ששם הי' צריך שומרים, וא\"כ אצ\"ל דשלום היינו שלום בפמליא של מטה אלא שלום בפמליא של מעלה, ובעבודה הוא שיומשך המשכת אוא\"ס בנה\"א שיתדבק ויתקשר באלקות, דשלום הוא התקשרות (הג\"ה. שלום הוא יסוד כמ\"ש במאו\"א ע' שי\"ן, וידוע דיסוד הוא התקשרות כמ\"ש כי כל בשמים וארץ דאחיד בשמיא וארעא,",[["821","1","<b>אי' באגה\"ק על מ\"ש ברע\"מ</b>: סכ\"ו (קמב, א ואילך). וראה גם ביאוה\"ז לאדהאמ\"צ ב, ג ואילך."],["822","2","<b>והם המבררים </b>[ק\"נ]: כ\"ה בגוכי\"ק בתוך מוסגרים. [וניכר כי כ\"ק אדמו\"ר מהר\"ש חזר על כל מאמר פעם שני', ותיבות אלו שבתוך מוסגר הוא אמרם רק בפעם אחת]. ועד\"ז פעמים רבות בהנחות אלו."]]],[2000460275,"שמים ז\"א וארץ בחי' מל', ויסוד הוא המקשר אותם דדרך בו יורד ההשפעה מז\"א למל', וידוע דכשאחד משפיע לחבירו ע\"י ההשפעה נתקרב המקבל להמשפיע שע\"י שיורד ההשפעה מז\"א למל' עי\"ז מתקרב מל' לז\"א, וכמו\"כ כאן ע\"י שיורד המשכה מאוא\"ס לנה\"א עי\"ז נדבק ונתקשר הנה\"א באלקות עכ\"ה).\n<b>והענין</b> דהנה בפסוק זה רבו הפי', הת\"י מפרש אלף קאי על י' שבטים שנפרדו משלמה בנבואת אחי' השילוני שא' שכל ימי שלמה יהיו הי' שבטים ואחר מות שלמה יפרדו ממנו, וכן הי', ונשאר יהודה, ובנימין נכלל ג\"כ כו', וזהו מלכי יהודה. והענין דהנה י\"ב שבטים הם י\"ב בקר דבריאה<sup data-n=\"823\">3</sup> וכתי' ששם עלו שבטים שבטי י\"ה, שנתעלו שיש להם שרש באצי' (ובפ\"א ששרשם מי\"ב גבולי האלכסונים דאצי'<sup data-n=\"824\">4</sup>) (הג\"ה, דכאן מדבר מענין שלמה שהוא מל' דאצי' וכל כונתו כאן בעולם האצי' כמשית\"ל, ולכאו' והלא י\"ב שבטים הם י\"ב בקר דבריאה, לכן אומר שיש להם שרש באצי', עכ\"ה).\n<b>והנה</b> על לע\"ל כתיב ונקבצו<sup data-n=\"825\">5</sup> יהודה וישראל ושמו להם ראש אחד, הרי יהודה וישראל מדריגות מחולקות מ\"מ יהי' להם ראש אחד. והענין דהנה יהודה הוא מ\"ש הפעם אודה<sup data-n=\"826\">6</sup> הוי', שהוא בחי' הודאה, הגם שאינו משיג מ\"מ הוא מודה וכמ\"ש מודים אנחנו לך, והו\"ע השתחואה, ואף דהשתחואה הוא מדריגה גבוה (הג\"ה דהשתחואה הוא ביטול מכל וכל עכ\"ה) מ\"מ הוא רק יחו\"ת ד\"ת (הג\"ה, י\"ל דהשתחוואה זו הוא כמו וצבא השמים לך משתחוים שהו\"ע יחו\"ת שמרכין ראשו עכ\"ה), וישראל הוא ישר אל, לי ראש, שהוא בחי' ראש ומוחין והוא בחי' יחו\"ע ד\"ע. והנה כי לא מחשבותי מחשבותיכם, דאל דעות הוי', ד\"ע וד\"ת. ד\"ע הוא כשכולא קמי' כלא חשיב וכל מה שלמטה מטה הוא אין שאינו נחשב לכלום, וד\"ת הוא שכל מה שלמטה מטה הוא יש ולמעלה אין, וצ\"ל חיבור יחו\"ת ויחו\"ע, דיחו\"ת יתעלה ויהי' ג\"כ כמו יחו\"ע. וזהו שכ' בזהר למהוי אחד באחד, דעכשיו עלמא דאתכסייא עולם בפ\"ע ועלמא דאתגלייא בפ\"ע.\n<b>וזהו</b> ביום ההוא יהי' ואי' בכהאריז\"ל<sup data-n=\"827\">7</sup> שיהי' ב\"פ י\"ה דעכשיו י\"ה ו\"ה, ועל לשון החסידות ו\"ה הם דיבור ומדות וי\"ה הם מוחין, ועכשיו הוא ו\"ה (בפ\"א, והדיבור מקבל מהקול) ה' מקבל מו', דאף דו' יש בראשו יו\"ד, אך נמשך אח\"כ קו",[["823","3","<b>והענין דהנה י\"ב שבטים הם י\"ב בקר דבריאה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370133\" data-slug=\"torah-or\" data-id=\"3901370133\">תו\"א וישב כח, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370208\" data-slug=\"torah-or\" data-id=\"3901370208\">ויחי מה, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380070\" data-slug=\"likkutei-torah\" data-id=\"4001380070\">לקו\"ת פקודי ז, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380700\" data-slug=\"likkutei-torah\" data-id=\"4001380700\">מסעי צד, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380826\" data-slug=\"likkutei-torah\" data-id=\"4001380826\">ד. פ' ראה כז, ג</a>."],["824","4","<b>ובפ\"א ששרשם מי\"ב גבולי האלכסונים דאצי'</b>: ר\"ל שבעת אמירת כ\"ק אדמו\"ר מהר\"ש המאמר בפעם א' הוא הוסיף תיבות אלו [ועד\"ז נמצא כמה פעמים בהנחות אלו]."],["825","5","<b>והנה על לע\"ל כתיב ונקבצו</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380334\" data-slug=\"likkutei-torah\" data-id=\"4001380334\">לקו\"ת במדבר ו, ג</a> ואילך."],["826","6","<b>דהנה יהודה הוא מ\"ש הפעם אודה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370205\" data-slug=\"torah-or\" data-id=\"3901370205\">תו\"א ויחי מה, א</a> ואילך."],["827","7","<b>וזהו ביום ההוא יהי' ואי' בכהאריז\"ל</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380339\" data-slug=\"likkutei-torah\" data-id=\"4001380339\">לקו\"ת במדבר שם ז, ד</a>."]]],[2000460276,"דק עד שנעשה קלישות הקו<sup data-n=\"828\">8</sup> (ובפ\"א, ואח\"כ נעשה ממנו הה') וכמו שאנו רואין כשהמדה בתוקף אינו יכול לדבר<sup data-n=\"829\">9</sup> עד שימעט המדה, וזהו גוף המדה, ומכ\"ש המוחין שבמדה שאפי' גוף המדה צריך לימעט, משא\"כ י\"ה מהיו\"ד נעשה הה' (ובפ\"א, ונחשב לדבר אחד), לכן אי' בספרים שבתפילין צריכין לעשות הה' ראשונה משם הוי' תחילה יו\"ד<sup data-n=\"830\">10</sup> ואח\"כ עושין ממנו הה'.\n<b>וזהו</b> ונקבצו יהודה וישראל, יהודה הוא בחי' ו\"ה, דאיהי בהוד דמל' מקבל כו', וישראל הוא בחי' ז\"א מהחזה (ובפ\"א מחצי) ולמעלה ששם מאיר הארת המוחין והוא באופן כמו מוחין, ועל לע\"ל כתיב והי' אור הלבנה כאור החמה שגם הלבנה יהי' כמו בחי' שמש (הג\"ה, שמש הוא בחי' ת\"ת שהוא מחזה ולמעלה לכן לע\"ל שיהי' אור הלבנה כאור החמה היינו שמל' יתעלה ויהי' כמו תפארת אזי עכ\"ה), ושמו להם ראש אחד, דעכשיו ת\"ת דאימא נעשה כתר לז\"א ולע\"ל יהי' כתר אחד לשניהם.\n<b>ומ\"ש</b> רא\"ש אחד הוא דוד<sup data-n=\"831\">11</sup> כמ\"ש קח לך עץ אחד וכתוב עליו ליהודה ולישראל חבריו ולקח עץ אחד וכתוב עליו ליוסף עץ אפרים כו' ועבדי דוד מלך עליהם, וכתיב ודוד עבדי נשיא להם, דעכשיו יוסף למעלה מבנימין דיוסף הוא צדיק עליון והוא מחבר עלמדאת\"כ ועלמדאת\"ג, שכל ההשפעות הם ע\"י יוסף וכמ\"ש אלה תולדות יעקב יוסף, שהגילוים דיעקב הם ע\"י יוסף (הג\"ה. ע' מזה באריכות בבה\"ז בפ' ויחי<sup data-n=\"832\">12</sup> על מאה\"ז שופרא דיוסף כעין שופרא דרחל כו' עכ\"ה) שדרך בו נמשך מעלמא עילאה לעלמא תתאה, הרי יוסף למעלה מבנימין, וראי' מזה גופא דאצל ירבעם שהוא משבט אפרים הי' י' שבטים, הרי הוא (מעלת) עשר, וכאן לא הי' רק ב' שבטים. אך לע\"ל כתיב א\"ח עט\"ב שדוד יתעלה ויהי' הוא הראש (בפ\"א וזהו כסא דמלכא דמשיחא רך\"א לוגין גי' ארך). וזהו\"ע שלמה, דשלמה ודוד הם אחד, מלך שהשלום שלו מל' שרשה מכתר ונמשך לה משרשה. וזהו האלף לך שלמה שמחזירים לו האלף.\n<b>ורש\"י</b> פי' האלף היינו שמחזירים לו הקרן, ומאתים היינו החומש שמוסיפין כדין מועל בקדשים. דבזה יש פלוגתא בגמ' ר' יאשיה אומר הוא וחומשו חמשה ור' יונתן אומר חומש מהקרן, ואף שאנו פוסקי' כר' יאשיה אך רש\"י מפרש כמ\"ד חומש מהקרן, ואנו נדבר כמו שפוסקין הוא וחומשו חמשה. (ובפ\"א, והענין דהנה",[["828","8","<b>אך נמשך אח\"כ קו דק עד שנעשה קלישות הקו</b>: ראה גם תו\"א טו, ד."],["829","9","<b>וכמו שאנו רואין כשהמדה בתוקף אינו יכול לדבר</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380936\" data-slug=\"likkutei-torah\" data-id=\"4001380936\">לקו\"ת</a> דרושים לר\"ה נד, ב-ג. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080137\" data-slug=\"or-hatorah-hb\" data-id=\"8160080137\">אוה\"ת ויקרא (כרך א) ע' קלז</a>. ובכ\"מ."],["830","10","<b>לכן אי' בספרים שבתפילין צריכין לעשות הה' ראשונה משם הוי' תחילה יו\"ד</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380705\" data-slug=\"likkutei-torah\" data-id=\"4001380705\">לקו\"ת במדבר שם ז, ד</a>. מסעי צה, ב ובהמ\"מ שם."],["831","11","<b>ומ\"ש ראש אחד הוא דוד</b>: ראה בכ\"ז גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370199\" data-slug=\"torah-or\" data-id=\"3901370199\">תו\"א ויגש מד, א</a> ואילך."],["832","12","<b>ע' מזה באריכות בבה\"ז בפ' ויחי</b>: ביאוה\"ז לאדהאמ\"צ כז, ג ואילך."]]],[2000460277,"תורה נתלבשה<sup data-n=\"833\">13</sup> בדברים גשמיים ציצית בצמר גשמי תפלין בקלף גשמי והכל נתלבש בדברים גשמיים. וי\"א שזה קאי על נבוכדנצר שזהו ג\"ק הטמאות לגמרי (ר\"ל שעי\"ז מבררים ג' קליפות הטמאות לגמרי, וצ\"ע דמה שייך בירור ג\"ק למ\"ע וכמ\"ש אח\"ז) וא\"כ הבירור הוא ע\"י מל\"ת. אך העיקר שקאי על ק\"נ שהוא מ\"ש ואת החזיר כי מפריס פרסה הוא, מ\"מ צריכים [מל\"ת] ג\"כ מפני שהוא דקות הרע)<sup data-n=\"834\">14</sup>.\n<b>ולהבין</b> זה הנה כתיב חדלו לכם<sup data-n=\"835\">15</sup> מן האדם אשר נשמה באפו ואי' בזהר שע\"י כעס מסתלקת הנשמה, דכל הכועס נשמתו מסתלקת ממנו [והיינו שמסתלק ממנו נר\"ן], ואי תימא ריתחא דרבנן, אורייתא הוא דקא מרתחא בי', והנה במד\"ר אי' ה' שמות נקראו לה נר\"ן ח\"י, אך בזהר לא חשיב רק ד' נר\"ן ונשמתא לנשמתא, וא\"כ שגם חכ' (ובפ\"א, חי') נכלל בזה כמ\"ש והחכמה תחי'. ג\"כ שם שהוא בחי' קדש, דיש ד' מדריגות ממלכת כהנים, וגוי קדוש, ועם קדוש, ואנשי קדש (ובפ\"א ובמק\"מ מפרש כל הכועס שכינה אינה חשובה כנגדו ומפרש שכינה הוא שכינתא עילאה בינה) (הג\"ה. ע' במק\"מ דקפ\"ב ע\"א בפי' הרמ\"ז טעם למה נשמתו מסתלקת ממנו, וגם טעם אומרו באפו ע\"ש, עכ\"ה).\n<b>והענין</b> דהנה בנשמות יש ב' מדריגות יעקב וישראל, יעקב הוא יו\"ד עקב שהיו\"ד יורד בבחי' עקביים לברר בירורים [יעקב] הוא ל' עקוב הלב מכל ואנוש הוא, והיינו לשון חלישות, דבאדם יש ד' מדריגות אדם איש גבר אנוש, ופי' אנוש לשון חלישות והיינו שאינו יכול לצאת ממאסר הגוף, דכשיתבונן במ\"ש בורא קדושים ישתבח שמך<sup data-n=\"836\">16</sup> שאפי' קדושים שהוא מקור נשמות ומלאכים (הג\"ה. בת\"א פ' יתרו ד\"ה בחודש השלישי<sup data-n=\"837\">17</sup> כ' קדושים שהם נשמות ומלאכים, ואפ\"ל קדושים הוא בחי' חכ' שהוא מקור הנשמות ומלאכים, דההפרש בין נשמות ומלאכים הוא דמלאכים הם זיווג נשיקין והיינו שאינו השפעה גשמיות וכמו השפעת הרב לתלמיד, משא\"כ נשמות הם ע\"י יסוד שנמשך בגשמיות, אך מ\"מ ההמשכה היא מבחי' מוחין וכמ\"ש באריכות בד\"ה להבין ענין מצות פו\"ר<sup data-n=\"838\">18</sup>, וצ\"ע מ\"ש בתו\"א קדושים שהם נשמות ומלאכים, דנשמות הם נמשכים מבחי' יסוד טפה גשמיות רק שרשם מחכמה כנ\"ל וגם מלאכים רק שרשם מחכמה, לכן אומר כאן שהוא מקור כו', עכ\"ה), הוא רק בחי' שמך שהוא שם והארה בעלמא. וזהו אני הוי' לא שניתי שלא יש שום שינוי בין קודם הבריאה לאחר הבריאה, אתה הוא קודם שנבה\"ע ואתה הוא לאחר שנבה\"ע, מפני שהוא רק שם והארה בעלמא שאינו נוגע לעצמיות, וא\"כ צריכים לחפוץ",[["833","13","<b>ובפ\"א </b>[ ובפעם א' אמר כ\"ק מהר\"ש]<b>, והענין דהנה תורה נתלבשה</b>: תוכן המקביל לפיסקא זו נמצא לעיל ע' יז, בשולי העמוד."],["834","14","<b>מ\"מ צריכים </b>[מל\"ת]<b> ג\"כ מפני שהוא דקות הרע</b>: ראה לעיל ס\"ע יז שם בשם רבינו הזקן."],["835","15","<b>ולהבין זה הנה כתיב חדלו לכם</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380642\" data-slug=\"likkutei-torah\" data-id=\"4001380642\">לקו\"ת פינחס פ, ג</a> ואילך."],["836","16","<b>בורא קדושים ישתבח שמך</b>: ראה לעיל במאמר ע' יח שמביא מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380253\" data-slug=\"likkutei-torah\" data-id=\"4001380253\">לקו\"ת בהר מא, ב</a> ואילך."],["837","17","<b>ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370300\" data-slug=\"torah-or\" data-id=\"3901370300\">תו\"א</a> פ' יתרו ד\"ה בחודש השלישי</b>: סז, א."],["838","18","<b>וכמ\"ש באריכות בד\"ה לה\"ע מצות פו\"ר</b>: ראה דרמ\"צ מצות פו\"ר פ\"ב (ג, א ואילך). והוא מיוסד על ד\"ה לה\"ע זווג הנשמות, בס' מאמרי אדה\"ז ענינים ע' קנא ואילך."]]],[2000460278,"באוא\"ס הסוכ\"ע. וזהו מי לי בשמים ועמך לא חפצתי בארץ, שמים וארץ הם געה\"ע וגעה\"ת, לא חפצתי ששניהם הם התחלקות מדריגות בבחי' ממכ\"ע כ\"א יחפוץ באוא\"ס הסוכ\"ע.\n<b>וזהו</b> אני ה' לא שניתי ואתם בני יעקב לא כליתם<sup data-n=\"839\">19</sup>, שהנביא מתמה שמהתבוננות זו צריך שיהי' לו כליון ותשוקה לאוא\"ס הסוכ\"ע, ואתם בני יעקב לא כליתם. אך הענין הוא מפני שכ' כאן בני יעקב, [דיעקב] היינו מ\"ש עון עקבי יסובני שעבירות שאדם דש בעקביו ואינו חש לעבור עליהם, אך הנה כתיב הוי מושכי עון בחבלי השוא כעבותות עגלה חטאה, אך אינו צריכים לזה דמקיבוץ חבלים דקים נעשה חבל עב, דהנה כתיב עונותיכם היו מבדילים ביניכם ובין אלקיכם, שנעשה מסך מבדיל מחיצה של ברזל, ואין פי' חטא ועון, אלא ע\"י [איזה חסרון] נעשה מסך מבדיל. והעצה לזה הוא תורה, דתורה נק' עוז שנותנת כח לנה\"א, ונק' תושי' שמתשת כחו של נה\"ב, וגם מתשת כח הגוף וכמו ריש לקיש כשקיבל עליו תורה לא הי' יכול לעבור הנהר, ועוז שנותנת כח לנה\"א שיברר ויהפוך הנה\"ב. דהנה שרש הנה\"ב מק\"ך צירופי אלקים, וישראל הוא כי שרית עם אלקים, דלכן קרא שמו ישראל שהוא ע\"ש כי שרית כו'.\n<b>אך</b> כל אוכליו יאשמו<sup data-n=\"840\">20</sup> (ובפ\"א, אך כשטורף נפשו באפו כל אוכליו יאשמו), אוכליו פי' שאוכל (בפ\"א, האדם) ישראל שלו, דכמו שכח האכילה נבלע בפנימיות אבריו, כמו שמצינו בהושע פסוק על ישראל שג\"כ נבלע בהם<sup data-n=\"841\">21</sup>, ועי\"ז צריכים אשם שהוא חלב ודם. דהנה כתיב וישמן ישרון ויבעט שמנת עבית כשית, כשית הוא בשי\"ן שמאל והוא ל' כיסוי שמכסה על [הנה\"א וע\"ז צריכים אשם] שאין העיקר סגופים ותעניתים אלא מרירות על הריחוק, [והו\"ע] התעוררות רחמים שמעורר ר\"ר על נפשו דנשמה היא חלק אלוקה ממעל וירדה בגוף ונה\"ב, [וזהו] כשית אף שהוא בשי\"ן שמאל מ\"מ הוא בשי\"ן. והוא משארז\"ל אין קוראין אבות אלא ג', דהנה חלב ודם הם חו\"ג שהו\"ע אברהם ויצחק, ויעקב הוא התעוררות רחמים [ועי\"ז יהי' ואנשי קודש].\n<b>אך</b> זהו הקרן וצריכים להוסיף חומש, והענין דהנה כתיב ומספר את רובע ישראל<sup data-n=\"842\">22</sup> דהנה כתיב ולכבודי בראתיו יצרתיו אף עשיתיו והם מחדו\"מ, בראתיו עולם המח', יצרתיו עולם הדיבור, עשיתיו הוא עשי', ואף מרבה בחי' רביעית היינו יו\"ד וקוש\"י, והו\"ע רצה\"ע שבפנימיות התורה דאורייתא מחכמה נפקת ויש בה בחי'",[["839","19","<b>וזהו אני ה' לא שניתי ואתם בני יעקב לא כליתם</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370300\" data-slug=\"torah-or\" data-id=\"3901370300\">תו\"א שם סז, א</a>. סה\"מ תרל\"ג ח\"א ע' רצה."],["840","20","<b>אך כל אוכליו יאשמו</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380643\" data-slug=\"likkutei-torah\" data-id=\"4001380643\">לקו\"ת פינחס פ, ד</a> ואילך."],["841","21","<b>כמו שמצינו בהושע פסוק על ישראל שג\"כ נבלע בהם</b>: בהושע ח, ח: נבלע ישראל גו'."],["842","22","<b>והענין דכתיב ומספר את רובע ישראל</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380593\" data-slug=\"likkutei-torah\" data-id=\"4001380593\">לקו\"ת בלק סח, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380596\" data-slug=\"likkutei-torah\" data-id=\"4001380596\">סט, ג</a> ואילך."]]],[2000460279,"רצה\"ע וזהו מעלות הצדיקים. אך יש עוד מדריגה חמשית והוא בחי' רעדכ\"ר (הוא בחי' א\"ק כמ\"ש בד\"ה להבין מ\"ש בע\"ח בענין ג' מיני אדם<sup data-n=\"843\">23</sup>) וזהו מעלות הבע\"ת דאי' בזהר זכאי אינון מרא דתיובתא דמשכין לי' בחילא יתיר, שע\"י תשובה מעומקא דליבא, ממעמקים קראתיך, עי\"ז ממשיכים מבחי' זו. וזהו\"ע החומש שהוא בחי' רעדכ\"ר כו'. וזהו\"ע יוהכ\"פ שיש בו חמש תפילות וה' עינוים, לכן אז וכפר על הקדש, דהכה\"ג נכנס לפני ולפנים, דבשאר ימות השנה כתיב והבדילה הפרוכת לכם שיש פרסה המפסקת, אך ביוהכ\"פ לא יש הפרסא דהכה\"ג נכנס לפני ולפנים, לכן אז וכפר על הקדש.",[["843","23","<b>כמ\"ש בד\"ה להבין מ\"ש בע\"ח בענין ג' מיני אדם</b>: אוה\"ת על מארז\"ל וענינים ע' עז ואילך."]]],[2000460280,"<h3>ויתן לך האלקים</h3>\n<b>ש\"פ תולדות ל\"ט לפ\"ק.</b>\n<b>ויתן</b> לך<sup data-n=\"844\">1</sup> האלקים מטל השמים ומשמני הארץ ורוב דגן ותירוש, ואי' במדרש מטל השמים זה מקרא, ומשמני הארץ זה משנה, ורוב דגן ותירוש הלכות ואגדות. והנה יש כאן יו\"ד ברכות כנגד עשרה מאמרות לכן א' ויתן לך האלקים, דבכ\"מ בברכה כתיב הוי' כמ\"ש יברכך הוי' מציון, וכתיב יברכך ה' גו' וישמרך, וכאן כתיב אלקים, דבמע\"ב כתיב בראשית ברא אלקים, ל\"ב פעמים אלקים נז' במע\"ב, לכן אומר כאן ג\"כ אלקים, וכמו שבמע\"ב כתיב אח\"כ ביום עשות הוי' אלקים ארץ ושמים הרי כתיב גם ש' הוי', והוי' קודם לאלקים, כמו\"כ כאן כתיב כריח השדה אשר ברכו הוי' ויתן לך האלקים שהוא ג\"כ הוי' אלקים. וצ\"ל מהו\"ע שרצה יצחק לברך את עשו שהוא דימה שהוא עשו ורצה לברך אותו.\n<b>והענין</b> דהנה איך הי' נחשב עשו אצל יצחק<sup data-n=\"845\">2</sup>, יש בזה מדרשות חלוקות, דע\"פ כי ציד בפיו אי' שצד את יצחק ששאל איך מעשרין את המלח איך מעשרין את התבן וחשב שהוא מדקדק במצות, וע\"פ גשה ואמושך כו' פירש\"י אמר אין זה עשו שאין ש\"ש שגור בפיו. ואיך ניחא ב' המדרשות. והענין דהנה אי' בזהר רישא דעשו בעטפי דיצחק, דיצחק הוא מעלת הזהב על הכסף, דאברהם הוא מדת החסד נכסף נכספת אל בית אביך גוון לבן וזהו אברהם אוהבי, ויצחק כמעלת הזהב כו' גבו' קדושות והו\"ע תגבורת (הג\"ה יצחק הוא זהב שהם גבורות ומעלת הזהב כו' היינו שהוא תגבורת עכ\"ה), ועשו הוא סוספיתא דדהבא הוא סיגי הגבו'.",[["844","1","<b>ויתן לך</b>: הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע מד\"ה ראה ריח בני, הנדפס לעיל ע' כו. וראה במ\"מ בתחילת המאמר שם."],["845","2","<b>והענין דהנה איך הי' עשו אצל יצחק</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370094\" data-slug=\"torah-or\" data-id=\"3901370094\">תו\"א תולדות כ, ב</a> ואילך.\nומחצית השקל־ זהו קיצור לשון ור\"ל מכיון שעשרים גרה השקל הלא מחצית השקל הוא במספר עשרה."]]],[2000460281,"<b>וענין</b> רישא דעשו, הנה כתיב ואת המשכן תעשה עשר יריעות, דעצם המשכן הי' עשר יריעות, אך חיפויו היו של יריעות עזים והיו י\"א יריעות, וכן קטורת שהוא מדריגה גבוה הי' י\"א סממני הקטורת וכדאי' בגמ' ואחד עשר סממנים היו בה, והם כנגד י\"א כתרין דמסאבותא, וצ\"ל דבכ\"מ מצינו מספר עשרה כדאי' בתק\"ז אנת הוא דאפיקת עשר תיקונין וקרינן לון עשר ספירן, ובס\"י אי' ע\"ס בלי מה עשר ולא תשע עשר ולא אחד עשר, ובתורה מצינו ג\"כ מספר עשר, עשה\"ד, ועשרה מאמרות, עשרה עשרה הכף בשקל הקדש, עה\"ד מכוון כנגד ע\"מ, הרי מספר עשר, וכמו\"כ בשקל הקודש כתיב עשרים גרה השקל ומחצית השקל, וכאן מספר י\"א.\n<b>והענין</b> דהנה אנת הוא חד<sup data-n=\"846\">3</sup> ולא בחושבן, דחושבן היינו כמו א' לגבי אלף, כמו\"כ אלף לגבי אלפי אלפים, וא\"כ גם א' יש לו ערך נגד אלפי אלפים שהוא חלק א' מאלפי אלפים וזהו חושבן, אבל אנת הוא חד ולא בחושבן שאינו בערך חושבן. ואח\"כ אנת הוא דאפיקת עשר תיקונין וקרינן לון עשר ספירן, ואי' בזהר והובא בעה\"ק הוא אינון ואינון הוא, הוא אלקות ואינון ע\"ס, ובאצי' הוא אינון ואינון הוא, וצ\"ל איך מאוא\"ס אחד ויחיד יתהוו נבראים בע\"ג. והענין דהנה כדי שמאוא\"ס אחד [ויחיד] ובל' החסידות הוא א\"ס הבלתי בעל גבול יתהווה נבראים בע\"ג, נתצמצם עד שיוכל להיות ממנו מקור הגבול, דאנת הוא שלימותא דכולא וכשם שיש לו כח בבע\"ג כמו\"כ יש לו כח בגבול שאם תאמר שיש לו כח בבע\"ג ואין לו כח בגבול אתה מחסר שלימותו, וכח הגבול הם ע\"ס דאצי' שהוא מקור שנתהווה אח\"כ נבראים בע\"ג (ובפ\"א ותכלית), והוא כח הא\"ס, כן מפרש העה\"ק את הזהר, ובזהר אי' בכלל שהו\"ע רזא דשמא קדישא והוא מדריגה היותר נעלה, דעד שלא נבה\"ע הי' הוא ושמו בלבד, שמו בגי' רצון, דכשעלה ברצונו שם יש ג\"כ כח לגבול, ושם הם רק ז' שמות שאינן נמחקים ואח\"כ נעשה מהם יו\"ד שמות [והו\"ע ציור אדם]<sup data-n=\"847\">4</sup> והו\"ע ג' מוחין וז' מדות וכמ\"ש על דמות הכסא דמות כמראה אדם עליו מלמעלה, והלא אין לו גוף ודמות הגוף, אלא הו\"ע ג' מוחין וז' מדות.\n<b>והנה</b> את זלעו\"ז עשה אלקים, וכמו שיש מדות אהוי\"ר כו' בקדושה כמו\"כ יש בלעו\"ז, דכתיב ולא תתורו אחרי לבבכם ואחרי עיניכם אשר אתם זונים אחריהם שהם מדות שבלב שזונים אחריהם, בל\"א מי וערט „<sup data-n=\"848\">5</sup>, והם ז' מדות רעות.",[["846","3","<b>והענין דהנה אנת הוא חד</b>: ראה גם תו\"א יג, ג ואילך."],["847","4","<b>והו\"ע ציור אדם]</b>: כל הקטעים הבאים כאן בתוך מוסגרים, כן הוא בגוכי\"ק. ובד\"כ הוא מה שאמר כ\"ק אדמו\"ר בעת חזרת המאמר בפעם א'.\nבצידי הגליון כאן נרשם בגוכי\"ק: אפ\"ל שצ\"ל קודם הזהר רזא כו'. [לעיל הובא הזוהר ”הוא אינון ואינו הוא\", והוא בזח\"ג ע, א ושם ליתא לשון רזא כו'. ואולי רשום כאן ”הוא\" ולא רזא]."],["848","5","<b>מי ווערט א</b>: תיבה אחת אחרי זה, אינה ברורה בגוכי\"ק."]]],[2000460282,"<b>וכמו\"כ</b> חכמה יש בלעו\"ז וכמ\"ש חכמים המה להרע, שהוא חכמה מ\"מ הוא רע. ואפי' עונג יש ג\"כ בלעו\"ז וזהו הלאו דחלב, דההפרש בין חלב לשומן, דשמנונית הוא מתענוגים, וחלב הוא מתענוג מדברים אסורים, לכן הוא לאו שיש בו כרת דהוא היפך אתוון כתר שהוא רצה\"ע שהוא עונג (בכלל) (ובפ\"א כמו שנגע היפך אתוון עונג כמו\"כ כרת היפך אתוון כתר). וזהו שא\"ל משמני הארץ ולא כל שמני הארץ, דשומן הוא שמנונית מתענוג דדברים המותרים, דיש אכילה כמו סעודה של שבת שהוא [עונג] אז תתענג על הוי', וקראת לשבת עונג, וחולין שנעשו על טה\"ק אפשר להפוך דבשבת יתעלו ויהיו [בחי'] אז תתענג על הוי', וכמו ר\"י בן גודגדא שהי' אוכל על טה\"ק כל ימיו, ויש בזהר כמה דרושים ע\"פ אלו.\n<b>אך</b> בקדושה הם ע\"ס ובלעו\"ז י\"א<sup data-n=\"849\">6</sup> כתרין דמסאבותא. והענין דהנה בקדושה כתי' וצבא השמים לך משתחוים, דכשנמשך להם החיות גורם בהם ביטול [דמרגישים החיות] (ובפ\"א, זיי דער הערין דעם כח הא\"ס), אך בסט\"א החיות נבלע בהם ואינו נראה החיות, רק נראה מי שנבלע בתוכו אבל דבר הנבלע אינו נראה, לכן מגביהים א\"ע בחוצפה וגסות כמ\"ש אם תגביהי כנשר, דרך הנשר בשמים, לקבל ממדריגה גבוה. אך מאין נמשך להם החיות הוא ע\"י המקיף דלבונה זכה שהוא מקדושה, אך בדרך מקיף נמשך חיות גם לסט\"א לכן אפשר להגביה בחוצפה וגסות, וזהו לבונה זכ\"ה שרשו ז\"ך הם ך\"ז אותיות<sup data-n=\"850\">7</sup> שמחי' בדרך מקיף, וכמו ענין השבעת השמות שפועל אך בדרך מקיף (ובפ\"א ויכול להיות בחוצפה כו'), וע\"י שמבררי' הי\"א כתרין עי\"ז ממשיכים שבחי' אנת הוא חד ולא בחושבן ואנת הוא דאפיקת כו' הם שלא בערך וגורמים שבחי' חד יומשך בע\"ס. ולפ\"ז ניחא הב' מדרשות דמ\"ש כי ציד בפיו איך מעשרין את התבן כו' היינו מצד המקיף שהוא קדושה [דרישא דעשו שהוא המקיף הוא בעיטפא דיצחק שהוא סוספיתא דדהבא סיום הגבו'] אך בפנימיות הוא רע. אך צ\"ל למה נבראו וצריכים לברר אותם והי' להם לא להבראות בתחילה (ובפ\"א דאחר שנבראו צריכים לברר אותם אך למה נבראו), וכמו\"כ כשמלאכים בקשו תורה א\"ל כלום יצה\"ר יש בכם משמע דהוא כדי לברר יצה\"ר למה נברא.\n<b>והענין</b> דהנה כתי' לויתן זה יצרת לשחק בו<sup data-n=\"851\">8</sup> ואמרז\"ל ג' שעות הראשונות הקב\"ה יושב ועוסק בתורה שניות יושב ודן שלישיות יושב וזן רביעיות יושב ומשחק עם לויתן, וג' שעות רביעיות הם בזמן תפלת מנחה (די\"ב שעות היום וג' שעות רביעיות הם זמן כו') שתיקן יצחק, דהנה יצחק הוא ע\"ש צחוק עשה לי אלקי',",[["849","6","<b>אך בקדושה הם ע\"ס ובלעו\"ז י\"א</b>: ראה בכ\"ז גם ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370020\" data-slug=\"torah-or\" data-id=\"3901370020\">תו\"א בראשית ה, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381159\" data-slug=\"likkutei-torah\" data-id=\"4001381159\">לקו\"ת שה\"ש ז, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381170\" data-slug=\"likkutei-torah\" data-id=\"4001381170\">י, ב</a>. ס' מאמרי אדהאמ\"צ דברים ח\"ג ע' א'קטז (ובהמ\"מ שם). סה\"מ תרכ\"ז ע' שע. תרל\"ב ח\"א ע' קנו. שיא ואילך. ח\"ב ע' תקנ. תקעט. תקפג. תרלה. ובכ\"מ."],["850","7","<b>וזהו לבונה זכה שרשו ז\"ך הם ך\"ז אותיות</b>: ראה אוה\"ת וארא (כרך ז) ע' ב'תקסח."],["851","8","<b>והענין דהנה כתי' לויתן זה יצרת לשחק בו</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370084\" data-slug=\"torah-or\" data-id=\"3901370084\">תו\"א תולדות יז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380151\" data-slug=\"likkutei-torah\" data-id=\"4001380151\">לקו\"ת שמיני יח, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380690\" data-slug=\"likkutei-torah\" data-id=\"4001380690\">פינחס עז, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381238\" data-slug=\"likkutei-torah\" data-id=\"4001381238\">מסעי צא, ג</a>. שה\"ש כז, ב. ס' מאמרי אדה\"ז על מארז\"ל ע' קמג. סה\"מ תרל\"ג ח\"א ס\"ע עדר."]]]]});
